  ('hsr-lc-22006', 'honkai-star-rail', 'Volando hacia un mañana rosado', 'Fly Into a Pink Tomorrow', '4', 'Memoria', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/22006.png', 'Una suave brisa dispersa las nubes y revela la apariencia del cosmos.
El resplandor dorado brilla y las epopeyas se transmiten en el cielo estrellado.
"¡Estrellas fugaces, encuentro, promesa!".
El hada mira al cielo, como la primera vez, como si fuera un reencuentro.
"Mem, espera. ¡Trazar caminos, mundo!".
Los ojos del hada se iluminan con la luz de las estrellas y brillan como ese mañana rosado.', 847, 476, 397, 'Mirada fija', '["El Daño CRIT del portador aumenta en un 12%. Cuando lo equipa {F#la}{M#el} Trazacaminos (Reminiscencia), el daño que infligen todos los aliados aumenta en un 8% y el daño que inflige el ATQ básico potenciado \"¡Escribamos el mañana!\" aumenta en un 60%.","El Daño CRIT del portador aumenta en un 15%. Cuando lo equipa {F#la}{M#el} Trazacaminos (Reminiscencia), el daño que infligen todos los aliados aumenta en un 10% y el daño que inflige el ATQ básico potenciado \"¡Escribamos el mañana!\" aumenta en un 70%.","El Daño CRIT del portador aumenta en un 18%. Cuando lo equipa {F#la}{M#el} Trazacaminos (Reminiscencia), el daño que infligen todos los aliados aumenta en un 12% y el daño que inflige el ATQ básico potenciado \"¡Escribamos el mañana!\" aumenta en un 80%.","El Daño CRIT del portador aumenta en un 21%. Cuando lo equipa {F#la}{M#el} Trazacaminos (Reminiscencia), el daño que infligen todos los aliados aumenta en un 14% y el daño que inflige el ATQ básico potenciado \"¡Escribamos el mañana!\" aumenta en un 90%.","El Daño CRIT del portador aumenta en un 24%. Cuando lo equipa {F#la}{M#el} Trazacaminos (Reminiscencia), el daño que infligen todos los aliados aumenta en un 16% y el daño que inflige el ATQ básico potenciado \"¡Escribamos el mañana!\" aumenta en un 100%."]'::jsonb, 'Recompensa permanente · Para superponerlo se usa «Flawed Recollection» en vez de otra copia del cono', '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"nombre":"Augurio etéreo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115011.png","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"nombre":"Semilla de la reflexión","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110251.png","cantidad":3},{"nombre":"Augurio etéreo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115011.png","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"nombre":"Brote de manas","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110252.png","cantidad":3},{"nombre":"Gemido resonante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115012.png","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"nombre":"Brote de manas","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110252.png","cantidad":6},{"nombre":"Gemido resonante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115012.png","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"nombre":"Alayawah","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110253.png","cantidad":4},{"nombre":"Lamento eterno","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115013.png","cantidad":5}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"nombre":"Alayawah","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110253.png","cantidad":8},{"nombre":"Lamento eterno","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115013.png","cantidad":7}]}]'::jsonb),
  ('hsr-lc-22007', 'honkai-star-rail', 'Juntos hacia el futuro', 'Tomorrow, Together', '4', 'Exultación', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/22007.png', 'Un gran regalo cae de repente en el canal.
"¡Es un pastel del tercer aniversario hecho especialmente para todos por los fans!".
Todos los momentos del pasado se convierten ahora en motivación y guían a todos juntos hacia el futuro.
"¡Espero que en este nuevo año todos avancemos felices y a salvo!".
"¡Tranquilo, revisor, yo, Liebre de Marzo, inmortalizaré este momento!".
En un ambiente cálido, todos alzan sus copas al mismo tiempo y las risas y la alegría llenan cada rincón.
"En este día de celebración, alcemos las copas".
"Por un mañana de luna y estrellas...".
"¡Salud!".', 953, 476, 331, 'Compañeros', '["El Daño CRIT del portador aumenta en un 12%. Después de que el portador lance la habilidad definitiva, la Exultación de todos los aliados aumenta en un 8% durante 1 turno.","El Daño CRIT del portador aumenta en un 15%. Después de que el portador lance la habilidad definitiva, la Exultación de todos los aliados aumenta en un 9% durante 1 turno.","El Daño CRIT del portador aumenta en un 18%. Después de que el portador lance la habilidad definitiva, la Exultación de todos los aliados aumenta en un 10% durante 1 turno.","El Daño CRIT del portador aumenta en un 21%. Después de que el portador lance la habilidad definitiva, la Exultación de todos los aliados aumenta en un 11% durante 1 turno.","El Daño CRIT del portador aumenta en un 24%. Después de que el portador lance la habilidad definitiva, la Exultación de todos los aliados aumenta en un 12% durante 1 turno."]'::jsonb, 'Recompensa del evento «Cosmic Data Roaming» · Para superponerlo se usa «Commemorative Cartridge» en vez de otra copia del cono', '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"nombre":"Crayón de la inocencia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116001.png","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"nombre":"Guion gráfico hecho a mano de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110261.png","cantidad":3},{"nombre":"Crayón de la inocencia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116001.png","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"nombre":"Edición conmemorativa de la serialización de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110262.png","cantidad":3},{"nombre":"Pluma creasueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116002.png","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"nombre":"Edición conmemorativa de la serialización de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110262.png","cantidad":6},{"nombre":"Pluma creasueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116002.png","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"nombre":"Edición de coleccionista de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110263.png","cantidad":4},{"nombre":"Pincel de los sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116003.png","cantidad":5}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"nombre":"Edición de coleccionista de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110263.png","cantidad":8},{"nombre":"Pincel de los sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116003.png","cantidad":7}]}]'::jsonb),
  ('hsr-lc-22008', 'honkai-star-rail', 'Hacia el final del horizonte', 'Race to the Horizon', '4', 'Cacería', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/22008.png', '"¡El equipo Trazacaminos va en cabeza! La meta está muy cerca, ¿podrá el equipo Trazacaminos alzarse con la victoria final?".
En la pista, donde se fijan todas las miradas, se entrelazan el rugido de los motores y los vítores de la multitud.
"¡Mantén la velocidad y sigue adelante, Mapache del Bate, seguro que puedes!".
Una voz en su interior, firme y poderosa, le infunde ánimos.
Justo antes de cruzar la meta, el sonido de los latidos, del viento, de los vítores y de la aceleración del sprint final se sintonizan en la misma frecuencia y se desvanecen en el silencio.
Y en los ojos del piloto solo queda una amplia pista que se extiende hacia el cielo.
De repente, resuenan salvas y aplausos atronadores.
"¡He... ganado! ¡El equipo Trazacaminos ha ganado!".
A medida que el resplandor del atardecer baña el horizonte, se desata la celebración de la victoria.', 847, 476, 397, 'Adelantamiento', '["El ATQ del portador aumenta en un 12%. Después de que el portador lance un ataque adicional, su Daño CRIT aumenta en un 3.0%. Este efecto dura 2 turnos y se puede acumular hasta 10 veces.","El ATQ del portador aumenta en un 15%. Después de que el portador lance un ataque adicional, su Daño CRIT aumenta en un 3.5%. Este efecto dura 2 turnos y se puede acumular hasta 10 veces.","El ATQ del portador aumenta en un 18%. Después de que el portador lance un ataque adicional, su Daño CRIT aumenta en un 4.0%. Este efecto dura 2 turnos y se puede acumular hasta 10 veces.","El ATQ del portador aumenta en un 21%. Después de que el portador lance un ataque adicional, su Daño CRIT aumenta en un 4.5%. Este efecto dura 2 turnos y se puede acumular hasta 10 veces.","El ATQ del portador aumenta en un 24%. Después de que el portador lance un ataque adicional, su Daño CRIT aumenta en un 5.0%. Este efecto dura 2 turnos y se puede acumular hasta 10 veces."]'::jsonb, 'Recompensa del evento «Overdrive: Whirlwind Grand Prix» · Para superponerlo se usa «Celebration Champagne» en vez de otra copia del cono', '[{"desde":20,"hasta":30,"creditos":4000,"materiales":[{"nombre":"Crayón de la inocencia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116001.png","cantidad":5}]},{"desde":30,"hasta":40,"creditos":8000,"materiales":[{"nombre":"Perdigón meteórico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110191.png","cantidad":3},{"nombre":"Crayón de la inocencia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116001.png","cantidad":10}]},{"desde":40,"hasta":50,"creditos":16000,"materiales":[{"nombre":"Deceso predestinado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110192.png","cantidad":3},{"nombre":"Pluma creasueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116002.png","cantidad":6}]},{"desde":50,"hasta":60,"creditos":40000,"materiales":[{"nombre":"Deceso predestinado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110192.png","cantidad":6},{"nombre":"Pluma creasueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116002.png","cantidad":9}]},{"desde":60,"hasta":70,"creditos":80000,"materiales":[{"nombre":"Disparo antitemporal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110193.png","cantidad":4},{"nombre":"Pincel de los sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116003.png","cantidad":5}]},{"desde":70,"hasta":80,"creditos":160000,"materiales":[{"nombre":"Disparo antitemporal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110193.png","cantidad":8},{"nombre":"Pincel de los sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116003.png","cantidad":7}]}]'::jsonb),
  ('hsr-lc-23000', 'honkai-star-rail', 'Noche en la Vía Láctea', 'Night on the Milky Way', '5', 'Erudición', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23000.png', 'Si te preocupa el estado del camino, mira al frente de nuevo.
Cuando las estrellas nos contemplan, el corazón ya vuela en el viento.
Cada pensamiento, cada susurro,
se convierte en una experiencia vital que nunca se irá.', 1164, 582, 397, 'Lluvia de meteoros', '["Por cada enemigo que haya en el campo de batalla, el ATQ del portador aumenta en un 9.0%. Este efecto se puede acumular hasta 5 veces. Si algún enemigo es afectado por Ruptura de Debilidad, el daño que inflige el portador aumenta en un 30% durante 1 turno.","Por cada enemigo que haya en el campo de batalla, el ATQ del portador aumenta en un 10.5%. Este efecto se puede acumular hasta 5 veces. Si algún enemigo es afectado por Ruptura de Debilidad, el daño que inflige el portador aumenta en un 35% durante 1 turno.","Por cada enemigo que haya en el campo de batalla, el ATQ del portador aumenta en un 12.0%. Este efecto se puede acumular hasta 5 veces. Si algún enemigo es afectado por Ruptura de Debilidad, el daño que inflige el portador aumenta en un 40% durante 1 turno.","Por cada enemigo que haya en el campo de batalla, el ATQ del portador aumenta en un 13.5%. Este efecto se puede acumular hasta 5 veces. Si algún enemigo es afectado por Ruptura de Debilidad, el daño que inflige el portador aumenta en un 45% durante 1 turno.","Por cada enemigo que haya en el campo de batalla, el ATQ del portador aumenta en un 15.0%. Este efecto se puede acumular hasta 5 veces. Si algún enemigo es afectado por Ruptura de Debilidad, el daño que inflige el portador aumenta en un 50% durante 1 turno."]'::jsonb, 'Tirando en el banner permanente · Tirando en los banners de conos de luz del evento · Se vende en tiendas del juego · Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Núcleo apagado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Llave de la inspiración","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110131.png","cantidad":4},{"nombre":"Núcleo apagado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Llave del conocimiento","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110132.png","cantidad":4},{"nombre":"Núcleo reluciente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Llave del conocimiento","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110132.png","cantidad":8},{"nombre":"Núcleo reluciente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Llave de la sabiduría","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110133.png","cantidad":5},{"nombre":"Núcleo serpenteante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Llave de la sabiduría","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110133.png","cantidad":10},{"nombre":"Núcleo serpenteante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23001', 'honkai-star-rail', 'En la noche', 'In the Night', '5', 'Cacería', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23001.png', 'La joven sonríe sutilmente.
"¿Por qué?".
"Es obvio que estoy sola, en este momento y en este lugar...".
"Pero se siente... muy animado".', 1058, 582, 463, 'Flores y mariposas', '["La Prob. CRIT del portador aumenta en un 18%. Cuando el portador tenga más de 100 pts. de VEL durante la batalla, por cada 10 pts. adicionales de VEL el daño que infligen su ATQ básico y habilidad básica aumenta en un 6% y el Daño CRIT de su habilidad definitiva aumenta en un 12%. Este efecto se puede acumular hasta 6 veces.","La Prob. CRIT del portador aumenta en un 21%. Cuando el portador tenga más de 100 pts. de VEL durante la batalla, por cada 10 pts. adicionales de VEL el daño que infligen su ATQ básico y habilidad básica aumenta en un 7% y el Daño CRIT de su habilidad definitiva aumenta en un 14%. Este efecto se puede acumular hasta 6 veces.","La Prob. CRIT del portador aumenta en un 24%. Cuando el portador tenga más de 100 pts. de VEL durante la batalla, por cada 10 pts. adicionales de VEL el daño que infligen su ATQ básico y habilidad básica aumenta en un 8% y el Daño CRIT de su habilidad definitiva aumenta en un 16%. Este efecto se puede acumular hasta 6 veces.","La Prob. CRIT del portador aumenta en un 27%. Cuando el portador tenga más de 100 pts. de VEL durante la batalla, por cada 10 pts. adicionales de VEL el daño que infligen su ATQ básico y habilidad básica aumenta en un 9% y el Daño CRIT de su habilidad definitiva aumenta en un 18%. Este efecto se puede acumular hasta 6 veces.","La Prob. CRIT del portador aumenta en un 30%. Cuando el portador tenga más de 100 pts. de VEL durante la batalla, por cada 10 pts. adicionales de VEL el daño que infligen su ATQ básico y habilidad básica aumenta en un 10% y el Daño CRIT de su habilidad definitiva aumenta en un 20%. Este efecto se puede acumular hasta 6 veces."]'::jsonb, 'Se vende en tiendas del juego · Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Instinto del ladrón","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111011.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Flecha del cazabestias","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110121.png","cantidad":4},{"nombre":"Instinto del ladrón","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111011.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Flecha del matademonios","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110122.png","cantidad":4},{"nombre":"Ambición distorsionada","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111012.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Flecha del matademonios","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110122.png","cantidad":8},{"nombre":"Ambición distorsionada","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111012.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Flecha del persigueestrellas","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110123.png","cantidad":5},{"nombre":"Voluntad de conquista","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111013.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Flecha del persigueestrellas","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110123.png","cantidad":10},{"nombre":"Voluntad de conquista","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111013.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23002', 'honkai-star-rail', 'Algo insustituible', 'Something Irreplaceable', '5', 'Destrucción', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23002.png', '"Svarog, si algún día yo no estoy, tendrás que hacerte cargo de la base de datos".
(¿Quién es? ¿Por qué hay un mensaje así en mis registros?).
"Svarog, ¿hay algo que sea insustituible para ti?".
(¿Insustituible?... Las piezas que se rompen se sustituyen y ya está...).
"Svarog, algún día lo encontrarás".
(Esas cosas... solo traerán problemas...).
"Cuando llegue ese momento, vete de aquí".', 1164, 582, 397, 'Familia', '["El ATQ del portador aumenta en un 24%. Cuando el portador elimina a un enemigo o recibe un ataque, regenera PV equivalentes al 8% de su ATQ y el daño que inflige aumenta en un 24% hasta que termine su siguiente turno. Este efecto no se puede acumular y solo se puede activar una vez en cada turno.","El ATQ del portador aumenta en un 28%. Cuando el portador elimina a un enemigo o recibe un ataque, regenera PV equivalentes al 9% de su ATQ y el daño que inflige aumenta en un 28% hasta que termine su siguiente turno. Este efecto no se puede acumular y solo se puede activar una vez en cada turno.","El ATQ del portador aumenta en un 32%. Cuando el portador elimina a un enemigo o recibe un ataque, regenera PV equivalentes al 10% de su ATQ y el daño que inflige aumenta en un 32% hasta que termine su siguiente turno. Este efecto no se puede acumular y solo se puede activar una vez en cada turno.","El ATQ del portador aumenta en un 36%. Cuando el portador elimina a un enemigo o recibe un ataque, regenera PV equivalentes al 11% de su ATQ y el daño que inflige aumenta en un 36% hasta que termine su siguiente turno. Este efecto no se puede acumular y solo se puede activar una vez en cada turno.","El ATQ del portador aumenta en un 40%. Cuando el portador elimina a un enemigo o recibe un ataque, regenera PV equivalentes al 12% de su ATQ y el daño que inflige aumenta en un 40% hasta que termine su siguiente turno. Este efecto no se puede acumular y solo se puede activar una vez en cada turno."]'::jsonb, 'Tirando en el banner permanente · Tirando en los banners de conos de luz del evento · Se vende en tiendas del juego · Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Componente antiguo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112011.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Espada rota","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110111.png","cantidad":4},{"nombre":"Componente antiguo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112011.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Espada inerte","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110112.png","cantidad":4},{"nombre":"Eje antiguo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112012.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Espada inerte","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110112.png","cantidad":8},{"nombre":"Eje antiguo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112012.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Espada rompemundos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110113.png","cantidad":5},{"nombre":"Motor antiguo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112013.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Espada rompemundos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110113.png","cantidad":10},{"nombre":"Motor antiguo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112013.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23003', 'honkai-star-rail', 'La batalla no ha terminado', 'But the Battle Isn''t Over', '5', 'Armonía', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23003.png', '"Recuerden, la guerra contra esos monstruos no se puede ganar retirándose".
"Detrás de nosotros está Belobog, somos la última línea de defensa...".
"¡No podemos retirarnos bajo ninguna circunstancia!".
Levantó la cabeza y miró la tierra helada y el invierno interminable.
Otro día normal.
Lo único diferente era que la espalda que solía contemplar ya no estaba.', 1164, 529, 463, 'Sucesión', '["El portador aumenta su recuperación de energía en un 10% y recupera 1 pt. de habilidad básica cuando utiliza la habilidad definitiva sobre un objetivo aliado. Este efecto se puede activar después de usar la habilidad definitiva 2 veces. Cuando el portador utiliza su habilidad básica, el daño que inflige el siguiente aliado que actúe (que no sea el portador) aumenta en un 30% durante 1 turno.","El portador aumenta su recuperación de energía en un 12% y recupera 1 pt. de habilidad básica cuando utiliza la habilidad definitiva sobre un objetivo aliado. Este efecto se puede activar después de usar la habilidad definitiva 2 veces. Cuando el portador utiliza su habilidad básica, el daño que inflige el siguiente aliado que actúe (que no sea el portador) aumenta en un 35% durante 1 turno.","El portador aumenta su recuperación de energía en un 14% y recupera 1 pt. de habilidad básica cuando utiliza la habilidad definitiva sobre un objetivo aliado. Este efecto se puede activar después de usar la habilidad definitiva 2 veces. Cuando el portador utiliza su habilidad básica, el daño que inflige el siguiente aliado que actúe (que no sea el portador) aumenta en un 40% durante 1 turno.","El portador aumenta su recuperación de energía en un 16% y recupera 1 pt. de habilidad básica cuando utiliza la habilidad definitiva sobre un objetivo aliado. Este efecto se puede activar después de usar la habilidad definitiva 2 veces. Cuando el portador utiliza su habilidad básica, el daño que inflige el siguiente aliado que actúe (que no sea el portador) aumenta en un 45% durante 1 turno.","El portador aumenta su recuperación de energía en un 18% y recupera 1 pt. de habilidad básica cuando utiliza la habilidad definitiva sobre un objetivo aliado. Este efecto se puede activar después de usar la habilidad definitiva 2 veces. Cuando el portador utiliza su habilidad básica, el daño que inflige el siguiente aliado que actúe (que no sea el portador) aumenta en un 50% durante 1 turno."]'::jsonb, 'Tirando en el banner permanente · Tirando en los banners de conos de luz del evento · Se vende en tiendas del juego · Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Pin del guardia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Melodía armónica","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110161.png","cantidad":4},{"nombre":"Pin del guardia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Himno del acervo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110162.png","cantidad":4},{"nombre":"Insignia del guardia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Himno del acervo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110162.png","cantidad":8},{"nombre":"Insignia del guardia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Opus Stellaris","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110163.png","cantidad":5},{"nombre":"Medalla del guardia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Opus Stellaris","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110163.png","cantidad":10},{"nombre":"Medalla del guardia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23004', 'honkai-star-rail', 'En nombre del mundo', 'In the Name of the World', '5', 'Nihilidad', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23004.png', '"¿Welt?".
"Es un buen nombre, ¿verdad?".
"Entonces...".
"A partir de ahora, serás Welt".
"Este núcleo de Herrscher... y la misión de proteger el mundo...".
"Ahora son tuyos, Welt".', 1058, 582, 463, 'Herencia', '["El portador inflige un 24% más de daño a los enemigos afectados por estados negativos. Cuando el portador usa su habilidad básica, su acierto de efecto en ese ataque aumenta en un 18% y su ATQ en un 24%.","El portador inflige un 28% más de daño a los enemigos afectados por estados negativos. Cuando el portador usa su habilidad básica, su acierto de efecto en ese ataque aumenta en un 21% y su ATQ en un 28%.","El portador inflige un 32% más de daño a los enemigos afectados por estados negativos. Cuando el portador usa su habilidad básica, su acierto de efecto en ese ataque aumenta en un 24% y su ATQ en un 32%.","El portador inflige un 36% más de daño a los enemigos afectados por estados negativos. Cuando el portador usa su habilidad básica, su acierto de efecto en ese ataque aumenta en un 27% y su ATQ en un 36%.","El portador inflige un 40% más de daño a los enemigos afectados por estados negativos. Cuando el portador usa su habilidad básica, su acierto de efecto en ese ataque aumenta en un 30% y su ATQ en un 40%."]'::jsonb, 'Tirando en el banner permanente · Tirando en los banners de conos de luz del evento · Se vende en tiendas del juego · Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Pin del guardia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Obsidiana lúgubre","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110151.png","cantidad":4},{"nombre":"Pin del guardia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Obsidiana del vacío","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110152.png","cantidad":4},{"nombre":"Insignia del guardia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Obsidiana del vacío","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110152.png","cantidad":8},{"nombre":"Insignia del guardia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Obsidiana de la obsesión","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110153.png","cantidad":5},{"nombre":"Medalla del guardia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Obsidiana de la obsesión","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110153.png","cantidad":10},{"nombre":"Medalla del guardia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23005', 'honkai-star-rail', 'El momento de la victoria', 'Moment of Victory', '5', 'Conservación', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23005.png', '"Gepard, si quieres llorar cuando pierdas, hazlo".
"Pero tienes que volver a levantarte hasta que puedas ganarme... aunque tardes cinco o diez años".
Varios años después, el niño ya no lloraba ni perdía ante su hermana mayor.
Hoy en día, y sin importar cuál sea la situación en el campo de batalla, el intrépido capitán de la Guardia Crinargenta se mantiene firme hasta el final...
Para encontrar el momento exacto en el que aplastará a sus enemigos.', 1058, 476, 595, 'Veredicto', '["La DEF del portador aumenta en un 24% y su acierto de efecto en un 24%. Incrementa la probabilidad de recibir ataques enemigos. Cuando el portador recibe un ataque, su DEF aumenta en un 24% adicional hasta el final de su turno.","La DEF del portador aumenta en un 28% y su acierto de efecto en un 28%. Incrementa la probabilidad de recibir ataques enemigos. Cuando el portador recibe un ataque, su DEF aumenta en un 28% adicional hasta el final de su turno.","La DEF del portador aumenta en un 32% y su acierto de efecto en un 32%. Incrementa la probabilidad de recibir ataques enemigos. Cuando el portador recibe un ataque, su DEF aumenta en un 32% adicional hasta el final de su turno.","La DEF del portador aumenta en un 36% y su acierto de efecto en un 36%. Incrementa la probabilidad de recibir ataques enemigos. Cuando el portador recibe un ataque, su DEF aumenta en un 36% adicional hasta el final de su turno.","La DEF del portador aumenta en un 40% y su acierto de efecto en un 40%. Incrementa la probabilidad de recibir ataques enemigos. Cuando el portador recibe un ataque, su DEF aumenta en un 40% adicional hasta el final de su turno."]'::jsonb, 'Tirando en el banner permanente · Tirando en los banners de conos de luz del evento · Se vende en tiendas del juego · Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Pin del guardia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Persistencia del bronce","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110141.png","cantidad":4},{"nombre":"Pin del guardia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Juramento de acero","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110142.png","cantidad":4},{"nombre":"Insignia del guardia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Juramento de acero","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110142.png","cantidad":8},{"nombre":"Insignia del guardia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Custodia de ámbar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110143.png","cantidad":5},{"nombre":"Medalla del guardia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Custodia de ámbar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110143.png","cantidad":10},{"nombre":"Medalla del guardia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23006', 'honkai-star-rail', 'Solo hay que esperar', 'Patience Is All You Need', '5', 'Nihilidad', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23006.png', '"¿Acaso hay algo que no me has contado?".
Vio cómo su interlocutor tensaba el cuello y oyó cómo tragaba saliva.
Ese hombre le tenía miedo, así que ni siquiera tenía que usar sus poderes.
En realidad, no importaba lo que ella dijera.
Cualquier palabra que saliera de su boca serviría para que el miedo comenzara a fermentar...
Su interlocutor entraría en pánico inmediatamente y diría todo lo que ella quería oír.
Solo necesitaba esperar, igual que una araña que ya ha extendido su tela.', 1058, 582, 463, 'Telaraña', '["El daño que inflige el portador aumenta en un 24%. Después de cada ataque del portador, su VEL aumenta en un 4.8%. Este efecto se puede acumular hasta 3 veces.\nCuando el portador golpea a un objetivo, si este no está afectado por Erosión, hay un 100% de probabilidad base de afectarlo con Erosión. Cuando el objetivo está afectado por Erosión, se considera que también está afectado por Electrocución. En el estado de Erosión, al comienzo de cada turno el objetivo recibe un Daño de Rayo con el tiempo equivalente al 60% del ATQ del portador durante 1 turno.","El daño que inflige el portador aumenta en un 28%. Después de cada ataque del portador, su VEL aumenta en un 5.6%. Este efecto se puede acumular hasta 3 veces.\nCuando el portador golpea a un objetivo, si este no está afectado por Erosión, hay un 100% de probabilidad base de afectarlo con Erosión. Cuando el objetivo está afectado por Erosión, se considera que también está afectado por Electrocución. En el estado de Erosión, al comienzo de cada turno el objetivo recibe un Daño de Rayo con el tiempo equivalente al 70% del ATQ del portador durante 1 turno.","El daño que inflige el portador aumenta en un 32%. Después de cada ataque del portador, su VEL aumenta en un 6.4%. Este efecto se puede acumular hasta 3 veces.\nCuando el portador golpea a un objetivo, si este no está afectado por Erosión, hay un 100% de probabilidad base de afectarlo con Erosión. Cuando el objetivo está afectado por Erosión, se considera que también está afectado por Electrocución. En el estado de Erosión, al comienzo de cada turno el objetivo recibe un Daño de Rayo con el tiempo equivalente al 80% del ATQ del portador durante 1 turno.","El daño que inflige el portador aumenta en un 36%. Después de cada ataque del portador, su VEL aumenta en un 7.2%. Este efecto se puede acumular hasta 3 veces.\nCuando el portador golpea a un objetivo, si este no está afectado por Erosión, hay un 100% de probabilidad base de afectarlo con Erosión. Cuando el objetivo está afectado por Erosión, se considera que también está afectado por Electrocución. En el estado de Erosión, al comienzo de cada turno el objetivo recibe un Daño de Rayo con el tiempo equivalente al 90% del ATQ del portador durante 1 turno.","El daño que inflige el portador aumenta en un 40%. Después de cada ataque del portador, su VEL aumenta en un 8.0%. Este efecto se puede acumular hasta 3 veces.\nCuando el portador golpea a un objetivo, si este no está afectado por Erosión, hay un 100% de probabilidad base de afectarlo con Erosión. Cuando el objetivo está afectado por Erosión, se considera que también está afectado por Electrocución. En el estado de Erosión, al comienzo de cada turno el objetivo recibe un Daño de Rayo con el tiempo equivalente al 100% del ATQ del portador durante 1 turno."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Instinto del ladrón","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111011.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Obsidiana lúgubre","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110151.png","cantidad":4},{"nombre":"Instinto del ladrón","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111011.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Obsidiana del vacío","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110152.png","cantidad":4},{"nombre":"Ambición distorsionada","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111012.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Obsidiana del vacío","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110152.png","cantidad":8},{"nombre":"Ambición distorsionada","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111012.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Obsidiana de la obsesión","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110153.png","cantidad":5},{"nombre":"Voluntad de conquista","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111013.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Obsidiana de la obsesión","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110153.png","cantidad":10},{"nombre":"Voluntad de conquista","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111013.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23007', 'honkai-star-rail', 'Lluvia incesante', 'Incessant Rain', '5', 'Nihilidad', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23007.png', 'Salió de debajo del alero de la casa, abrió su paraguas y se dirigió tarareando hacia la esquina del callejón.
Poco después dejó de llover.
Se rascó la cabeza, deslizó la pantalla y la lluvia volvió a colarse por el pequeño espacio que había encima de su cabeza.
Al escuchar la lluvia repiqueteando en el paraguas, como acompañamiento de los efectos de sonido del juego, se puso de muy buen humor.
"Los días de lluvia son los más apropiados para jugar".', 1058, 582, 463, 'Espejismo de la realidad', '["El acierto de efecto del portador aumenta en un 24%. Cuando el portador inflige daño a un enemigo que tenga 3 o más estados negativos, su Prob. CRIT aumenta en un 12%. Después de usar el ATQ básico, la habilidad básica o la habilidad definitiva, el portador tiene un 100% de probabilidad base de aplicar Código de éter a 1 objetivo al azar de los golpeados que no lo tenga ya aplicado. El daño que reciben los enemigos con Código de éter aumenta en un 12% durante 1 turno.","El acierto de efecto del portador aumenta en un 28%. Cuando el portador inflige daño a un enemigo que tenga 3 o más estados negativos, su Prob. CRIT aumenta en un 14%. Después de usar el ATQ básico, la habilidad básica o la habilidad definitiva, el portador tiene un 100% de probabilidad base de aplicar Código de éter a 1 objetivo al azar de los golpeados que no lo tenga ya aplicado. El daño que reciben los enemigos con Código de éter aumenta en un 14% durante 1 turno.","El acierto de efecto del portador aumenta en un 32%. Cuando el portador inflige daño a un enemigo que tenga 3 o más estados negativos, su Prob. CRIT aumenta en un 16%. Después de usar el ATQ básico, la habilidad básica o la habilidad definitiva, el portador tiene un 100% de probabilidad base de aplicar Código de éter a 1 objetivo al azar de los golpeados que no lo tenga ya aplicado. El daño que reciben los enemigos con Código de éter aumenta en un 16% durante 1 turno.","El acierto de efecto del portador aumenta en un 36%. Cuando el portador inflige daño a un enemigo que tenga 3 o más estados negativos, su Prob. CRIT aumenta en un 18%. Después de usar el ATQ básico, la habilidad básica o la habilidad definitiva, el portador tiene un 100% de probabilidad base de aplicar Código de éter a 1 objetivo al azar de los golpeados que no lo tenga ya aplicado. El daño que reciben los enemigos con Código de éter aumenta en un 18% durante 1 turno.","El acierto de efecto del portador aumenta en un 40%. Cuando el portador inflige daño a un enemigo que tenga 3 o más estados negativos, su Prob. CRIT aumenta en un 20%. Después de usar el ATQ básico, la habilidad básica o la habilidad definitiva, el portador tiene un 100% de probabilidad base de aplicar Código de éter a 1 objetivo al azar de los golpeados que no lo tenga ya aplicado. El daño que reciben los enemigos con Código de éter aumenta en un 20% durante 1 turno."]'::jsonb, 'Se vende en tiendas del juego · Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Componente antiguo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112011.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Obsidiana lúgubre","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110151.png","cantidad":4},{"nombre":"Componente antiguo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112011.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Obsidiana del vacío","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110152.png","cantidad":4},{"nombre":"Eje antiguo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112012.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Obsidiana del vacío","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110152.png","cantidad":8},{"nombre":"Eje antiguo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112012.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Obsidiana de la obsesión","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110153.png","cantidad":5},{"nombre":"Motor antiguo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112013.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Obsidiana de la obsesión","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110153.png","cantidad":10},{"nombre":"Motor antiguo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112013.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23008', 'honkai-star-rail', 'Ecos del ataúd', 'Echoes of the Coffin', '5', 'Abundancia', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23008.png', 'El hombre golpeó el ataúd al lado de los lirios blancos.
"A veces pienso que te subestimé al hacer este trato contigo".
No hubo respuesta más allá de las espinas que atravesaban la palma de su mano.
Pero él sonrió y cerró el puño.
"Así que era eso. Los dos queríamos aprovecharnos el uno del otro, pero subestimamos a nuestro rival".', 1164, 582, 397, 'Espinas', '["El ATQ del portador aumenta en un 24%. Después de que el portador lance un ataque, por cada enemigo distinto golpeado, recupera 3.0 pts. de energía. Cada ataque puede recuperar energía de esta manera hasta 3 veces. Después de que el portador use la habilidad definitiva, la VEL de todos los aliados aumenta en 12 pts. durante 1 turno.","El ATQ del portador aumenta en un 28%. Después de que el portador lance un ataque, por cada enemigo distinto golpeado, recupera 3.5 pts. de energía. Cada ataque puede recuperar energía de esta manera hasta 3 veces. Después de que el portador use la habilidad definitiva, la VEL de todos los aliados aumenta en 14 pts. durante 1 turno.","El ATQ del portador aumenta en un 32%. Después de que el portador lance un ataque, por cada enemigo distinto golpeado, recupera 4.0 pts. de energía. Cada ataque puede recuperar energía de esta manera hasta 3 veces. Después de que el portador use la habilidad definitiva, la VEL de todos los aliados aumenta en 16 pts. durante 1 turno.","El ATQ del portador aumenta en un 36%. Después de que el portador lance un ataque, por cada enemigo distinto golpeado, recupera 4.5 pts. de energía. Cada ataque puede recuperar energía de esta manera hasta 3 veces. Después de que el portador use la habilidad definitiva, la VEL de todos los aliados aumenta en 18 pts. durante 1 turno.","El ATQ del portador aumenta en un 40%. Después de que el portador lance un ataque, por cada enemigo distinto golpeado, recupera 5.0 pts. de energía. Cada ataque puede recuperar energía de esta manera hasta 3 veces. Después de que el portador use la habilidad definitiva, la VEL de todos los aliados aumenta en 20 pts. durante 1 turno."]'::jsonb, 'Se vende en tiendas del juego · Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Componente artificial mecánico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113011.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Semilla de la abundancia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110171.png","cantidad":4},{"nombre":"Componente artificial mecánico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113011.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Brote de la vida","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110172.png","cantidad":4},{"nombre":"Engranaje cilíndrico mecánico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113012.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Brote de la vida","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110172.png","cantidad":8},{"nombre":"Engranaje cilíndrico mecánico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113012.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Flor de la eternidad","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110173.png","cantidad":5},{"nombre":"Corazón armonioso mecánico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113013.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Flor de la eternidad","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110173.png","cantidad":10},{"nombre":"Corazón armonioso mecánico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113013.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23009', 'honkai-star-rail', 'Orilla inalcanzable', 'The Unreachable Side', '5', 'Destrucción', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23009.png', 'Cada año venía a este lugar y traía varias espadas nuevas.
Había visto con sus propios ojos la última expresión de todos y cada uno de los dueños de esas espadas.
Cada vez que se alejaba, pensaba con tristeza:
"¿Cuándo traerá alguien mi espada a este lugar?".', 1270, 582, 331, 'Anhelo insatisfecho', '["La Prob. CRIT del portador aumenta en un 18% y sus PV máx. aumentan en un 18%. Cuando el portador recibe un ataque o consume sus propios PV, el daño que inflige aumenta en un 24%. Este último efecto se elimina después de que el portador lance un ataque.","La Prob. CRIT del portador aumenta en un 21% y sus PV máx. aumentan en un 21%. Cuando el portador recibe un ataque o consume sus propios PV, el daño que inflige aumenta en un 28%. Este último efecto se elimina después de que el portador lance un ataque.","La Prob. CRIT del portador aumenta en un 24% y sus PV máx. aumentan en un 24%. Cuando el portador recibe un ataque o consume sus propios PV, el daño que inflige aumenta en un 32%. Este último efecto se elimina después de que el portador lance un ataque.","La Prob. CRIT del portador aumenta en un 27% y sus PV máx. aumentan en un 27%. Cuando el portador recibe un ataque o consume sus propios PV, el daño que inflige aumenta en un 36%. Este último efecto se elimina después de que el portador lance un ataque.","La Prob. CRIT del portador aumenta en un 30% y sus PV máx. aumentan en un 30%. Cuando el portador recibe un ataque o consume sus propios PV, el daño que inflige aumenta en un 40%. Este último efecto se elimina después de que el portador lance un ataque."]'::jsonb, 'Se vende en tiendas del juego · Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Brote verde inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Espada rota","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110111.png","cantidad":4},{"nombre":"Brote verde inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Espada inerte","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110112.png","cantidad":4},{"nombre":"Flor etérea inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Espada inerte","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110112.png","cantidad":8},{"nombre":"Flor etérea inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Espada rompemundos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110113.png","cantidad":5},{"nombre":"Rama gloriosa inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Espada rompemundos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110113.png","cantidad":10},{"nombre":"Rama gloriosa inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23010', 'honkai-star-rail', 'Antes del amanecer', 'Before Dawn', '5', 'Erudición', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23010.png', '"General, este asunto no se puede decidir a la ligera... Piense en cómo lo recordarán las generaciones venideras...".
El general de los Nimbocaballeros frunció el ceño al escuchar estas palabras.
"La historia hará su propio juicio, pero no me interesa qué opinen los demás de mí".
"Si tengo éxito, dirán que todo salió de acuerdo a mi plan maestro".
"Si fracaso, afirmarán que era un hedonista sin remedio y que no sabía distinguir los asuntos importantes".
Un pajarillo saltó desde su hombro y él levantó la mano para que se posara en ella.
"Estoy actuando de acuerdo a mi juicio".', 1058, 582, 463, 'Noche larga', '["El Daño CRIT del portador aumenta en un 36%. El daño que infligen la habilidad básica y la habilidad definitiva del portador aumenta en un 18%. Cuando el portador utiliza la habilidad básica o la habilidad definitiva, obtiene Somnus corpus. Al lanzar un ataque adicional, se consume Somnus corpus y el daño que inflige el ataque adicional aumenta en un 48%.","El Daño CRIT del portador aumenta en un 42%. El daño que infligen la habilidad básica y la habilidad definitiva del portador aumenta en un 21%. Cuando el portador utiliza la habilidad básica o la habilidad definitiva, obtiene Somnus corpus. Al lanzar un ataque adicional, se consume Somnus corpus y el daño que inflige el ataque adicional aumenta en un 56%.","El Daño CRIT del portador aumenta en un 48%. El daño que infligen la habilidad básica y la habilidad definitiva del portador aumenta en un 24%. Cuando el portador utiliza la habilidad básica o la habilidad definitiva, obtiene Somnus corpus. Al lanzar un ataque adicional, se consume Somnus corpus y el daño que inflige el ataque adicional aumenta en un 64%.","El Daño CRIT del portador aumenta en un 54%. El daño que infligen la habilidad básica y la habilidad definitiva del portador aumenta en un 27%. Cuando el portador utiliza la habilidad básica o la habilidad definitiva, obtiene Somnus corpus. Al lanzar un ataque adicional, se consume Somnus corpus y el daño que inflige el ataque adicional aumenta en un 72%.","El Daño CRIT del portador aumenta en un 60%. El daño que infligen la habilidad básica y la habilidad definitiva del portador aumenta en un 30%. Cuando el portador utiliza la habilidad básica o la habilidad definitiva, obtiene Somnus corpus. Al lanzar un ataque adicional, se consume Somnus corpus y el daño que inflige el ataque adicional aumenta en un 80%."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Brote verde inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Llave de la inspiración","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110131.png","cantidad":4},{"nombre":"Brote verde inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Llave del conocimiento","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110132.png","cantidad":4},{"nombre":"Flor etérea inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Llave del conocimiento","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110132.png","cantidad":8},{"nombre":"Flor etérea inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Llave de la sabiduría","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110133.png","cantidad":5},{"nombre":"Rama gloriosa inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Llave de la sabiduría","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110133.png","cantidad":10},{"nombre":"Rama gloriosa inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23011', 'honkai-star-rail', 'Ya ha cerrado los ojos', 'She Already Shut Her Eyes', '5', 'Conservación', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23011.png', 'El dolor en la frente la acompañará toda su vida, pero no es más que una fracción del que sufrió en el pasado.
Pensaba que podía preverlo todo, hasta que sus seres queridos se fueron.
Ahora "ve" el mundo y los tiempos que nunca dejan de cambiar...
Pero ya ha cerrado los ojos, porque el futuro ya se ha determinado... dentro del tercer ojo.', 1270, 423, 529, 'Horizonte cosmológico', '["Los PV máx. del portador aumentan en un 24% y la recuperación de energía en un 12%. Cuando se reducen los PV del portador, el daño que infligen todos los aliados aumenta en un 9.0% durante 2 turnos.\nAl comienzo de cada oleada, todos los aliados regeneran un 80% de los PV que les falten en ese momento.","Los PV máx. del portador aumentan en un 28% y la recuperación de energía en un 14%. Cuando se reducen los PV del portador, el daño que infligen todos los aliados aumenta en un 10.5% durante 2 turnos.\nAl comienzo de cada oleada, todos los aliados regeneran un 85% de los PV que les falten en ese momento.","Los PV máx. del portador aumentan en un 32% y la recuperación de energía en un 16%. Cuando se reducen los PV del portador, el daño que infligen todos los aliados aumenta en un 12.0% durante 2 turnos.\nAl comienzo de cada oleada, todos los aliados regeneran un 90% de los PV que les falten en ese momento.","Los PV máx. del portador aumentan en un 36% y la recuperación de energía en un 18%. Cuando se reducen los PV del portador, el daño que infligen todos los aliados aumenta en un 13.5% durante 2 turnos.\nAl comienzo de cada oleada, todos los aliados regeneran un 95% de los PV que les falten en ese momento.","Los PV máx. del portador aumentan en un 40% y la recuperación de energía en un 20%. Cuando se reducen los PV del portador, el daño que infligen todos los aliados aumenta en un 15.0% durante 2 turnos.\nAl comienzo de cada oleada, todos los aliados regeneran un 100% de los PV que les falten en ese momento."]'::jsonb, 'Se vende en tiendas del juego · Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Componente artificial mecánico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113011.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Persistencia del bronce","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110141.png","cantidad":4},{"nombre":"Componente artificial mecánico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113011.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Juramento de acero","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110142.png","cantidad":4},{"nombre":"Engranaje cilíndrico mecánico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113012.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Juramento de acero","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110142.png","cantidad":8},{"nombre":"Engranaje cilíndrico mecánico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113012.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Custodia de ámbar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110143.png","cantidad":5},{"nombre":"Corazón armonioso mecánico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113013.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Custodia de ámbar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110143.png","cantidad":10},{"nombre":"Corazón armonioso mecánico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113013.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23012', 'honkai-star-rail', 'Dormir como un tronco', 'Sleep Like the Dead', '5', 'Cacería', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23012.png', 'El joven sigue agarrando con fuerza la espada, incluso cuando se duerme apoyado en el hombro del general.
Este roza la mejilla del joven, quien murmura algo en sueños.
"General... por fin... gané...".
El general se queda quieto y de repente se da cuenta de que, comparado con el joven, que cada día se esfuerza por mejorar, por él ya han pasado muchos años y se ha acostumbrado a no cambiar.
"Muy pronto ganarás a todo el mundo, y eso solo será el comienzo...".', 1058, 582, 463, 'Dulces sueños', '["El Daño CRIT del portador aumenta en un 30%. Cuando el portador no causa ningún Golpe CRIT al infligir daño de ATQ básico o daño de habilidad básica, su Prob. CRIT aumenta en un 36% durante 1 turno. Este efecto se puede activar una vez cada 3 turnos.","El Daño CRIT del portador aumenta en un 35%. Cuando el portador no causa ningún Golpe CRIT al infligir daño de ATQ básico o daño de habilidad básica, su Prob. CRIT aumenta en un 42% durante 1 turno. Este efecto se puede activar una vez cada 3 turnos.","El Daño CRIT del portador aumenta en un 40%. Cuando el portador no causa ningún Golpe CRIT al infligir daño de ATQ básico o daño de habilidad básica, su Prob. CRIT aumenta en un 48% durante 1 turno. Este efecto se puede activar una vez cada 3 turnos.","El Daño CRIT del portador aumenta en un 45%. Cuando el portador no causa ningún Golpe CRIT al infligir daño de ATQ básico o daño de habilidad básica, su Prob. CRIT aumenta en un 54% durante 1 turno. Este efecto se puede activar una vez cada 3 turnos.","El Daño CRIT del portador aumenta en un 50%. Cuando el portador no causa ningún Golpe CRIT al infligir daño de ATQ básico o daño de habilidad básica, su Prob. CRIT aumenta en un 60% durante 1 turno. Este efecto se puede activar una vez cada 3 turnos."]'::jsonb, 'Tirando en el banner permanente · Tirando en los banners de conos de luz del evento · Se vende en tiendas del juego · Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Instinto del ladrón","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111011.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Flecha del cazabestias","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110121.png","cantidad":4},{"nombre":"Instinto del ladrón","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111011.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Flecha del matademonios","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110122.png","cantidad":4},{"nombre":"Ambición distorsionada","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111012.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Flecha del matademonios","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110122.png","cantidad":8},{"nombre":"Ambición distorsionada","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111012.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Flecha del persigueestrellas","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110123.png","cantidad":5},{"nombre":"Voluntad de conquista","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111013.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Flecha del persigueestrellas","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110123.png","cantidad":10},{"nombre":"Voluntad de conquista","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111013.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23013', 'honkai-star-rail', 'El tiempo no espera', 'Time Waits for No One', '5', 'Abundancia', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23013.png', 'Había pasado muchos días al lado de la ventana.
Afuera, las flores extendían orgullosamente sus pétalos mientras ella hacía remedios suaves con menta y nepeta.
La lluvia caía mientras fabricaba remedios fuertes con mosla y jengibre.
Las hojas volaban mientras hacía remedios ácidos con raíces de peonía y ciruelas secas.
La nieve caía mientras producía remedios amargos con escutelaria y anemarrena.
El tiempo nunca se detiene, pero esta ventana y la persona sentada junto a ella siguen siendo las mismas.', 1270, 476, 463, 'Mañana, tarde y noche', '["Los PV máx. del portador aumentan en un 18% y su curación realizada en un 12%. Cuando el portador cura a los aliados, se registra la curación realizada. Cuando un aliado lanza un ataque, un enemigo al azar de los atacados recibe una cantidad de daño adicional equivalente al 36% de la curación realizada que se registró para ese aliado. Este daño adicional es del mismo tipo que el del portador, no se ve afectado por otras bonificaciones y ocurre como máximo 1 vez por turno.","Los PV máx. del portador aumentan en un 21% y su curación realizada en un 14%. Cuando el portador cura a los aliados, se registra la curación realizada. Cuando un aliado lanza un ataque, un enemigo al azar de los atacados recibe una cantidad de daño adicional equivalente al 42% de la curación realizada que se registró para ese aliado. Este daño adicional es del mismo tipo que el del portador, no se ve afectado por otras bonificaciones y ocurre como máximo 1 vez por turno.","Los PV máx. del portador aumentan en un 24% y su curación realizada en un 16%. Cuando el portador cura a los aliados, se registra la curación realizada. Cuando un aliado lanza un ataque, un enemigo al azar de los atacados recibe una cantidad de daño adicional equivalente al 48% de la curación realizada que se registró para ese aliado. Este daño adicional es del mismo tipo que el del portador, no se ve afectado por otras bonificaciones y ocurre como máximo 1 vez por turno.","Los PV máx. del portador aumentan en un 27% y su curación realizada en un 18%. Cuando el portador cura a los aliados, se registra la curación realizada. Cuando un aliado lanza un ataque, un enemigo al azar de los atacados recibe una cantidad de daño adicional equivalente al 54% de la curación realizada que se registró para ese aliado. Este daño adicional es del mismo tipo que el del portador, no se ve afectado por otras bonificaciones y ocurre como máximo 1 vez por turno.","Los PV máx. del portador aumentan en un 30% y su curación realizada en un 20%. Cuando el portador cura a los aliados, se registra la curación realizada. Cuando un aliado lanza un ataque, un enemigo al azar de los atacados recibe una cantidad de daño adicional equivalente al 60% de la curación realizada que se registró para ese aliado. Este daño adicional es del mismo tipo que el del portador, no se ve afectado por otras bonificaciones y ocurre como máximo 1 vez por turno."]'::jsonb, 'Tirando en el banner permanente · Tirando en los banners de conos de luz del evento · Se vende en tiendas del juego · Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Núcleo apagado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Semilla de la abundancia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110171.png","cantidad":4},{"nombre":"Núcleo apagado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Brote de la vida","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110172.png","cantidad":4},{"nombre":"Núcleo reluciente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Brote de la vida","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110172.png","cantidad":8},{"nombre":"Núcleo reluciente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Flor de la eternidad","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110173.png","cantidad":5},{"nombre":"Núcleo serpenteante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Flor de la eternidad","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110173.png","cantidad":10},{"nombre":"Núcleo serpenteante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23014', 'honkai-star-rail', 'Yo seré mi propia espada', 'I Shall Be My Own Sword', '5', 'Destrucción', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23014.png', 'La espada destrozada se precipita en el frío que hiela los huesos.
Las armas comunes de metal son inútiles, ya que sus límites se pueden observar a simple vista.
"¿Para qué necesito una espada?".
No mantiene ningún apego, y en sus ojos no hay espacio para nada.
"A partir de ahora, yo seré mi propia espada".
La única manera de trascender los límites y llegar hasta donde nadie ha llegado antes es convertirse una misma en la "chispa".', 1164, 582, 397, 'Con este jade nocturno', '["El Daño CRIT del portador aumenta en un 20%. Cuando un aliado recibe un ataque o consume PV, el portador obtiene 1 acumulación de Eclipse. Se puede acumular hasta 3 veces. Por cada acumulación, el daño que inflige el siguiente ataque del portador aumenta en un 14.0%. Cuando se alcanzan 3 acumulaciones, el ataque actual ignora un 12% de la DEF del objetivo. Este efecto se elimina después de que el portador lance un ataque.","El Daño CRIT del portador aumenta en un 23%. Cuando un aliado recibe un ataque o consume PV, el portador obtiene 1 acumulación de Eclipse. Se puede acumular hasta 3 veces. Por cada acumulación, el daño que inflige el siguiente ataque del portador aumenta en un 16.5%. Cuando se alcanzan 3 acumulaciones, el ataque actual ignora un 14% de la DEF del objetivo. Este efecto se elimina después de que el portador lance un ataque.","El Daño CRIT del portador aumenta en un 26%. Cuando un aliado recibe un ataque o consume PV, el portador obtiene 1 acumulación de Eclipse. Se puede acumular hasta 3 veces. Por cada acumulación, el daño que inflige el siguiente ataque del portador aumenta en un 19.0%. Cuando se alcanzan 3 acumulaciones, el ataque actual ignora un 16% de la DEF del objetivo. Este efecto se elimina después de que el portador lance un ataque.","El Daño CRIT del portador aumenta en un 29%. Cuando un aliado recibe un ataque o consume PV, el portador obtiene 1 acumulación de Eclipse. Se puede acumular hasta 3 veces. Por cada acumulación, el daño que inflige el siguiente ataque del portador aumenta en un 21.5%. Cuando se alcanzan 3 acumulaciones, el ataque actual ignora un 18% de la DEF del objetivo. Este efecto se elimina después de que el portador lance un ataque.","El Daño CRIT del portador aumenta en un 32%. Cuando un aliado recibe un ataque o consume PV, el portador obtiene 1 acumulación de Eclipse. Se puede acumular hasta 3 veces. Por cada acumulación, el daño que inflige el siguiente ataque del portador aumenta en un 24.0%. Cuando se alcanzan 3 acumulaciones, el ataque actual ignora un 20% de la DEF del objetivo. Este efecto se elimina después de que el portador lance un ataque."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Brote verde inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Espada rota","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110111.png","cantidad":4},{"nombre":"Brote verde inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Espada inerte","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110112.png","cantidad":4},{"nombre":"Flor etérea inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Espada inerte","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110112.png","cantidad":8},{"nombre":"Flor etérea inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Espada rompemundos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110113.png","cantidad":5},{"nombre":"Rama gloriosa inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Espada rompemundos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110113.png","cantidad":10},{"nombre":"Rama gloriosa inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23015', 'honkai-star-rail', 'Más brillante que el sol', 'Brighter Than the Sun', '5', 'Destrucción', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23015.png', 'Desde su nacimiento, lo único que había visto era una celda oscura.
Pecados con los que no tenía relación lo ataban a ese lugar, y recuerdos con los que no tenía relación lo abrumaban.
Hacía todo lo posible por respirar e intentaba aferrarse a una grieta iluminada en el mar infinito.
Hasta que el general entró en su celda oscura y vio que la mirada del joven era más brillante que el sol.', 1058, 635, 397, 'Desafiante hasta la muerte', '["La Prob. CRIT del portador aumenta en un 18%. Cuando el portador usa el ATQ básico, obtiene 1 acumulación de Canto del dragón durante 2 turnos. Cada acumulación de Canto del dragón aumenta el ATQ del portador en un 18% y la recuperación de energía en un 6.0%. Canto del dragón se puede acumular hasta 2 veces.","La Prob. CRIT del portador aumenta en un 21%. Cuando el portador usa el ATQ básico, obtiene 1 acumulación de Canto del dragón durante 2 turnos. Cada acumulación de Canto del dragón aumenta el ATQ del portador en un 21% y la recuperación de energía en un 7.0%. Canto del dragón se puede acumular hasta 2 veces.","La Prob. CRIT del portador aumenta en un 24%. Cuando el portador usa el ATQ básico, obtiene 1 acumulación de Canto del dragón durante 2 turnos. Cada acumulación de Canto del dragón aumenta el ATQ del portador en un 24% y la recuperación de energía en un 8.0%. Canto del dragón se puede acumular hasta 2 veces.","La Prob. CRIT del portador aumenta en un 27%. Cuando el portador usa el ATQ básico, obtiene 1 acumulación de Canto del dragón durante 2 turnos. Cada acumulación de Canto del dragón aumenta el ATQ del portador en un 27% y la recuperación de energía en un 9.0%. Canto del dragón se puede acumular hasta 2 veces.","La Prob. CRIT del portador aumenta en un 30%. Cuando el portador usa el ATQ básico, obtiene 1 acumulación de Canto del dragón durante 2 turnos. Cada acumulación de Canto del dragón aumenta el ATQ del portador en un 30% y la recuperación de energía en un 10.0%. Canto del dragón se puede acumular hasta 2 veces."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Brote verde inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Espada rota","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110111.png","cantidad":4},{"nombre":"Brote verde inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Espada inerte","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110112.png","cantidad":4},{"nombre":"Flor etérea inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Espada inerte","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110112.png","cantidad":8},{"nombre":"Flor etérea inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Espada rompemundos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110113.png","cantidad":5},{"nombre":"Rama gloriosa inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Espada rompemundos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110113.png","cantidad":10},{"nombre":"Rama gloriosa inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23016', 'honkai-star-rail', 'Preocupaciones y felicidad', 'Worrisome, Blissful', '5', 'Cacería', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23016.png', 'Un empleado competente de una empresa no tiene permitido sentirse abrumado por la presión.
Ya sea estrés o cansancio, ¡uno debe ser firme y enfrentarse a las circunstancias!
A menos que sea por "ellos".
"¡Ay, no te apresures! ¡Solo tengo dos manos!".
Una joven que acaba de llegar a casa después de trabajar hasta tarde ha sido inmovilizada en el suelo por unas criaturas peludas.
Parece que no entienden lo que dice, solo acercan sus cabezas redondas hacia las manos de la joven.
Poco a poco, su cansancio se desvanece cuando acaricia su suave pelaje.', 1058, 582, 463, 'De uno en uno', '["La Prob. CRIT del portador aumenta en un 18% y el daño que infligen sus ataques adicionales aumenta en un 30%. Cuando el portador lanza un ataque adicional, afecta con Doma al objetivo. Este efecto se puede acumular hasta 2 veces. Cuando un aliado golpea a un objetivo afectado por Doma, el Daño CRIT infligido aumenta en un 12% por cada acumulación.","La Prob. CRIT del portador aumenta en un 21% y el daño que infligen sus ataques adicionales aumenta en un 35%. Cuando el portador lanza un ataque adicional, afecta con Doma al objetivo. Este efecto se puede acumular hasta 2 veces. Cuando un aliado golpea a un objetivo afectado por Doma, el Daño CRIT infligido aumenta en un 14% por cada acumulación.","La Prob. CRIT del portador aumenta en un 24% y el daño que infligen sus ataques adicionales aumenta en un 40%. Cuando el portador lanza un ataque adicional, afecta con Doma al objetivo. Este efecto se puede acumular hasta 2 veces. Cuando un aliado golpea a un objetivo afectado por Doma, el Daño CRIT infligido aumenta en un 16% por cada acumulación.","La Prob. CRIT del portador aumenta en un 27% y el daño que infligen sus ataques adicionales aumenta en un 45%. Cuando el portador lanza un ataque adicional, afecta con Doma al objetivo. Este efecto se puede acumular hasta 2 veces. Cuando un aliado golpea a un objetivo afectado por Doma, el Daño CRIT infligido aumenta en un 18% por cada acumulación.","La Prob. CRIT del portador aumenta en un 30% y el daño que infligen sus ataques adicionales aumenta en un 50%. Cuando el portador lanza un ataque adicional, afecta con Doma al objetivo. Este efecto se puede acumular hasta 2 veces. Cuando un aliado golpea a un objetivo afectado por Doma, el Daño CRIT infligido aumenta en un 20% por cada acumulación."]'::jsonb, 'Se vende en tiendas del juego · Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Pin del guardia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Flecha del cazabestias","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110121.png","cantidad":4},{"nombre":"Pin del guardia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Flecha del matademonios","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110122.png","cantidad":4},{"nombre":"Insignia del guardia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Flecha del matademonios","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110122.png","cantidad":8},{"nombre":"Insignia del guardia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Flecha del persigueestrellas","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110123.png","cantidad":5},{"nombre":"Medalla del guardia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Flecha del persigueestrellas","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110123.png","cantidad":10},{"nombre":"Medalla del guardia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/112003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23017', 'honkai-star-rail', 'Noche terrorífica', 'Night of Fright', '5', 'Abundancia', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23017.png', 'La niña se esconde detrás de la puerta y no se atreve a avanzar ni un paso más.
Tal vez porque el objetivo de esta noche está al alcance de su mano, su corazón late más fuerte.
"No tengo miedo, no tengo miedo, no tengo miedo...".
En medio de la oscuridad, el silencio suelta un grito agudo.
La niña está temblando y sostiene con fuerza el "arma" que tiene entre las manos, pero aún no se atreve a acercarse al "objetivo".
"¡N-no hay nada de lo que t-tener miedo!".
La cola que tiene detrás ya no aguanta más y se ilumina.
"¡Date prisa! ¡Solo estás recogiendo un paquete!".', 1164, 476, 529, 'Respiración profunda', '["La recuperación de energía del portador aumenta en un 12%. Cuando un aliado usa su habilidad definitiva, el portador regenera al aliado con menor porcentaje de PV una cantidad de PV equivalente al 10% de los PV máx. del objetivo. Cuando el portador cura a un aliado, el ATQ del objetivo aumenta en un 2.4%. Este efecto se puede acumular hasta 5 veces y dura 2 turnos.","La recuperación de energía del portador aumenta en un 14%. Cuando un aliado usa su habilidad definitiva, el portador regenera al aliado con menor porcentaje de PV una cantidad de PV equivalente al 11% de los PV máx. del objetivo. Cuando el portador cura a un aliado, el ATQ del objetivo aumenta en un 2.8%. Este efecto se puede acumular hasta 5 veces y dura 2 turnos.","La recuperación de energía del portador aumenta en un 16%. Cuando un aliado usa su habilidad definitiva, el portador regenera al aliado con menor porcentaje de PV una cantidad de PV equivalente al 12% de los PV máx. del objetivo. Cuando el portador cura a un aliado, el ATQ del objetivo aumenta en un 3.2%. Este efecto se puede acumular hasta 5 veces y dura 2 turnos.","La recuperación de energía del portador aumenta en un 18%. Cuando un aliado usa su habilidad definitiva, el portador regenera al aliado con menor porcentaje de PV una cantidad de PV equivalente al 13% de los PV máx. del objetivo. Cuando el portador cura a un aliado, el ATQ del objetivo aumenta en un 3.6%. Este efecto se puede acumular hasta 5 veces y dura 2 turnos.","La recuperación de energía del portador aumenta en un 20%. Cuando un aliado usa su habilidad definitiva, el portador regenera al aliado con menor porcentaje de PV una cantidad de PV equivalente al 14% de los PV máx. del objetivo. Cuando el portador cura a un aliado, el ATQ del objetivo aumenta en un 4.0%. Este efecto se puede acumular hasta 5 veces y dura 2 turnos."]'::jsonb, 'Se vende en tiendas del juego · Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Brote verde inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Semilla de la abundancia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110171.png","cantidad":4},{"nombre":"Brote verde inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Brote de la vida","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110172.png","cantidad":4},{"nombre":"Flor etérea inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Brote de la vida","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110172.png","cantidad":8},{"nombre":"Flor etérea inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Flor de la eternidad","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110173.png","cantidad":5},{"nombre":"Rama gloriosa inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Flor de la eternidad","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110173.png","cantidad":10},{"nombre":"Rama gloriosa inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23018', 'honkai-star-rail', 'Instante grabado a fuego', 'An Instant Before A Gaze', '5', 'Erudición', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23018.png', 'Había oído canciones que alababan esa luz:
Las rosas florecen en respuesta a su sonrisa.
El alba brilla para iluminar su rostro.
Las melodías resuenan para animar sus ojos cansados.
Pero la luz se ha ido para no volver, y él sigue corriendo hacia lugares lejanos.
Lo único que puede hacer es esperar, tener fe y extender la Belleza por el cosmos.
Aunque todo no sea más que un instante grabado a fuego en su mente, ya ha recibido la respuesta que buscaba.', 1058, 582, 463, 'Peregrinación del caballero', '["El Daño CRIT del portador aumenta en un 36%. Cuando el portador usa la habilidad definitiva, el daño que inflige su habilidad definitiva aumenta según su energía máxima: por cada punto de energía, el daño aumenta en un 0.36%. Se cuentan un máximo de 180 pts. de energía.","El Daño CRIT del portador aumenta en un 42%. Cuando el portador usa la habilidad definitiva, el daño que inflige su habilidad definitiva aumenta según su energía máxima: por cada punto de energía, el daño aumenta en un 0.42%. Se cuentan un máximo de 180 pts. de energía.","El Daño CRIT del portador aumenta en un 48%. Cuando el portador usa la habilidad definitiva, el daño que inflige su habilidad definitiva aumenta según su energía máxima: por cada punto de energía, el daño aumenta en un 0.48%. Se cuentan un máximo de 180 pts. de energía.","El Daño CRIT del portador aumenta en un 54%. Cuando el portador usa la habilidad definitiva, el daño que inflige su habilidad definitiva aumenta según su energía máxima: por cada punto de energía, el daño aumenta en un 0.54%. Se cuentan un máximo de 180 pts. de energía.","El Daño CRIT del portador aumenta en un 60%. Cuando el portador usa la habilidad definitiva, el daño que inflige su habilidad definitiva aumenta según su energía máxima: por cada punto de energía, el daño aumenta en un 0.60%. Se cuentan un máximo de 180 pts. de energía."]'::jsonb, 'Se vende en tiendas del juego · Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Núcleo apagado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Llave de la inspiración","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110131.png","cantidad":4},{"nombre":"Núcleo apagado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Llave del conocimiento","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110132.png","cantidad":4},{"nombre":"Núcleo reluciente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Llave del conocimiento","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110132.png","cantidad":8},{"nombre":"Núcleo reluciente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Llave de la sabiduría","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110133.png","cantidad":5},{"nombre":"Núcleo serpenteante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Llave de la sabiduría","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110133.png","cantidad":10},{"nombre":"Núcleo serpenteante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23019', 'honkai-star-rail', 'Mi pasado en el espejo', 'Past Self in Mirror', '5', 'Armonía', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23019.png', 'Antes le encantaba capturar el momento en que las flores del ciruelo estaban a punto de marchitarse y mantenerlo vívido con ella.
Han pasado muchos años desde entonces. Muchas formas de vida (revoltosas, dulces y de todas las maneras) han florecido en sus manos, pero las flores del ciruelo siguen marchitándose en ese instante predeterminado.
Han pasado muchos años desde entonces, pero el rostro en el espejo todavía luce idéntico. Sin embargo, en la escala de todo el cosmos, ¿ella mantendría su frescura solo por un momento fugaz?
"Si todo está condenado a fenecer, ¿cuál sería el propósito de la creación?".
Después de un silencio que parece extenderse hasta la eternidad, el viento arrastra las flores al suelo, y la respuesta de la persona en el espejo es la misma de siempre.
"Para el día en que ya no conservemos la flor del ciruelo".
Acaricia la superficie helada del espejo. Soliloquios de esta índole habían ocurrido demasiadas veces como para poder contarlos.', 1058, 529, 529, 'Fragancia de ciruela en mis huesos', '["El efecto de Ruptura del portador aumenta en un 60%. Cuando el portador usa la habilidad definitiva, el daño que infligen todos los aliados aumenta en un 24% durante 3 turnos, y si el efecto de Ruptura del portador es igual o superior al 150%, se recupera 1 pt. de habilidad básica.\nAl comienzo de cada oleada, todos los aliados recuperan 10.0 pts. de energía. Los efectos del mismo tipo no se pueden activar varias veces.","El efecto de Ruptura del portador aumenta en un 70%. Cuando el portador usa la habilidad definitiva, el daño que infligen todos los aliados aumenta en un 28% durante 3 turnos, y si el efecto de Ruptura del portador es igual o superior al 150%, se recupera 1 pt. de habilidad básica.\nAl comienzo de cada oleada, todos los aliados recuperan 12.5 pts. de energía. Los efectos del mismo tipo no se pueden activar varias veces.","El efecto de Ruptura del portador aumenta en un 80%. Cuando el portador usa la habilidad definitiva, el daño que infligen todos los aliados aumenta en un 32% durante 3 turnos, y si el efecto de Ruptura del portador es igual o superior al 150%, se recupera 1 pt. de habilidad básica.\nAl comienzo de cada oleada, todos los aliados recuperan 15.0 pts. de energía. Los efectos del mismo tipo no se pueden activar varias veces.","El efecto de Ruptura del portador aumenta en un 90%. Cuando el portador usa la habilidad definitiva, el daño que infligen todos los aliados aumenta en un 36% durante 3 turnos, y si el efecto de Ruptura del portador es igual o superior al 150%, se recupera 1 pt. de habilidad básica.\nAl comienzo de cada oleada, todos los aliados recuperan 17.5 pts. de energía. Los efectos del mismo tipo no se pueden activar varias veces.","El efecto de Ruptura del portador aumenta en un 100%. Cuando el portador usa la habilidad definitiva, el daño que infligen todos los aliados aumenta en un 40% durante 3 turnos, y si el efecto de Ruptura del portador es igual o superior al 150%, se recupera 1 pt. de habilidad básica.\nAl comienzo de cada oleada, todos los aliados recuperan 20.0 pts. de energía. Los efectos del mismo tipo no se pueden activar varias veces."]'::jsonb, 'Se vende en tiendas del juego · Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Brote verde inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Melodía armónica","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110161.png","cantidad":4},{"nombre":"Brote verde inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Himno del acervo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110162.png","cantidad":4},{"nombre":"Flor etérea inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Himno del acervo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110162.png","cantidad":8},{"nombre":"Flor etérea inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Opus Stellaris","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110163.png","cantidad":5},{"nombre":"Rama gloriosa inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Opus Stellaris","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110163.png","cantidad":10},{"nombre":"Rama gloriosa inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23020', 'honkai-star-rail', 'El bautismo del pensamiento puro', 'Baptism of Pure Thought', '5', 'Cacería', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23020.png', 'La luz del sol tras el mediodía brilla en su justa medida, y la fragancia de las flores embriaga el aire.
Aunque él intenta mantener sus pensamientos puros, el agotamiento inevitablemente trae partículas de confusión como motas de polvo.
"Sanar los pensamientos es tan importante como el mantenimiento de la salud del cuerpo".
El clamor de los tontos se desvanece junto con la fatiga y él se hunde en el agua, dejando que todos los pensamientos floten a la deriva, dejando que su mente se vuelva clara y ordenada.
"La verdad alejará a los inmundos, y solo los verdaderamente puros podrán acercarse".', 953, 582, 529, 'Entrenamiento mental', '["El Daño CRIT del portador aumenta en un 20%. Por cada estado negativo que tenga el objetivo, el Daño CRIT que le inflige el portador aumenta en un 8%. Se puede acumular hasta 3 veces. Al atacar a un objetivo con la habilidad definitiva, el portador obtiene el efecto Disputa, el daño que inflige aumenta en un 36% y sus ataques adicionales ignoran un 24% de la DEF del objetivo. Este efecto dura 2 turnos.","El Daño CRIT del portador aumenta en un 23%. Por cada estado negativo que tenga el objetivo, el Daño CRIT que le inflige el portador aumenta en un 9%. Se puede acumular hasta 3 veces. Al atacar a un objetivo con la habilidad definitiva, el portador obtiene el efecto Disputa, el daño que inflige aumenta en un 42% y sus ataques adicionales ignoran un 28% de la DEF del objetivo. Este efecto dura 2 turnos.","El Daño CRIT del portador aumenta en un 26%. Por cada estado negativo que tenga el objetivo, el Daño CRIT que le inflige el portador aumenta en un 10%. Se puede acumular hasta 3 veces. Al atacar a un objetivo con la habilidad definitiva, el portador obtiene el efecto Disputa, el daño que inflige aumenta en un 48% y sus ataques adicionales ignoran un 32% de la DEF del objetivo. Este efecto dura 2 turnos.","El Daño CRIT del portador aumenta en un 29%. Por cada estado negativo que tenga el objetivo, el Daño CRIT que le inflige el portador aumenta en un 11%. Se puede acumular hasta 3 veces. Al atacar a un objetivo con la habilidad definitiva, el portador obtiene el efecto Disputa, el daño que inflige aumenta en un 54% y sus ataques adicionales ignoran un 36% de la DEF del objetivo. Este efecto dura 2 turnos.","El Daño CRIT del portador aumenta en un 32%. Por cada estado negativo que tenga el objetivo, el Daño CRIT que le inflige el portador aumenta en un 12%. Se puede acumular hasta 3 veces. Al atacar a un objetivo con la habilidad definitiva, el portador obtiene el efecto Disputa, el daño que inflige aumenta en un 60% y sus ataques adicionales ignoran un 40% de la DEF del objetivo. Este efecto dura 2 turnos."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Instinto del ladrón","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111011.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Flecha del cazabestias","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110121.png","cantidad":4},{"nombre":"Instinto del ladrón","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111011.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Flecha del matademonios","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110122.png","cantidad":4},{"nombre":"Ambición distorsionada","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111012.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Flecha del matademonios","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110122.png","cantidad":8},{"nombre":"Ambición distorsionada","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111012.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Flecha del persigueestrellas","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110123.png","cantidad":5},{"nombre":"Voluntad de conquista","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111013.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Flecha del persigueestrellas","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110123.png","cantidad":10},{"nombre":"Voluntad de conquista","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111013.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23021', 'honkai-star-rail', 'Mundo de juegos', 'Earthly Escapade', '5', 'Armonía', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23021.png', 'Como los fuegos artificiales cambiantes, ella también puede cambiar de color diez veces en un minuto.
Cuando el espectáculo de pirotecnia está a punto de terminar, se sienta en un lugar elevado y observa aburrida a la muchedumbre bulliciosa que hay bajo sus pies.
Los pensamientos se deslizan y desaparecen, y una chispa astuta se mueve en sus ojos caleidoscópicos.
"¡Ya sé! ¡Hoy nos divertiremos así!".
Dando saltos, atraviesa la marea de gente con su cola roja y dorada revoloteando.
"¡No te quedes atrás! ¡Los mejores fuegos artificiales están a punto de empezar!".', 1164, 529, 463, 'Veleidad', '["Aumenta el Daño CRIT del portador en un 32%. Al comienzo de la batalla, el portador obtiene Máscara durante 3 turnos. Mientras el portador tiene Máscara, la Prob. CRIT de los aliados del portador aumenta en un 10% y el Daño CRIT aumenta en un 28%. Cada vez que el portador recupera 1 pt. de habilidad básica (incluyendo los pts. que exceden el límite), obtiene 1 acumulación de Llama radiante. Cuando tiene 4 acumulaciones de Llama radiante, se eliminan todas y obtiene Máscara durante 4 turnos.","Aumenta el Daño CRIT del portador en un 39%. Al comienzo de la batalla, el portador obtiene Máscara durante 3 turnos. Mientras el portador tiene Máscara, la Prob. CRIT de los aliados del portador aumenta en un 11% y el Daño CRIT aumenta en un 35%. Cada vez que el portador recupera 1 pt. de habilidad básica (incluyendo los pts. que exceden el límite), obtiene 1 acumulación de Llama radiante. Cuando tiene 4 acumulaciones de Llama radiante, se eliminan todas y obtiene Máscara durante 4 turnos.","Aumenta el Daño CRIT del portador en un 46%. Al comienzo de la batalla, el portador obtiene Máscara durante 3 turnos. Mientras el portador tiene Máscara, la Prob. CRIT de los aliados del portador aumenta en un 12% y el Daño CRIT aumenta en un 42%. Cada vez que el portador recupera 1 pt. de habilidad básica (incluyendo los pts. que exceden el límite), obtiene 1 acumulación de Llama radiante. Cuando tiene 4 acumulaciones de Llama radiante, se eliminan todas y obtiene Máscara durante 4 turnos.","Aumenta el Daño CRIT del portador en un 53%. Al comienzo de la batalla, el portador obtiene Máscara durante 3 turnos. Mientras el portador tiene Máscara, la Prob. CRIT de los aliados del portador aumenta en un 13% y el Daño CRIT aumenta en un 49%. Cada vez que el portador recupera 1 pt. de habilidad básica (incluyendo los pts. que exceden el límite), obtiene 1 acumulación de Llama radiante. Cuando tiene 4 acumulaciones de Llama radiante, se eliminan todas y obtiene Máscara durante 4 turnos.","Aumenta el Daño CRIT del portador en un 60%. Al comienzo de la batalla, el portador obtiene Máscara durante 3 turnos. Mientras el portador tiene Máscara, la Prob. CRIT de los aliados del portador aumenta en un 14% y el Daño CRIT aumenta en un 56%. Cada vez que el portador recupera 1 pt. de habilidad básica (incluyendo los pts. que exceden el límite), obtiene 1 acumulación de Llama radiante. Cuando tiene 4 acumulaciones de Llama radiante, se eliminan todas y obtiene Máscara durante 4 turnos."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Jirones de pensamientos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114011.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Nota del firmamento","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110231.png","cantidad":4},{"nombre":"Jirones de pensamientos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114011.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Compás celestial","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110232.png","cantidad":4},{"nombre":"Fragmento de impresiones","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114012.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Compás celestial","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110232.png","cantidad":8},{"nombre":"Fragmento de impresiones","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114012.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Movimiento celestial","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110233.png","cantidad":5},{"nombre":"Fragmento de deseos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114013.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Movimiento celestial","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110233.png","cantidad":10},{"nombre":"Fragmento de deseos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114013.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23022', 'honkai-star-rail', 'Recuerdos reconstruidos', 'Reforged Remembrance', '5', 'Nihilidad', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23022.png', 'Encender las velas, extender las cartas, oler la fragancia...
Esos recuerdos fragmentados se convierten en rostros en medio de la luz danzante.
Las apariciones que salen de las llamas le cuentan sobre un pasado recordado con cariño.
Un tiempo cortado, un momento congelado. Ella convierte esos instantes preciosos en una eternidad cristalizada.
"Perdemos demasiado y nos queda demasiado poco... Cultivamos la reminiscencia para defendernos de la crueldad del tiempo".', 1058, 582, 463, 'Cristalización', '["El acierto de efecto del portador aumenta en un 40%. Cuando el portador inflige daño a un enemigo afectado por Intemperie, Quemadura, Electrocución o Sangrado, obtiene 1 acumulación de Profeta, hasta un máximo de 4 acumulaciones. En una sola batalla, cada tipo de estado de Daño con el tiempo solo puede acumular Profeta 1 vez. Cada acumulación de Profeta aumenta el ATQ del portador en un 5%. Además, el Daño con el tiempo infligido ignora un 7.2% de la DEF del objetivo.","El acierto de efecto del portador aumenta en un 45%. Cuando el portador inflige daño a un enemigo afectado por Intemperie, Quemadura, Electrocución o Sangrado, obtiene 1 acumulación de Profeta, hasta un máximo de 4 acumulaciones. En una sola batalla, cada tipo de estado de Daño con el tiempo solo puede acumular Profeta 1 vez. Cada acumulación de Profeta aumenta el ATQ del portador en un 6%. Además, el Daño con el tiempo infligido ignora un 7.9% de la DEF del objetivo.","El acierto de efecto del portador aumenta en un 50%. Cuando el portador inflige daño a un enemigo afectado por Intemperie, Quemadura, Electrocución o Sangrado, obtiene 1 acumulación de Profeta, hasta un máximo de 4 acumulaciones. En una sola batalla, cada tipo de estado de Daño con el tiempo solo puede acumular Profeta 1 vez. Cada acumulación de Profeta aumenta el ATQ del portador en un 7%. Además, el Daño con el tiempo infligido ignora un 8.6% de la DEF del objetivo.","El acierto de efecto del portador aumenta en un 55%. Cuando el portador inflige daño a un enemigo afectado por Intemperie, Quemadura, Electrocución o Sangrado, obtiene 1 acumulación de Profeta, hasta un máximo de 4 acumulaciones. En una sola batalla, cada tipo de estado de Daño con el tiempo solo puede acumular Profeta 1 vez. Cada acumulación de Profeta aumenta el ATQ del portador en un 8%. Además, el Daño con el tiempo infligido ignora un 9.3% de la DEF del objetivo.","El acierto de efecto del portador aumenta en un 60%. Cuando el portador inflige daño a un enemigo afectado por Intemperie, Quemadura, Electrocución o Sangrado, obtiene 1 acumulación de Profeta, hasta un máximo de 4 acumulaciones. En una sola batalla, cada tipo de estado de Daño con el tiempo solo puede acumular Profeta 1 vez. Cada acumulación de Profeta aumenta el ATQ del portador en un 9%. Además, el Daño con el tiempo infligido ignora un 10.0% de la DEF del objetivo."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Núcleo apagado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Espíritu ardiente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110221.png","cantidad":4},{"nombre":"Núcleo apagado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Esencia de fuego estelar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110222.png","cantidad":4},{"nombre":"Núcleo reluciente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Esencia de fuego estelar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110222.png","cantidad":8},{"nombre":"Núcleo reluciente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Incinerador divino","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110223.png","cantidad":5},{"nombre":"Núcleo serpenteante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Incinerador divino","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110223.png","cantidad":10},{"nombre":"Núcleo serpenteante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23023', 'honkai-star-rail', 'El destino nunca es justo', 'Inherently Unjust Destiny', '5', 'Conservación', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23023.png', 'Cuando se revela la última carta, innumerables emociones afloran a los rostros de sus oponentes: decepción, rabia, impotencia, calma...
"Ya que estamos aquí, ¿por qué no hacemos algo más emocionante?".
Y empuja todas sus fichas. Quienes se consideran desafortunados se retiran de la mesa maldiciendo en susurros. Secretamente, esperan que pierda.
Las victorias y las derrotas, la reputación, la suerte... Nada de eso le importa. Simplemente, está obsesionado con ese momento que hace temblar su vida.
Una decisión es lo único que separa el cielo del infierno.
Se lanzan las fichas, se oyen lamentos y las satisfacciones ilusorias como esta se desvanecen cuando el polvo se asienta.
"Tenerlo todo o no tener nada... Pero no tengo libertad para elegir".', 1058, 423, 662, 'Con todo', '["La DEF del portador aumenta en un 40%. Cuando el portador proporciona un escudo a un aliado, el Daño CRIT del portador aumenta en un 40% durante 2 turnos. Cuando el portador golpea al enemigo con sus ataques adicionales, hay un 100% de probabilidad base de que el daño que recibe el enemigo atacado aumente en un 10.0% durante 2 turnos.","La DEF del portador aumenta en un 46%. Cuando el portador proporciona un escudo a un aliado, el Daño CRIT del portador aumenta en un 46% durante 2 turnos. Cuando el portador golpea al enemigo con sus ataques adicionales, hay un 115% de probabilidad base de que el daño que recibe el enemigo atacado aumente en un 11.5% durante 2 turnos.","La DEF del portador aumenta en un 52%. Cuando el portador proporciona un escudo a un aliado, el Daño CRIT del portador aumenta en un 52% durante 2 turnos. Cuando el portador golpea al enemigo con sus ataques adicionales, hay un 130% de probabilidad base de que el daño que recibe el enemigo atacado aumente en un 13.0% durante 2 turnos.","La DEF del portador aumenta en un 58%. Cuando el portador proporciona un escudo a un aliado, el Daño CRIT del portador aumenta en un 58% durante 2 turnos. Cuando el portador golpea al enemigo con sus ataques adicionales, hay un 145% de probabilidad base de que el daño que recibe el enemigo atacado aumente en un 14.5% durante 2 turnos.","La DEF del portador aumenta en un 64%. Cuando el portador proporciona un escudo a un aliado, el Daño CRIT del portador aumenta en un 64% durante 2 turnos. Cuando el portador golpea al enemigo con sus ataques adicionales, hay un 160% de probabilidad base de que el daño que recibe el enemigo atacado aumente en un 16.0% durante 2 turnos."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Jirones de pensamientos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114011.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Polvo estelar disperso","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110211.png","cantidad":4},{"nombre":"Jirones de pensamientos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114011.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Meteoritos de cristal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110212.png","cantidad":4},{"nombre":"Fragmento de impresiones","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114012.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Meteoritos de cristal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110212.png","cantidad":8},{"nombre":"Fragmento de impresiones","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114012.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Ámbar divino","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110213.png","cantidad":5},{"nombre":"Fragmento de deseos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114013.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Ámbar divino","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110213.png","cantidad":10},{"nombre":"Fragmento de deseos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114013.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23024', 'honkai-star-rail', 'En las orillas transitorias', 'Along the Passing Shore', '5', 'Nihilidad', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23024.png', 'Las mareas heladas que rompen constantemente contra las orillas y llevan todo hacia su final fluyen en el estrecho espacio que hay entre la existencia y la nada.
Aquí, los ahogados piden socorro, cantan sus lamentaciones, disfrutan de la felicidad, viven dulces momentos y sufren grandes dolores... y todo esto se refleja en el agua. Ella no puede vivirlo, pero lo siente.
Antes de llegar al final, tiene que andar muchos caminos, oír muchos sonidos y cambiar muchas cosas.
Extiende la mano y salva a los ahogados de las tentaciones de la Nihilidad, y una ilusión tras otra se rompe tras su silueta.
Ella sigue andando en este mundo sin límites en busca de un destino final que no existe.
Y aquí siempre está lloviendo.', 1058, 635, 397, 'Navegante', '["El Daño CRIT del portador aumenta en un 36%. Cuando el portador golpea a un enemigo, lo afecta con Ilusión vacía durante 1 turno. Solo se puede activar 1 vez por objetivo en cada ataque del portador. El daño que el portador inflige a los objetivos afectados por Ilusión vacía aumenta en un 24% y el daño que inflige la habilidad definitiva aumenta en un 24% adicional.","El Daño CRIT del portador aumenta en un 42%. Cuando el portador golpea a un enemigo, lo afecta con Ilusión vacía durante 1 turno. Solo se puede activar 1 vez por objetivo en cada ataque del portador. El daño que el portador inflige a los objetivos afectados por Ilusión vacía aumenta en un 28% y el daño que inflige la habilidad definitiva aumenta en un 28% adicional.","El Daño CRIT del portador aumenta en un 48%. Cuando el portador golpea a un enemigo, lo afecta con Ilusión vacía durante 1 turno. Solo se puede activar 1 vez por objetivo en cada ataque del portador. El daño que el portador inflige a los objetivos afectados por Ilusión vacía aumenta en un 32% y el daño que inflige la habilidad definitiva aumenta en un 32% adicional.","El Daño CRIT del portador aumenta en un 54%. Cuando el portador golpea a un enemigo, lo afecta con Ilusión vacía durante 1 turno. Solo se puede activar 1 vez por objetivo en cada ataque del portador. El daño que el portador inflige a los objetivos afectados por Ilusión vacía aumenta en un 36% y el daño que inflige la habilidad definitiva aumenta en un 36% adicional.","El Daño CRIT del portador aumenta en un 60%. Cuando el portador golpea a un enemigo, lo afecta con Ilusión vacía durante 1 turno. Solo se puede activar 1 vez por objetivo en cada ataque del portador. El daño que el portador inflige a los objetivos afectados por Ilusión vacía aumenta en un 40% y el daño que inflige la habilidad definitiva aumenta en un 40% adicional."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Componente del acumulador de sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Espíritu ardiente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110221.png","cantidad":4},{"nombre":"Componente del acumulador de sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Esencia de fuego estelar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110222.png","cantidad":4},{"nombre":"Válvula del flujo de sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Esencia de fuego estelar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110222.png","cantidad":8},{"nombre":"Válvula del flujo de sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Incinerador divino","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110223.png","cantidad":5},{"nombre":"Motor creasueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Incinerador divino","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110223.png","cantidad":10},{"nombre":"Motor creasueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23025', 'honkai-star-rail', 'A donde regresan los sueños', 'Whereabouts Should Dreams Rest', '5', 'Destrucción', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23025.png', 'La frontera del sistema estelar Asdana. Las olas gigantes agitaban el océano de recuerdos, y ella era como una chispa que podía extinguirse en cualquier momento con un fuerte soplo de viento.
"Cuando alguien incapaz de soñar quiere entrar en el paisaje onírico sinestésico, el precio a pagar es comparable a la muerte".
La voz preocupada de sus compañeros aún resonaba en sus oídos. Respiró hondo y se sumergió en la Zona de los Recuerdos.
A medida que el vehículo se hundía en silencio en las profundidades de la Zona de los Recuerdos, diminutas motas de luz como estrellas escapaban entre sus resquicios, solo para ser engullidas por la oscuridad sin fin.
"¿Por qué morimos?".
En el océano de recuerdos, cada vez más profundo, las criaturas de la Zona de los Recuerdos emitían una tenue luz que recuerda a unos ojos lejanos que la miran con indiferencia.
Los sueños permanecían demasiado distantes para ella. Contemplaba la negrura infinita, con su cuerpo y alma hace rato al borde del colapso bajo la inmensa presión de la memoria. Aunque sentía que su conciencia se desvanecía, su mente repetía una y otra vez los mismos recuerdos persistentes...
El Enjambre irrumpía en las líneas del frente y su cuerpo envuelto en llamas se alzaba hacia ellos. Las cenizas del Enjambre caían como nieve, cubriendo los restos ennegrecidos de los caballeros de abajo.
Ni siquiera había tenido tiempo de sostener un ramo, de ofrecer un último tributo a sus camaradas caídos mientras caían uno tras otro. Sus vidas parpadeaban brevemente y luego se extinguían, como una cadena de códigos genéticos, solo dígitos, nunca teniendo sus propios nombres.
"¿Por qué vivimos?".
En un silencio sepulcral, se disolvía como una llama en el mar. Solo quedaba una débil chispa que avanzaba hacia un lugar brillante...
No sabía cuánto tiempo había pasado cuando abrió los ojos y le pareció ver el futuro como una perla que emitía una luz tenue. Las lágrimas bañaron su rostro...
"Para encontrar... mi propio sueño...".', 1164, 476, 529, 'Metamorfosis', '["El efecto de Ruptura del portador aumenta en un 60%. Cuando el portador inflige Daño de Ruptura a un enemigo, este entra en el estado de Vencido durante 2 turnos. Los objetivos afectados con Vencido reciben un 24.0% más de Daño de Ruptura del portador y su VEL se reduce en un 20%. Los efectos del mismo tipo no se pueden acumular.","El efecto de Ruptura del portador aumenta en un 70%. Cuando el portador inflige Daño de Ruptura a un enemigo, este entra en el estado de Vencido durante 2 turnos. Los objetivos afectados con Vencido reciben un 28.0% más de Daño de Ruptura del portador y su VEL se reduce en un 20%. Los efectos del mismo tipo no se pueden acumular.","El efecto de Ruptura del portador aumenta en un 80%. Cuando el portador inflige Daño de Ruptura a un enemigo, este entra en el estado de Vencido durante 2 turnos. Los objetivos afectados con Vencido reciben un 32.0% más de Daño de Ruptura del portador y su VEL se reduce en un 20%. Los efectos del mismo tipo no se pueden acumular.","El efecto de Ruptura del portador aumenta en un 90%. Cuando el portador inflige Daño de Ruptura a un enemigo, este entra en el estado de Vencido durante 2 turnos. Los objetivos afectados con Vencido reciben un 36.0% más de Daño de Ruptura del portador y su VEL se reduce en un 20%. Los efectos del mismo tipo no se pueden acumular.","El efecto de Ruptura del portador aumenta en un 100%. Cuando el portador inflige Daño de Ruptura a un enemigo, este entra en el estado de Vencido durante 2 turnos. Los objetivos afectados con Vencido reciben un 40.0% más de Daño de Ruptura del portador y su VEL se reduce en un 20%. Los efectos del mismo tipo no se pueden acumular."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Jirones de pensamientos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114011.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Canino de borisin","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110181.png","cantidad":4},{"nombre":"Jirones de pensamientos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114011.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Diente serrado con lupitoxina","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110182.png","cantidad":4},{"nombre":"Fragmento de impresiones","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114012.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Diente serrado con lupitoxina","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110182.png","cantidad":8},{"nombre":"Fragmento de impresiones","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114012.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Colmillo de la locura lunar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110183.png","cantidad":5},{"nombre":"Fragmento de deseos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114013.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Colmillo de la locura lunar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110183.png","cantidad":10},{"nombre":"Fragmento de deseos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114013.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23026', 'honkai-star-rail', 'Luces de la noche', 'Flowing Nightglow', '5', 'Armonía', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23026.png', 'Los años pasan a través del espejo, y la joven inexperta se ha convertido ya en una cantante experimentada.
Se mira a sí misma en el espejo. El tiempo lo ha cambiado todo, pero sus ojos verdes permanecen tan tranquilos como un lago en calma, como expresando una fe inquebrantable.
"Parece que estás de buen humor hoy".
"Sí... Después de todo, es una actuación muy importante".
"Cierto. El ensayo para el Festival Carismonía está a punto de comenzar. Puedes ir a la sala de preparación".
...
Sale del camerino y se aleja poco a poco del teatro envuelto en fastuosas luces.
"Mi escenario no está aquí".
Ella cierra los ojos y deja que la noche engulla su sombra.
"Desde el primer día, siempre he cantado solo para...".
"Para aquellos que han perdido la esperanza".', 953, 635, 463, 'Consuelo', '["Cada vez que un aliado ataca, el portador obtiene 1 acumulación de Tonada. Cada acumulación de Tonada aumenta la recuperación de energía del portador en un 3.0%, hasta un máximo de 5 acumulaciones. Después de que el portador use su habilidad definitiva, elimina Tonada y obtiene Cadenza. Cadenza aumenta en un 48% el ATQ del portador y aumenta en un 24% el daño que infligen todos los aliados durante 1 turno.","Cada vez que un aliado ataca, el portador obtiene 1 acumulación de Tonada. Cada acumulación de Tonada aumenta la recuperación de energía del portador en un 3.5%, hasta un máximo de 5 acumulaciones. Después de que el portador use su habilidad definitiva, elimina Tonada y obtiene Cadenza. Cadenza aumenta en un 60% el ATQ del portador y aumenta en un 28% el daño que infligen todos los aliados durante 1 turno.","Cada vez que un aliado ataca, el portador obtiene 1 acumulación de Tonada. Cada acumulación de Tonada aumenta la recuperación de energía del portador en un 4.0%, hasta un máximo de 5 acumulaciones. Después de que el portador use su habilidad definitiva, elimina Tonada y obtiene Cadenza. Cadenza aumenta en un 72% el ATQ del portador y aumenta en un 32% el daño que infligen todos los aliados durante 1 turno.","Cada vez que un aliado ataca, el portador obtiene 1 acumulación de Tonada. Cada acumulación de Tonada aumenta la recuperación de energía del portador en un 4.5%, hasta un máximo de 5 acumulaciones. Después de que el portador use su habilidad definitiva, elimina Tonada y obtiene Cadenza. Cadenza aumenta en un 84% el ATQ del portador y aumenta en un 36% el daño que infligen todos los aliados durante 1 turno.","Cada vez que un aliado ataca, el portador obtiene 1 acumulación de Tonada. Cada acumulación de Tonada aumenta la recuperación de energía del portador en un 5.0%, hasta un máximo de 5 acumulaciones. Después de que el portador use su habilidad definitiva, elimina Tonada y obtiene Cadenza. Cadenza aumenta en un 96% el ATQ del portador y aumenta en un 40% el daño que infligen todos los aliados durante 1 turno."]'::jsonb, 'Se vende en tiendas del juego · Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Componente del acumulador de sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Nota del firmamento","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110231.png","cantidad":4},{"nombre":"Componente del acumulador de sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Compás celestial","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110232.png","cantidad":4},{"nombre":"Válvula del flujo de sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Compás celestial","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110232.png","cantidad":8},{"nombre":"Válvula del flujo de sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Movimiento celestial","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110233.png","cantidad":5},{"nombre":"Motor creasueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Movimiento celestial","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110233.png","cantidad":10},{"nombre":"Motor creasueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23027', 'honkai-star-rail', 'Hacia una segunda vida', 'Sailing Towards a Second Life', '5', 'Cacería', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23027.png', 'Sintió como si cayera al fondo del mar. Todo lo había abandonado, y lo único que le quedaba eran pensamientos que saltaban y luchaban en el vacío.
El miedo, la inquietud, la soledad, la oscuridad, la ira... Esas emociones no se disiparon con su cuerpo físico, sino que se conservaron de un modo distinto en la carcasa mecánica, más opresivas aún.
Oyó los gritos de los difuntos, percibió el olor a quemado, un zumbido de maquinaria le rondaba los oídos, y la nueva sangre azul fluyó hacia su sediento corazón... Algunos recuerdos crueles salieron a flote, mientras el odio imborrable se convertía en una débil luz en la oscuridad. Siguiendo la luz hasta el final, salió del agua con sus últimas fuerzas.
Abrió los ojos y, después de los cegadores destellos, escuchó las felicitaciones de la sanadora...
"Bienvenido de nuevo a este mundo".
Apretó fuerte los puños, hechos ahora de acero...
Ya no viviría para sí mismo.', 1058, 582, 463, 'Mar bravo', '["El efecto de Ruptura del portador aumenta en un 60% y el Daño de Ruptura que inflige el portador ignora un 20% de la DEF del objetivo. Cuando el efecto de Ruptura del portador sea igual o superior al 150% durante la batalla, su VEL aumenta en un 12%.","El efecto de Ruptura del portador aumenta en un 70% y el Daño de Ruptura que inflige el portador ignora un 23% de la DEF del objetivo. Cuando el efecto de Ruptura del portador sea igual o superior al 150% durante la batalla, su VEL aumenta en un 14%.","El efecto de Ruptura del portador aumenta en un 80% y el Daño de Ruptura que inflige el portador ignora un 26% de la DEF del objetivo. Cuando el efecto de Ruptura del portador sea igual o superior al 150% durante la batalla, su VEL aumenta en un 16%.","El efecto de Ruptura del portador aumenta en un 90% y el Daño de Ruptura que inflige el portador ignora un 29% de la DEF del objetivo. Cuando el efecto de Ruptura del portador sea igual o superior al 150% durante la batalla, su VEL aumenta en un 18%.","El efecto de Ruptura del portador aumenta en un 100% y el Daño de Ruptura que inflige el portador ignora un 32% de la DEF del objetivo. Cuando el efecto de Ruptura del portador sea igual o superior al 150% durante la batalla, su VEL aumenta en un 20%."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Jirones de pensamientos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114011.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Perdigón meteórico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110191.png","cantidad":4},{"nombre":"Jirones de pensamientos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114011.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Deceso predestinado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110192.png","cantidad":4},{"nombre":"Fragmento de impresiones","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114012.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Deceso predestinado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110192.png","cantidad":8},{"nombre":"Fragmento de impresiones","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114012.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Disparo antitemporal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110193.png","cantidad":5},{"nombre":"Fragmento de deseos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114013.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Disparo antitemporal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110193.png","cantidad":10},{"nombre":"Fragmento de deseos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114013.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23028', 'honkai-star-rail', 'La esperanza no tiene precio', 'Yet Hope Is Priceless', '5', 'Erudición', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23028.png', '"Señora Bonajade, si no fuera por su continua ayuda y donaciones, el orfanato...".
Las palabras del director se vieron interrumpidas por la suave caricia de Bonajade sobre las cabezas de los niños.
"No te preocupes por el futuro mientras esté aquí... Además, no es necesario hablar de estas cosas frente a los niños, solo les preocuparíamos más".
Los pequeños alzaron la mirada, compartiendo con ella los sucesos recientes, sus preocupaciones y sus sueños.
"¿Cuándo volverá, señora Bonajade?".
"No se exija demasiado, asegúrese de descansar lo suficiente...".
"¡Cuando crezca, quiero ser como usted!".
Bonajade se detuvo un momento al ver la mirada limpia de los niños.
"¿Ser como yo?...".
La niña añadió con entusiasmo mientras le ofrecía una manzana: "¡Sí! ¡Alguien que lleva luz y esperanza a los demás!".
La pobreza, el desamparo, la tristeza, el sufrimiento... Ella viajaba por el cosmos, aceptando lo que otros empeñaban y devolviendo algo del mismo valor.
La vida existe por el deseo, se apresura por el deseo y muere por el deseo. Esta es una ley irrefutable, al igual que una verdad inevitable.
Una filántropa con un lado oculto, una villana que hipoteca almas... El mundo le asignaba diversas identidades, pero solo ella comprendía la moralidad tras sus actos.', 953, 582, 529, 'Promesa', '["La Prob. CRIT del portador aumenta en un 16%. Cuando el Daño CRIT del portador es superior al 120% en el combate, por cada 20% en exceso, el daño que infligen los ataques adicionales aumenta en un 12%. Este efecto se puede acumular hasta 4 veces. Al comenzar el combate y después de que el portador use el ATQ básico, el daño que infligen su habilidad definitiva o ataques adicionales ignora un 20% de la DEF del objetivo durante 2 turnos.","La Prob. CRIT del portador aumenta en un 19%. Cuando el Daño CRIT del portador es superior al 120% en el combate, por cada 20% en exceso, el daño que infligen los ataques adicionales aumenta en un 14%. Este efecto se puede acumular hasta 4 veces. Al comenzar el combate y después de que el portador use el ATQ básico, el daño que infligen su habilidad definitiva o ataques adicionales ignora un 24% de la DEF del objetivo durante 2 turnos.","La Prob. CRIT del portador aumenta en un 22%. Cuando el Daño CRIT del portador es superior al 120% en el combate, por cada 20% en exceso, el daño que infligen los ataques adicionales aumenta en un 16%. Este efecto se puede acumular hasta 4 veces. Al comenzar el combate y después de que el portador use el ATQ básico, el daño que infligen su habilidad definitiva o ataques adicionales ignora un 28% de la DEF del objetivo durante 2 turnos.","La Prob. CRIT del portador aumenta en un 25%. Cuando el Daño CRIT del portador es superior al 120% en el combate, por cada 20% en exceso, el daño que infligen los ataques adicionales aumenta en un 18%. Este efecto se puede acumular hasta 4 veces. Al comenzar el combate y después de que el portador use el ATQ básico, el daño que infligen su habilidad definitiva o ataques adicionales ignora un 32% de la DEF del objetivo durante 2 turnos.","La Prob. CRIT del portador aumenta en un 28%. Cuando el Daño CRIT del portador es superior al 120% en el combate, por cada 20% en exceso, el daño que infligen los ataques adicionales aumenta en un 20%. Este efecto se puede acumular hasta 4 veces. Al comenzar el combate y después de que el portador use el ATQ básico, el daño que infligen su habilidad definitiva o ataques adicionales ignora un 36% de la DEF del objetivo durante 2 turnos."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Componente del acumulador de sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Bosquejo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110201.png","cantidad":4},{"nombre":"Componente del acumulador de sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Esbozo dinámico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110202.png","cantidad":4},{"nombre":"Válvula del flujo de sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Esbozo dinámico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110202.png","cantidad":8},{"nombre":"Válvula del flujo de sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Borrador con colores bellos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110203.png","cantidad":5},{"nombre":"Motor creasueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Borrador con colores bellos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110203.png","cantidad":10},{"nombre":"Motor creasueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23029', 'honkai-star-rail', 'Esas incontables primaveras', 'Those Many Springs', '5', 'Nihilidad', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23029.png', 'Tras varias lluvias repentinas, la primavera se alza como una marea de verdor creciente.
"¿Cuántas primaveras han pasado?".
Se acuerda de los jóvenes soldados marchando por primera vez hacia el campo de batalla. Esto sucede año tras año. Las personas son distintas, pero su vigor y esperanza son los mismos.
Las ramas de sauce se doblan esperando su regreso. Pero al final, lo que traen de vuelta a la tierra natal... suele ser un frío helado que nunca se derretirá.
Los pájaros trinan apaciblemente. Cierra los ojos y deja que la luz del sol que se filtra entre las hojas bañe su cara.
"Y por eso, quienes quedan son los que más solos se sienten".', 953, 582, 529, 'Los asuntos mundanos no dejan huella', '["El acierto de efecto del portador aumenta en un 60%. Después de que el portador ataque al enemigo con su ATQ básico, habilidad básica o habilidad definitiva, tiene una probabilidad base del 60% de afectar al enemigo con Sin armadura. En el estado de Sin armadura, el daño que recibe el enemigo aumenta en un 10% durante 2 turnos. Si el objetivo está afectado por un estado de Daño con el tiempo aplicado por el portador, hay una probabilidad base del 60% de mejorar el estado de Sin armadura aplicado por el portador al estado de Arrinconado, lo que aumenta el daño que recibe el enemigo en un 14% adicional durante 2 turnos. Durante este periodo, el portador no puede aplicarle Sin armadura.","El acierto de efecto del portador aumenta en un 70%. Después de que el portador ataque al enemigo con su ATQ básico, habilidad básica o habilidad definitiva, tiene una probabilidad base del 60% de afectar al enemigo con Sin armadura. En el estado de Sin armadura, el daño que recibe el enemigo aumenta en un 12% durante 2 turnos. Si el objetivo está afectado por un estado de Daño con el tiempo aplicado por el portador, hay una probabilidad base del 60% de mejorar el estado de Sin armadura aplicado por el portador al estado de Arrinconado, lo que aumenta el daño que recibe el enemigo en un 16% adicional durante 2 turnos. Durante este periodo, el portador no puede aplicarle Sin armadura.","El acierto de efecto del portador aumenta en un 80%. Después de que el portador ataque al enemigo con su ATQ básico, habilidad básica o habilidad definitiva, tiene una probabilidad base del 60% de afectar al enemigo con Sin armadura. En el estado de Sin armadura, el daño que recibe el enemigo aumenta en un 14% durante 2 turnos. Si el objetivo está afectado por un estado de Daño con el tiempo aplicado por el portador, hay una probabilidad base del 60% de mejorar el estado de Sin armadura aplicado por el portador al estado de Arrinconado, lo que aumenta el daño que recibe el enemigo en un 18% adicional durante 2 turnos. Durante este periodo, el portador no puede aplicarle Sin armadura.","El acierto de efecto del portador aumenta en un 90%. Después de que el portador ataque al enemigo con su ATQ básico, habilidad básica o habilidad definitiva, tiene una probabilidad base del 60% de afectar al enemigo con Sin armadura. En el estado de Sin armadura, el daño que recibe el enemigo aumenta en un 16% durante 2 turnos. Si el objetivo está afectado por un estado de Daño con el tiempo aplicado por el portador, hay una probabilidad base del 60% de mejorar el estado de Sin armadura aplicado por el portador al estado de Arrinconado, lo que aumenta el daño que recibe el enemigo en un 20% adicional durante 2 turnos. Durante este periodo, el portador no puede aplicarle Sin armadura.","El acierto de efecto del portador aumenta en un 100%. Después de que el portador ataque al enemigo con su ATQ básico, habilidad básica o habilidad definitiva, tiene una probabilidad base del 60% de afectar al enemigo con Sin armadura. En el estado de Sin armadura, el daño que recibe el enemigo aumenta en un 18% durante 2 turnos. Si el objetivo está afectado por un estado de Daño con el tiempo aplicado por el portador, hay una probabilidad base del 60% de mejorar el estado de Sin armadura aplicado por el portador al estado de Arrinconado, lo que aumenta el daño que recibe el enemigo en un 22% adicional durante 2 turnos. Durante este periodo, el portador no puede aplicarle Sin armadura."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Brote verde inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Espíritu ardiente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110221.png","cantidad":4},{"nombre":"Brote verde inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Esencia de fuego estelar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110222.png","cantidad":4},{"nombre":"Flor etérea inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Esencia de fuego estelar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110222.png","cantidad":8},{"nombre":"Flor etérea inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Incinerador divino","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110223.png","cantidad":5},{"nombre":"Rama gloriosa inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Incinerador divino","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110223.png","cantidad":10},{"nombre":"Rama gloriosa inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23030', 'honkai-star-rail', 'Danza crepuscular', 'Dance at Sunset', '5', 'Destrucción', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23030.png', 'Una figura ágil corre sobre los tejados bajo la menguante luz del crepúsculo.
"Lili, Guoguo, ¡veamos quién llega a la meta primero!".
Como un raudo animalito, la chica escala aleros, evade guardias y se balancea en el aire mientras persigue los últimos rayos de sol.
Una cálida brisa nocturna acaricia su rostro, y el reflejo del sol poniente pinta de abigarrados colores el pelaje de los gatos.
"¡Ganaron!".
Se limpia el sudor de la frente y abraza a los gatos.
Las estrellas se encienden, y su rostro inocente y sincero se ilumina con ellas, como las rosadas nubes del atardecer que se extienden hacia el horizonte.', 1058, 582, 463, 'Fascinación profunda', '["Aumenta en gran medida la probabilidad de que el portador reciba un ataque y el Daño CRIT del portador aumenta en un 36%. Después de que el portador use la habilidad definitiva, obtiene 1 acumulación de Danza ígnea durante 2 turnos. Se puede acumular hasta 2 veces. Cada acumulación de Danza ígnea aumenta el daño que infligen los ataques adicionales del portador en un 36%.","Aumenta en gran medida la probabilidad de que el portador reciba un ataque y el Daño CRIT del portador aumenta en un 42%. Después de que el portador use la habilidad definitiva, obtiene 1 acumulación de Danza ígnea durante 2 turnos. Se puede acumular hasta 2 veces. Cada acumulación de Danza ígnea aumenta el daño que infligen los ataques adicionales del portador en un 42%.","Aumenta en gran medida la probabilidad de que el portador reciba un ataque y el Daño CRIT del portador aumenta en un 48%. Después de que el portador use la habilidad definitiva, obtiene 1 acumulación de Danza ígnea durante 2 turnos. Se puede acumular hasta 2 veces. Cada acumulación de Danza ígnea aumenta el daño que infligen los ataques adicionales del portador en un 48%.","Aumenta en gran medida la probabilidad de que el portador reciba un ataque y el Daño CRIT del portador aumenta en un 54%. Después de que el portador use la habilidad definitiva, obtiene 1 acumulación de Danza ígnea durante 2 turnos. Se puede acumular hasta 2 veces. Cada acumulación de Danza ígnea aumenta el daño que infligen los ataques adicionales del portador en un 54%.","Aumenta en gran medida la probabilidad de que el portador reciba un ataque y el Daño CRIT del portador aumenta en un 60%. Después de que el portador use la habilidad definitiva, obtiene 1 acumulación de Danza ígnea durante 2 turnos. Se puede acumular hasta 2 veces. Cada acumulación de Danza ígnea aumenta el daño que infligen los ataques adicionales del portador en un 60%."]'::jsonb, 'Se vende en tiendas del juego · Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Componente artificial mecánico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113011.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Canino de borisin","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110181.png","cantidad":4},{"nombre":"Componente artificial mecánico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113011.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Diente serrado con lupitoxina","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110182.png","cantidad":4},{"nombre":"Engranaje cilíndrico mecánico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113012.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Diente serrado con lupitoxina","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110182.png","cantidad":8},{"nombre":"Engranaje cilíndrico mecánico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113012.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Colmillo de la locura lunar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110183.png","cantidad":5},{"nombre":"Corazón armonioso mecánico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113013.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Colmillo de la locura lunar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110183.png","cantidad":10},{"nombre":"Corazón armonioso mecánico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113013.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23031', 'honkai-star-rail', 'Me voy de caza', 'I Venture Forth to Hunt', '5', 'Cacería', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23031.png', '"Esclavos patéticos, ridículos...".
El ejército de los Moradores de la Abundancia se abalanza sobre la frontera, la lupitoxina se acerca a los Caballeros del Verdor como una inundación, tratando de despertar el miedo oculto en lo profundo de los corazones de los soldados, evocando visiones de terror, golpeando las voluntades de los guerreros, obligándolos a soltar sus armas y dejarse llevar por la duda.
Pero el frente se mantiene firme como el Muro de Bronce, imperturbable ante las despectivas palabras de los borisin. De entre los soldados, una figura se asoma.
Mueve su cuerpo lentamente, las banderas tras ella ondean bajo el invisible impulso asesino.
"La general... Es la general...".
"General Feixiao".
"¡La Garra Celestial!".
Los murmullos se unen y se convierten en un grito de batalla.
"¡Siempre volando alto! ¡Siempre victoriosa!".
Ella permanece ahí, sola. Una figura solitaria con el poder de todo un ejército.', 953, 635, 463, 'Intimidación', '["La Prob. CRIT del portador aumenta en un 15.0%. Cuando el portador lanza un ataque adicional, obtiene 1 acumulación de Resplandor. Se puede acumular hasta 2 veces. Por cada acumulación de Resplandor, el daño de habilidad definitiva que inflige el portador ignora un 27% de la DEF del objetivo. Cuando termina el turno del portador, se elimina 1 acumulación de Resplandor.","La Prob. CRIT del portador aumenta en un 17.5%. Cuando el portador lanza un ataque adicional, obtiene 1 acumulación de Resplandor. Se puede acumular hasta 2 veces. Por cada acumulación de Resplandor, el daño de habilidad definitiva que inflige el portador ignora un 30% de la DEF del objetivo. Cuando termina el turno del portador, se elimina 1 acumulación de Resplandor.","La Prob. CRIT del portador aumenta en un 20.0%. Cuando el portador lanza un ataque adicional, obtiene 1 acumulación de Resplandor. Se puede acumular hasta 2 veces. Por cada acumulación de Resplandor, el daño de habilidad definitiva que inflige el portador ignora un 33% de la DEF del objetivo. Cuando termina el turno del portador, se elimina 1 acumulación de Resplandor.","La Prob. CRIT del portador aumenta en un 22.5%. Cuando el portador lanza un ataque adicional, obtiene 1 acumulación de Resplandor. Se puede acumular hasta 2 veces. Por cada acumulación de Resplandor, el daño de habilidad definitiva que inflige el portador ignora un 36% de la DEF del objetivo. Cuando termina el turno del portador, se elimina 1 acumulación de Resplandor.","La Prob. CRIT del portador aumenta en un 25.0%. Cuando el portador lanza un ataque adicional, obtiene 1 acumulación de Resplandor. Se puede acumular hasta 2 veces. Por cada acumulación de Resplandor, el daño de habilidad definitiva que inflige el portador ignora un 39% de la DEF del objetivo. Cuando termina el turno del portador, se elimina 1 acumulación de Resplandor."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Componente artificial mecánico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113011.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Perdigón meteórico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110191.png","cantidad":4},{"nombre":"Componente artificial mecánico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113011.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Deceso predestinado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110192.png","cantidad":4},{"nombre":"Engranaje cilíndrico mecánico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113012.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Deceso predestinado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110192.png","cantidad":8},{"nombre":"Engranaje cilíndrico mecánico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113012.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Disparo antitemporal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110193.png","cantidad":5},{"nombre":"Corazón armonioso mecánico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113013.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Disparo antitemporal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110193.png","cantidad":10},{"nombre":"Corazón armonioso mecánico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113013.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23032', 'honkai-star-rail', 'Solo la fragancia perdura', 'Scent Alone Stays True', '5', 'Abundancia', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23032.png', '"Primero, reorganizar los hábitos de trabajo del departamento".
"Luego, aplicar recompensas y sanciones estrictas".
"Por supuesto, lo más importante es averiguar cuanto antes los intereses personales de todos...".
Aunque disfrutaba del paisaje, su mente volvía al trabajo y al estrés y la irritación que este conllevaba.
Rápidamente, encendió el incienso que siempre llevaba consigo.
"El mundo es tan maravilloso y yo me la paso renegando... ¡Será mejor que no piense en eso mientras estoy de vacaciones!".', 1058, 529, 529, 'Alivio', '["El efecto de Ruptura del portador aumenta en un 60%. Los enemigos a los que ataca el portador con su habilidad definitiva entran en el estado de Imperturbable durante 2 turnos después de ser atacados. El daño que reciben los objetivos afectados con Imperturbable aumenta en un 10%. Si el efecto de Ruptura actual del portador es igual o superior al 150%, este daño aumenta en un 8% adicional.","El efecto de Ruptura del portador aumenta en un 70%. Los enemigos a los que ataca el portador con su habilidad definitiva entran en el estado de Imperturbable durante 2 turnos después de ser atacados. El daño que reciben los objetivos afectados con Imperturbable aumenta en un 12%. Si el efecto de Ruptura actual del portador es igual o superior al 150%, este daño aumenta en un 10% adicional.","El efecto de Ruptura del portador aumenta en un 80%. Los enemigos a los que ataca el portador con su habilidad definitiva entran en el estado de Imperturbable durante 2 turnos después de ser atacados. El daño que reciben los objetivos afectados con Imperturbable aumenta en un 14%. Si el efecto de Ruptura actual del portador es igual o superior al 150%, este daño aumenta en un 12% adicional.","El efecto de Ruptura del portador aumenta en un 90%. Los enemigos a los que ataca el portador con su habilidad definitiva entran en el estado de Imperturbable durante 2 turnos después de ser atacados. El daño que reciben los objetivos afectados con Imperturbable aumenta en un 16%. Si el efecto de Ruptura actual del portador es igual o superior al 150%, este daño aumenta en un 14% adicional.","El efecto de Ruptura del portador aumenta en un 100%. Los enemigos a los que ataca el portador con su habilidad definitiva entran en el estado de Imperturbable durante 2 turnos después de ser atacados. El daño que reciben los objetivos afectados con Imperturbable aumenta en un 18%. Si el efecto de Ruptura actual del portador es igual o superior al 150%, este daño aumenta en un 16% adicional."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Brote verde inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Semilla del árbol extraño","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110241.png","cantidad":4},{"nombre":"Brote verde inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Miel nutricia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110242.png","cantidad":4},{"nombre":"Flor etérea inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Miel nutricia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110242.png","cantidad":8},{"nombre":"Flor etérea inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Fruta del sinfín","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110243.png","cantidad":5},{"nombre":"Rama gloriosa inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Fruta del sinfín","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110243.png","cantidad":10},{"nombre":"Rama gloriosa inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23033', 'honkai-star-rail', 'Pergamino ninja: Azote deslumbrante del mal', 'Ninjutsu Inscription: Dazzling Evilbreaker', '5', 'Erudición', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23033.png', 'En algún lugar del reino ninja, un velo gris lúgubre cubre la ciudad.
"¡Iaaaa!".
Una joven se lanza entre los monstruos. Su silueta vibrante corta la oscuridad como un trazo de pintura contra una tierra sin luna.
En medio del humo, los ninjas malvados se estremecen de agonía e incredulidad.
"¿Quién... eres tú?...".
"¡Soy la ninja Rappa! Un dechado de determinación que erradica el mal y defiende la justicia".
Los ninjas malvados intercambian miradas vacilantes con los ojos muy abiertos mientras intentan huir.
"¿Están listos para decir sus poemas de muerte, villanos?".
Su shuriken baila por el aire como una ráfaga de luz y acero que abruma a sus adversarios con su velocidad cegadora.
"Técnica secreta: ¡Matriz de aniquilación deslumbrante!".
La explosión a sus espaldas destroza la noche y revela las heridas de la ciudad.
Inspirando profundamente, se lanza a la distancia iluminada por luces de neón vibrantes que gritan como un coro de metal.
"Qué espíritus malignos tan repugnantes. La cacería magnífica de la Ninja Deslumbrante continuará...".', 953, 582, 529, 'Exorcismo', '["El efecto de Ruptura del portador aumenta en un 60%. Al entrar en combate, recupera inmediatamente 30.0 pts. de energía. Tras lanzar la habilidad definitiva, el portador obtiene Elemento Rayo. Tras lanzar 2 veces el ATQ básico, la acción del portador se adelanta un 50% y Elemento Rayo se disipa. Elemento Rayo se restablece después de que el portador lance la habilidad definitiva.","El efecto de Ruptura del portador aumenta en un 70%. Al entrar en combate, recupera inmediatamente 32.5 pts. de energía. Tras lanzar la habilidad definitiva, el portador obtiene Elemento Rayo. Tras lanzar 2 veces el ATQ básico, la acción del portador se adelanta un 55% y Elemento Rayo se disipa. Elemento Rayo se restablece después de que el portador lance la habilidad definitiva.","El efecto de Ruptura del portador aumenta en un 80%. Al entrar en combate, recupera inmediatamente 35.0 pts. de energía. Tras lanzar la habilidad definitiva, el portador obtiene Elemento Rayo. Tras lanzar 2 veces el ATQ básico, la acción del portador se adelanta un 60% y Elemento Rayo se disipa. Elemento Rayo se restablece después de que el portador lance la habilidad definitiva.","El efecto de Ruptura del portador aumenta en un 90%. Al entrar en combate, recupera inmediatamente 37.5 pts. de energía. Tras lanzar la habilidad definitiva, el portador obtiene Elemento Rayo. Tras lanzar 2 veces el ATQ básico, la acción del portador se adelanta un 65% y Elemento Rayo se disipa. Elemento Rayo se restablece después de que el portador lance la habilidad definitiva.","El efecto de Ruptura del portador aumenta en un 100%. Al entrar en combate, recupera inmediatamente 40.0 pts. de energía. Tras lanzar la habilidad definitiva, el portador obtiene Elemento Rayo. Tras lanzar 2 veces el ATQ básico, la acción del portador se adelanta un 70% y Elemento Rayo se disipa. Elemento Rayo se restablece después de que el portador lance la habilidad definitiva."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Componente del acumulador de sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Bosquejo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110201.png","cantidad":4},{"nombre":"Componente del acumulador de sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Esbozo dinámico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110202.png","cantidad":4},{"nombre":"Válvula del flujo de sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Esbozo dinámico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110202.png","cantidad":8},{"nombre":"Válvula del flujo de sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Borrador con colores bellos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110203.png","cantidad":5},{"nombre":"Motor creasueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Borrador con colores bellos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110203.png","cantidad":10},{"nombre":"Motor creasueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23034', 'honkai-star-rail', 'De vuelta a la tierra', 'A Grounded Ascent', '5', 'Armonía', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23034.png', 'Esos delirios y falacias se han roto. Quería ser el sol del mundo, pero se precipitó desde el cielo.
"¿Ahora ya sabes lo que es el dolor?".
Eso dijo la otra voz en su corazón.
"Sí. Y esto es lo que me merezco".
Se hundió en el polvo y se respondió a sí mismo con sus pasos pesados.
Caminó por la tierra y volvió a contemplar la agonía que cubre el mundo mortal como un manantial que no cesa.
Cruzó las espinas que cortaban el paso y escuchó los gritos de la humanidad. Sufrió y encontró la paz.
"Así que ''caer'' no es más que otra forma de decir ''volar''".
Y al octavo día, se concedió a sí mismo su partida.', 1164, 476, 529, 'Volver a partir', '["Después de que el portador lance la habilidad básica o la habilidad definitiva sobre un personaje aliado, el portador recupera 6.0 pts. de energía y el objetivo recibe 1 acumulación de Himno sagrado durante 3 turnos. Se puede acumular hasta 3 veces. Cada acumulación de Himno sagrado aumenta el daño en un 15%. Tras cada 2 lanzamientos de la habilidad básica o la habilidad definitiva sobre un personaje aliado, el portador recupera 1 pt. de habilidad básica.","Después de que el portador lance la habilidad básica o la habilidad definitiva sobre un personaje aliado, el portador recupera 6.5 pts. de energía y el objetivo recibe 1 acumulación de Himno sagrado durante 3 turnos. Se puede acumular hasta 3 veces. Cada acumulación de Himno sagrado aumenta el daño en un 17%. Tras cada 2 lanzamientos de la habilidad básica o la habilidad definitiva sobre un personaje aliado, el portador recupera 1 pt. de habilidad básica.","Después de que el portador lance la habilidad básica o la habilidad definitiva sobre un personaje aliado, el portador recupera 7.0 pts. de energía y el objetivo recibe 1 acumulación de Himno sagrado durante 3 turnos. Se puede acumular hasta 3 veces. Cada acumulación de Himno sagrado aumenta el daño en un 20%. Tras cada 2 lanzamientos de la habilidad básica o la habilidad definitiva sobre un personaje aliado, el portador recupera 1 pt. de habilidad básica.","Después de que el portador lance la habilidad básica o la habilidad definitiva sobre un personaje aliado, el portador recupera 7.5 pts. de energía y el objetivo recibe 1 acumulación de Himno sagrado durante 3 turnos. Se puede acumular hasta 3 veces. Cada acumulación de Himno sagrado aumenta el daño en un 22%. Tras cada 2 lanzamientos de la habilidad básica o la habilidad definitiva sobre un personaje aliado, el portador recupera 1 pt. de habilidad básica.","Después de que el portador lance la habilidad básica o la habilidad definitiva sobre un personaje aliado, el portador recupera 8.0 pts. de energía y el objetivo recibe 1 acumulación de Himno sagrado durante 3 turnos. Se puede acumular hasta 3 veces. Cada acumulación de Himno sagrado aumenta el daño en un 24%. Tras cada 2 lanzamientos de la habilidad básica o la habilidad definitiva sobre un personaje aliado, el portador recupera 1 pt. de habilidad básica."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Jirones de pensamientos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114011.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Nota del firmamento","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110231.png","cantidad":4},{"nombre":"Jirones de pensamientos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114011.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Compás celestial","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110232.png","cantidad":4},{"nombre":"Fragmento de impresiones","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114012.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Compás celestial","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110232.png","cantidad":8},{"nombre":"Fragmento de impresiones","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114012.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Movimiento celestial","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110233.png","cantidad":5},{"nombre":"Fragmento de deseos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114013.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Movimiento celestial","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110233.png","cantidad":10},{"nombre":"Fragmento de deseos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114013.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23035', 'honkai-star-rail', 'El largo camino a casa', 'Long Road Leads Home', '5', 'Nihilidad', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23035.png', '"Esa... ¿quién es?". La joven acaricia a esa desconocida que es ella misma.
Recuerda cómo el fuego de ese día se la tragó entera, y cómo su abanico engastado se convirtió en cenizas.
Antes caminaba por una senda interminable y buscaba la luz que había más adelante.
Los sonidos del exterior la llamaban y la guiaban hacia adelante, ayudándola a atravesar las capas de oscuridad.
Los sonidos del interior le recordaban que las promesas incumplidas, los planes sin ejecutar y los deseos que aún no se habían hecho realidad seguían esperándola.
No habían perecido en el fuego, sino que brillaban más fuerte entre las llamas.
"Esa soy yo...".
Parada al final del camino, ya no mira hacia atrás.
"Es mi yo original... y también mi nuevo yo".', 953, 476, 662, 'Renacimiento', '["El efecto de Ruptura del portador aumenta en un 60%. Cuando se rompe la Debilidad de un enemigo, hay una probabilidad base del 100% de afectarlo con Calcinación y hacer que reciba un 18% más de Daño de Ruptura durante 2 turnos. Este efecto se puede acumular 2 veces.","El efecto de Ruptura del portador aumenta en un 70%. Cuando se rompe la Debilidad de un enemigo, hay una probabilidad base del 100% de afectarlo con Calcinación y hacer que reciba un 21% más de Daño de Ruptura durante 2 turnos. Este efecto se puede acumular 2 veces.","El efecto de Ruptura del portador aumenta en un 80%. Cuando se rompe la Debilidad de un enemigo, hay una probabilidad base del 100% de afectarlo con Calcinación y hacer que reciba un 24% más de Daño de Ruptura durante 2 turnos. Este efecto se puede acumular 2 veces.","El efecto de Ruptura del portador aumenta en un 90%. Cuando se rompe la Debilidad de un enemigo, hay una probabilidad base del 100% de afectarlo con Calcinación y hacer que reciba un 27% más de Daño de Ruptura durante 2 turnos. Este efecto se puede acumular 2 veces.","El efecto de Ruptura del portador aumenta en un 100%. Cuando se rompe la Debilidad de un enemigo, hay una probabilidad base del 100% de afectarlo con Calcinación y hacer que reciba un 30% más de Daño de Ruptura durante 2 turnos. Este efecto se puede acumular 2 veces."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Brote verde inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Espíritu ardiente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110221.png","cantidad":4},{"nombre":"Brote verde inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Esencia de fuego estelar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110222.png","cantidad":4},{"nombre":"Flor etérea inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Esencia de fuego estelar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110222.png","cantidad":8},{"nombre":"Flor etérea inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Incinerador divino","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110223.png","cantidad":5},{"nombre":"Rama gloriosa inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Incinerador divino","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110223.png","cantidad":10},{"nombre":"Rama gloriosa inmortal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/113003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23036', 'honkai-star-rail', 'Tiempo urdido en oro', 'Time Woven Into Gold', '5', 'Memoria', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23036.png', '"Esta hebra es el sacrificio de un guerrero".
"Esta hebra es el desarrollo de un héroe".
"Esta hebra es la prosperidad de la polis".
...
El Sastre tira de los hilos que sostiene entre los dedos.
"La trayectoria de algunos héroes ya se ha roto...".
Tira de otro manojo de hilos dorados y sigue zurciendo.
"El destino de algunos héroes debe seguir extendiéndose hacia adelante...".
El telar al que se ha otorgado la divinidad sigue trabajando y los Sastres danzan con gracia. Por el telar ya han pasado miles de años, y ella está acostumbrada a esperar.
A esperar esa inspiración del tiempo urdido en oro.', 1058, 635, 397, 'Creación', '["La VEL base del portador aumenta en 12 pts. Después de que el portador o su mnemoduende ataquen, el portador obtiene una acumulación de Bordado. Cada acumulación de Bordado aumenta el Daño CRIT del portador y de su mnemoduende en un 9.0%. Se puede acumular hasta 6 veces. Cuando las acumulaciones llegan al límite, cada acumulación de Bordado aumenta el daño de ATQ básico infligido en un 9.0% adicional.","La VEL base del portador aumenta en 14 pts. Después de que el portador o su mnemoduende ataquen, el portador obtiene una acumulación de Bordado. Cada acumulación de Bordado aumenta el Daño CRIT del portador y de su mnemoduende en un 10.5%. Se puede acumular hasta 6 veces. Cuando las acumulaciones llegan al límite, cada acumulación de Bordado aumenta el daño de ATQ básico infligido en un 10.5% adicional.","La VEL base del portador aumenta en 16 pts. Después de que el portador o su mnemoduende ataquen, el portador obtiene una acumulación de Bordado. Cada acumulación de Bordado aumenta el Daño CRIT del portador y de su mnemoduende en un 12.0%. Se puede acumular hasta 6 veces. Cuando las acumulaciones llegan al límite, cada acumulación de Bordado aumenta el daño de ATQ básico infligido en un 12.0% adicional.","La VEL base del portador aumenta en 18 pts. Después de que el portador o su mnemoduende ataquen, el portador obtiene una acumulación de Bordado. Cada acumulación de Bordado aumenta el Daño CRIT del portador y de su mnemoduende en un 13.5%. Se puede acumular hasta 6 veces. Cuando las acumulaciones llegan al límite, cada acumulación de Bordado aumenta el daño de ATQ básico infligido en un 13.5% adicional.","La VEL base del portador aumenta en 20 pts. Después de que el portador o su mnemoduende ataquen, el portador obtiene una acumulación de Bordado. Cada acumulación de Bordado aumenta el Daño CRIT del portador y de su mnemoduende en un 15.0%. Se puede acumular hasta 6 veces. Cuando las acumulaciones llegan al límite, cada acumulación de Bordado aumenta el daño de ATQ básico infligido en un 15.0% adicional."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Carne pisoteada del miedo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Semilla de la reflexión","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110251.png","cantidad":4},{"nombre":"Carne pisoteada del miedo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Brote de manas","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110252.png","cantidad":4},{"nombre":"Pecho hendido del valor","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Brote de manas","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110252.png","cantidad":8},{"nombre":"Pecho hendido del valor","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Alayawah","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110253.png","cantidad":5},{"nombre":"Torso bautizado de gloria","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Alayawah","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110253.png","cantidad":10},{"nombre":"Torso bautizado de gloria","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23037', 'honkai-star-rail', 'Hacia lo inescrutable', 'Into the Unreachable Veil', '5', 'Erudición', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23037.png', '"Las cartas de la Sociedad del Conocimiento ya se han procesado".
"El Universo Simulado funciona correctamente".
"Se han reeditado las antologías de sus escritos".
"¡Shhh! ¡Hablen más bajo! ¡No molesten a la señora Herta!".
En una torre que se yergue en los confines del cosmos, las marionetas se ocupan metódicamente de toda clase de asuntos mientras esperan su llegada.
Pasa el tiempo. Innumerables personas cruzan la noche de la historia como meteoros: brillan por un instante y vuelven al silencio.
"La señora Herta no ha aparecido en mucho tiempo...".
"¿Seguirá pensando?".
"¡Hum! ¿Pensaban que esto terminaría tras descubrir unos cuantos axiomas?".
Se despereza y levanta la vista de sus cálculos. Otro pensamiento le viene a la mente.
"¡No hay nada de lo que no se pueda dudar! ¡Yo haré todas las preguntas!".', 953, 635, 463, 'Juego mental', '["La Prob. CRIT del portador aumenta en un 12%. Cuando el portador lanza la habilidad definitiva, el daño de habilidad básica y habilidad definitiva que inflige aumenta en un 60% durante 3 turnos. Si el portador consume 140 pts. de energía o más al lanzar la habilidad definitiva, recupera 1 pt. de habilidad básica.","La Prob. CRIT del portador aumenta en un 14%. Cuando el portador lanza la habilidad definitiva, el daño de habilidad básica y habilidad definitiva que inflige aumenta en un 70% durante 3 turnos. Si el portador consume 140 pts. de energía o más al lanzar la habilidad definitiva, recupera 1 pt. de habilidad básica.","La Prob. CRIT del portador aumenta en un 16%. Cuando el portador lanza la habilidad definitiva, el daño de habilidad básica y habilidad definitiva que inflige aumenta en un 80% durante 3 turnos. Si el portador consume 140 pts. de energía o más al lanzar la habilidad definitiva, recupera 1 pt. de habilidad básica.","La Prob. CRIT del portador aumenta en un 18%. Cuando el portador lanza la habilidad definitiva, el daño de habilidad básica y habilidad definitiva que inflige aumenta en un 90% durante 3 turnos. Si el portador consume 140 pts. de energía o más al lanzar la habilidad definitiva, recupera 1 pt. de habilidad básica.","La Prob. CRIT del portador aumenta en un 20%. Cuando el portador lanza la habilidad definitiva, el daño de habilidad básica y habilidad definitiva que inflige aumenta en un 100% durante 3 turnos. Si el portador consume 140 pts. de energía o más al lanzar la habilidad definitiva, recupera 1 pt. de habilidad básica."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Núcleo apagado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Bosquejo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110201.png","cantidad":4},{"nombre":"Núcleo apagado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Esbozo dinámico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110202.png","cantidad":4},{"nombre":"Núcleo reluciente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Esbozo dinámico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110202.png","cantidad":8},{"nombre":"Núcleo reluciente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Borrador con colores bellos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110203.png","cantidad":5},{"nombre":"Núcleo serpenteante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Borrador con colores bellos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110203.png","cantidad":10},{"nombre":"Núcleo serpenteante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23038', 'honkai-star-rail', 'Si el tiempo fuera una flor', 'If Time Were a Flower', '5', 'Armonía', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23038.png', '"¡Mamá, quiero que me cuentes otra historia!".
"¿Qué te parece si te cuento una historia sobre el tiempo, cariño?".
"¿Qué es el tiempo?".
"El tiempo es como una flor".
"¿Es una de esas flores de diente de león que crecen en los campos?".
"Sí, igual que las flores de diente de león, el tiempo crece, florece y madura. A sus pétalos los llamamos ''momentos''".
"¿Y qué pasa después?".
"Después, se marchita y se convierte en miles de semillas que vuelan a todas partes...".
"¿Mamá, eso no es lo que se llama ''futuro''?".
"Adivina en qué se convierte después de eso".
"Se convertirá en un mar de flores coloridas, ¿verdad?".
Antes de que su madre pueda responder, los rayos del sol acarician el rostro de la niña a través de la ventana, y la dulce figura de su madre desaparece una vez más en el sueño.
La niña abre los ojos.
"Si el tiempo fuera una flor...", murmura.
"Seguro que se convertiría en un mar de flores", responde la niña tranquila.
"¡Por supuesto!", dice la niña traviesa, celebrando su obra maestra.', 1270, 529, 397, 'Esperanza', '["El Daño CRIT del portador aumenta en un 36%. Tras lanzar un ataque adicional, el portador recupera adicionalmente 12 pts. de energía y obtiene Vaticinio durante 2 turnos. Cuando el portador tiene Vaticinio, el Daño CRIT de todos los aliados aumenta en un 48%. Al entrar en combate, el portador recupera 21 pts. de energía y obtiene Vaticinio durante 2 turnos.","El Daño CRIT del portador aumenta en un 42%. Tras lanzar un ataque adicional, el portador recupera adicionalmente 12 pts. de energía y obtiene Vaticinio durante 2 turnos. Cuando el portador tiene Vaticinio, el Daño CRIT de todos los aliados aumenta en un 60%. Al entrar en combate, el portador recupera 21 pts. de energía y obtiene Vaticinio durante 2 turnos.","El Daño CRIT del portador aumenta en un 48%. Tras lanzar un ataque adicional, el portador recupera adicionalmente 12 pts. de energía y obtiene Vaticinio durante 2 turnos. Cuando el portador tiene Vaticinio, el Daño CRIT de todos los aliados aumenta en un 72%. Al entrar en combate, el portador recupera 21 pts. de energía y obtiene Vaticinio durante 2 turnos.","El Daño CRIT del portador aumenta en un 54%. Tras lanzar un ataque adicional, el portador recupera adicionalmente 12 pts. de energía y obtiene Vaticinio durante 2 turnos. Cuando el portador tiene Vaticinio, el Daño CRIT de todos los aliados aumenta en un 84%. Al entrar en combate, el portador recupera 21 pts. de energía y obtiene Vaticinio durante 2 turnos.","El Daño CRIT del portador aumenta en un 60%. Tras lanzar un ataque adicional, el portador recupera adicionalmente 12 pts. de energía y obtiene Vaticinio durante 2 turnos. Cuando el portador tiene Vaticinio, el Daño CRIT de todos los aliados aumenta en un 96%. Al entrar en combate, el portador recupera 21 pts. de energía y obtiene Vaticinio durante 2 turnos."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Carne pisoteada del miedo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Nota del firmamento","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110231.png","cantidad":4},{"nombre":"Carne pisoteada del miedo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Compás celestial","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110232.png","cantidad":4},{"nombre":"Pecho hendido del valor","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Compás celestial","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110232.png","cantidad":8},{"nombre":"Pecho hendido del valor","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Movimiento celestial","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110233.png","cantidad":5},{"nombre":"Torso bautizado de gloria","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Movimiento celestial","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110233.png","cantidad":10},{"nombre":"Torso bautizado de gloria","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23039', 'honkai-star-rail', 'Sangre y fuego, abran camino', 'Flame of Blood, Blaze My Path', '5', 'Destrucción', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23039.png', 'El rocío helado se condensa en la hoja de la espada, dejando un rastro carmesí.
Un olor a óxido cubre el paraje desolado, donde aún quedan rescoldos de las llamas que rugieron en la batalla.
"Mideimos, ¡peleaste como los dioses!",
grita con emoción un guerrero con el torso desnudo mientras limpia su arma.
"¡Algún día seré un guerrero invencible, como tú!",
dice apenas un niño mirándolo con veneración, con una espada rota en la mano.
"Príncipe, es hora de regresar a Castrum Kremnos",
un anciano curtido sonríe mientras alza su copa en un brindis.
Él asiente con la cabeza y anda hasta llegar al final del campamento.
El dolor de la vuelta a la vida sigue recorriendo su piel. Mañana liderará al destacamento de Kremnos hacia una tierra extranjera.
No sabe a dónde irá, pero lo único de lo que está seguro es que cargará con la responsabilidad de un rey hasta que la sangre y el fuego lo consuman.
La noche se alarga mientras bebe a solas el licor sanguino. Un rapsoda de paso toca las cuerdas, y una melodía errabunda resuena en el aire.
"El hogar está en los sueños, y no es un lugar al que se pueda llegar".', 1376, 476, 397, 'Contemplación', '["Los PV máx. del portador aumentan en un 18% y la curación recibida aumenta en un 20%. Al lanzar la habilidad básica o la habilidad definitiva, consume un 6.0% de sus PV máx. y aumenta el daño que inflige ese ataque en un 30%. Si el efecto consume más de 500 PV, el daño aumenta en un 30% adicional.\nSi los PV actuales del portador son insuficientes, este efecto reduce sus PV actuales a 1.","Los PV máx. del portador aumentan en un 21% y la curación recibida aumenta en un 25%. Al lanzar la habilidad básica o la habilidad definitiva, consume un 6.5% de sus PV máx. y aumenta el daño que inflige ese ataque en un 35%. Si el efecto consume más de 500 PV, el daño aumenta en un 35% adicional.\nSi los PV actuales del portador son insuficientes, este efecto reduce sus PV actuales a 1.","Los PV máx. del portador aumentan en un 24% y la curación recibida aumenta en un 30%. Al lanzar la habilidad básica o la habilidad definitiva, consume un 7.0% de sus PV máx. y aumenta el daño que inflige ese ataque en un 40%. Si el efecto consume más de 500 PV, el daño aumenta en un 40% adicional.\nSi los PV actuales del portador son insuficientes, este efecto reduce sus PV actuales a 1.","Los PV máx. del portador aumentan en un 27% y la curación recibida aumenta en un 35%. Al lanzar la habilidad básica o la habilidad definitiva, consume un 7.5% de sus PV máx. y aumenta el daño que inflige ese ataque en un 45%. Si el efecto consume más de 500 PV, el daño aumenta en un 45% adicional.\nSi los PV actuales del portador son insuficientes, este efecto reduce sus PV actuales a 1.","Los PV máx. del portador aumentan en un 30% y la curación recibida aumenta en un 40%. Al lanzar la habilidad básica o la habilidad definitiva, consume un 8.0% de sus PV máx. y aumenta el daño que inflige ese ataque en un 50%. Si el efecto consume más de 500 PV, el daño aumenta en un 50% adicional.\nSi los PV actuales del portador son insuficientes, este efecto reduce sus PV actuales a 1."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Carne pisoteada del miedo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Canino de borisin","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110181.png","cantidad":4},{"nombre":"Carne pisoteada del miedo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Diente serrado con lupitoxina","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110182.png","cantidad":4},{"nombre":"Pecho hendido del valor","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Diente serrado con lupitoxina","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110182.png","cantidad":8},{"nombre":"Pecho hendido del valor","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Colmillo de la locura lunar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110183.png","cantidad":5},{"nombre":"Torso bautizado de gloria","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Colmillo de la locura lunar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110183.png","cantidad":10},{"nombre":"Torso bautizado de gloria","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23040', 'honkai-star-rail', 'Despedidas más bellas', 'Make Farewells More Beautiful', '5', 'Memoria', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23040.png', 'Era otra ceremonia de despedida.
Una joven, caminando sobre luz de luna fragmentada, teje una guirnalda de despedida en la ribera.
Una antigua elegía se congela en el aire helado, mientras el río silencioso fluye hacia la lejana tierra de las flores.
Pergaminos manchados de sangre, espadas oxidadas, pañuelos bordados con versos... Ella acepta estas pertenencias, junto a las historias vitales de sus antiguos dueños.
"Mis ojos son como lentes, siempre anhelando las estrellas".
Era una inscripción en la lápida de un erudito fallecido.
"En la vida y en la muerte, un caballero solo lanza una mirada fría".
Ese fue el lema que un guerrero sin nombre mantuvo toda su vida.
"La vida no es más que muerte que brilla momentáneamente".
Ese era el último verso de un poeta que buscaba la eternidad.
... 
"Cada flor se abrió orgullosa una vez...".
Acompañada por el murmullo del río, ofrece poemas, guirnaldas y recuerdos a los difuntos.
"Si el marchitamiento es inevitable, que nuestras despedidas al menos sean... algo más bellas".', 1270, 529, 397, 'Inscripción', '["Los PV máx. del portador aumentan en un 30%. Cuando el portador o su mnemoduende pierden PV durante su propio turno, el portador obtiene Flor de ultratumba. Flor de ultratumba hace que el portador y su mnemoduende ignoren un 30% de la DEF de los objetivos al infligir daño durante 2 turnos.\nCuando el mnemoduende del portador desaparece, el portador adelanta su acción un 12%. Este efecto solo se puede activar 1 vez, y el contador de activaciones se reinicia cada vez que el portador lanza la habilidad definitiva.","Los PV máx. del portador aumentan en un 38%. Cuando el portador o su mnemoduende pierden PV durante su propio turno, el portador obtiene Flor de ultratumba. Flor de ultratumba hace que el portador y su mnemoduende ignoren un 35% de la DEF de los objetivos al infligir daño durante 2 turnos.\nCuando el mnemoduende del portador desaparece, el portador adelanta su acción un 15%. Este efecto solo se puede activar 1 vez, y el contador de activaciones se reinicia cada vez que el portador lanza la habilidad definitiva.","Los PV máx. del portador aumentan en un 45%. Cuando el portador o su mnemoduende pierden PV durante su propio turno, el portador obtiene Flor de ultratumba. Flor de ultratumba hace que el portador y su mnemoduende ignoren un 40% de la DEF de los objetivos al infligir daño durante 2 turnos.\nCuando el mnemoduende del portador desaparece, el portador adelanta su acción un 18%. Este efecto solo se puede activar 1 vez, y el contador de activaciones se reinicia cada vez que el portador lanza la habilidad definitiva.","Los PV máx. del portador aumentan en un 53%. Cuando el portador o su mnemoduende pierden PV durante su propio turno, el portador obtiene Flor de ultratumba. Flor de ultratumba hace que el portador y su mnemoduende ignoren un 45% de la DEF de los objetivos al infligir daño durante 2 turnos.\nCuando el mnemoduende del portador desaparece, el portador adelanta su acción un 21%. Este efecto solo se puede activar 1 vez, y el contador de activaciones se reinicia cada vez que el portador lanza la habilidad definitiva.","Los PV máx. del portador aumentan en un 60%. Cuando el portador o su mnemoduende pierden PV durante su propio turno, el portador obtiene Flor de ultratumba. Flor de ultratumba hace que el portador y su mnemoduende ignoren un 50% de la DEF de los objetivos al infligir daño durante 2 turnos.\nCuando el mnemoduende del portador desaparece, el portador adelanta su acción un 24%. Este efecto solo se puede activar 1 vez, y el contador de activaciones se reinicia cada vez que el portador lanza la habilidad definitiva."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Augurio etéreo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115011.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Semilla de la reflexión","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110251.png","cantidad":4},{"nombre":"Augurio etéreo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115011.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Brote de manas","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110252.png","cantidad":4},{"nombre":"Gemido resonante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115012.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Brote de manas","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110252.png","cantidad":8},{"nombre":"Gemido resonante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115012.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Alayawah","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110253.png","cantidad":5},{"nombre":"Lamento eterno","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115013.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Alayawah","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110253.png","cantidad":10},{"nombre":"Lamento eterno","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115013.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23041', 'honkai-star-rail', 'La vida en llamas', 'Life Should Be Cast to Flames', '5', 'Erudición', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23041.png', 'Durante ese experimento secreto, todo tipo de ilusiones aparecían, intentando estorbar su avance.
Suaves susurros le instaban a abandonar ese tema de investigación tan peligroso, ¿por qué arriesgar la vida?
Una fría voz amenazante le advertía que quienes caminan por la delgada línea entre la vida y la muerte acaban muriendo entre llamas.
Y otras voces indignadas lo acusaban de sacrílego y pedían a gritos arrojarlo al cadalso como un criminal.
"El telón también ha de acabar cayendo para el espectáculo que es la vida".
Él cierra los ojos, aferra la Yesca divina y deja que el dolor ahogue su alma moribunda.
Primero, su mirada decidida. Luego, su corazón palpitante. Y, finalmente, toda su alma... Él mismo se arroja a las llamas de forja más puras e intensas.
Las voces entran en ebullición y luego caen en un silencio absoluto.
En medio de la oscuridad, la verdad brillante empieza a tomar forma en sus manos.', 953, 582, 529, 'Fundición', '["Cuando comienza su turno, el portador recupera 10 pts. de energía. Si el enemigo tiene una Debilidad implantada por el portador, el daño que le inflige el portador aumenta en un 60%.\nCuando el enemigo recibe un ataque del portador, su DEF se reduce en un 12% durante 2 turnos. Los efectos del mismo tipo no se pueden acumular.","Cuando comienza su turno, el portador recupera 10 pts. de energía. Si el enemigo tiene una Debilidad implantada por el portador, el daño que le inflige el portador aumenta en un 70%.\nCuando el enemigo recibe un ataque del portador, su DEF se reduce en un 15% durante 2 turnos. Los efectos del mismo tipo no se pueden acumular.","Cuando comienza su turno, el portador recupera 10 pts. de energía. Si el enemigo tiene una Debilidad implantada por el portador, el daño que le inflige el portador aumenta en un 80%.\nCuando el enemigo recibe un ataque del portador, su DEF se reduce en un 18% durante 2 turnos. Los efectos del mismo tipo no se pueden acumular.","Cuando comienza su turno, el portador recupera 10 pts. de energía. Si el enemigo tiene una Debilidad implantada por el portador, el daño que le inflige el portador aumenta en un 90%.\nCuando el enemigo recibe un ataque del portador, su DEF se reduce en un 21% durante 2 turnos. Los efectos del mismo tipo no se pueden acumular.","Cuando comienza su turno, el portador recupera 10 pts. de energía. Si el enemigo tiene una Debilidad implantada por el portador, el daño que le inflige el portador aumenta en un 100%.\nCuando el enemigo recibe un ataque del portador, su DEF se reduce en un 24% durante 2 turnos. Los efectos del mismo tipo no se pueden acumular."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Augurio etéreo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115011.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Bosquejo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110201.png","cantidad":4},{"nombre":"Augurio etéreo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115011.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Esbozo dinámico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110202.png","cantidad":4},{"nombre":"Gemido resonante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115012.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Esbozo dinámico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110202.png","cantidad":8},{"nombre":"Gemido resonante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115012.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Borrador con colores bellos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110203.png","cantidad":5},{"nombre":"Lamento eterno","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115013.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Borrador con colores bellos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110203.png","cantidad":10},{"nombre":"Lamento eterno","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115013.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23042', 'honkai-star-rail', 'Que el arcoíris siempre esté en el cielo', 'Long May Rainbows Adorn the Sky', '5', 'Memoria', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23042.png', '"Las emociones son como nubes, y nosotros somos el cielo que las lleva. Si el cielo está nublado, nuestro estado de ánimo oscilará entre la luz y la sombra".
La sanadora escucha atentamente las penas del paciente, y le ofrece suaves palabras de consuelo.
"Cierra los ojos y respira lentamente... Imagina que estás en un lugar cálido y acogedor...".
Sus palabras parecen tener magia, y bajo las alas de la bestia alada se derrama un resplandor irisado de siete colores.
"Una brisa suave recorre el campo, trayendo el aroma de las flores silvestres. Nubes húmedas pasan, cargadas de sol...".
El paciente se sumerge gradualmente en un sueño agradable, y responde solo con una respiración uniforme y queda.
Después de atender al último paciente, la sanadora cierra suavemente la puerta de la sala.
La noche eterna sigue agitándose en la distancia, y las ruinas se asemejan a cicatrices en la tierra.
"En la próxima vida, que el amanecer ilumine a todos...".
Antes de partir, ella cierra los ojos y pide un deseo...
"Que el arcoíris siempre esté en el cielo".', 1164, 476, 529, 'Tolerancia', '["La VEL del portador aumenta en un 18%. Cuando el portador lanza el ATQ básico, la habilidad básica o la habilidad definitiva, consume un 1.0% de los PV actuales de todos los aliados, y el mnemoduende del portador, tras su siguiente ataque, inflige adicionalmente a los objetivos golpeados un 250.0% de los PV consumidos totales como daño adicional del mismo tipo que el mnemoduende del portador. Después, se reinicia este total de PV consumidos. Cuando el mnemoduende del portador lanza la habilidad de mnemoduende, el daño que reciben todos los enemigos aumenta en un 18.0% durante 2 turnos. Los efectos del mismo tipo no se pueden acumular.","La VEL del portador aumenta en un 21%. Cuando el portador lanza el ATQ básico, la habilidad básica o la habilidad definitiva, consume un 1.3% de los PV actuales de todos los aliados, y el mnemoduende del portador, tras su siguiente ataque, inflige adicionalmente a los objetivos golpeados un 312.5% de los PV consumidos totales como daño adicional del mismo tipo que el mnemoduende del portador. Después, se reinicia este total de PV consumidos. Cuando el mnemoduende del portador lanza la habilidad de mnemoduende, el daño que reciben todos los enemigos aumenta en un 22.5% durante 2 turnos. Los efectos del mismo tipo no se pueden acumular.","La VEL del portador aumenta en un 24%. Cuando el portador lanza el ATQ básico, la habilidad básica o la habilidad definitiva, consume un 1.5% de los PV actuales de todos los aliados, y el mnemoduende del portador, tras su siguiente ataque, inflige adicionalmente a los objetivos golpeados un 375.0% de los PV consumidos totales como daño adicional del mismo tipo que el mnemoduende del portador. Después, se reinicia este total de PV consumidos. Cuando el mnemoduende del portador lanza la habilidad de mnemoduende, el daño que reciben todos los enemigos aumenta en un 27.0% durante 2 turnos. Los efectos del mismo tipo no se pueden acumular.","La VEL del portador aumenta en un 27%. Cuando el portador lanza el ATQ básico, la habilidad básica o la habilidad definitiva, consume un 1.8% de los PV actuales de todos los aliados, y el mnemoduende del portador, tras su siguiente ataque, inflige adicionalmente a los objetivos golpeados un 437.5% de los PV consumidos totales como daño adicional del mismo tipo que el mnemoduende del portador. Después, se reinicia este total de PV consumidos. Cuando el mnemoduende del portador lanza la habilidad de mnemoduende, el daño que reciben todos los enemigos aumenta en un 31.5% durante 2 turnos. Los efectos del mismo tipo no se pueden acumular.","La VEL del portador aumenta en un 30%. Cuando el portador lanza el ATQ básico, la habilidad básica o la habilidad definitiva, consume un 2.0% de los PV actuales de todos los aliados, y el mnemoduende del portador, tras su siguiente ataque, inflige adicionalmente a los objetivos golpeados un 500.0% de los PV consumidos totales como daño adicional del mismo tipo que el mnemoduende del portador. Después, se reinicia este total de PV consumidos. Cuando el mnemoduende del portador lanza la habilidad de mnemoduende, el daño que reciben todos los enemigos aumenta en un 36.0% durante 2 turnos. Los efectos del mismo tipo no se pueden acumular."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Carne pisoteada del miedo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Semilla de la reflexión","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110251.png","cantidad":4},{"nombre":"Carne pisoteada del miedo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Brote de manas","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110252.png","cantidad":4},{"nombre":"Pecho hendido del valor","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Brote de manas","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110252.png","cantidad":8},{"nombre":"Pecho hendido del valor","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Alayawah","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110253.png","cantidad":5},{"nombre":"Torso bautizado de gloria","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Alayawah","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110253.png","cantidad":10},{"nombre":"Torso bautizado de gloria","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23043', 'honkai-star-rail', 'Mentiras que vuelan en el viento', 'Lies Dance on the Breeze', '5', 'Nihilidad', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23043.png', 'La chica con orejas de gato se estira sobre el tejado y se desliza hacia la noche.
La joven se mueve ágilmente por la bóveda silente durante milenios, toma los tesoros en sus brazos y escapa sin dejar rastro.
"¡Destino tonto, no me alcanzarás!".
El viento en las ruinas, cargado del olor del campo, mueve la capucha de la chica.
Apoyada en las frías piedras, traga un bocado de sus ásperas raciones mientras juguetea con una moneda de oro entre los dedos.
Un sonido lejano llega a sus oídos. En la ciudad sagrada iluminada por el alba, la multitud bulliciosa sigue inmersa en sus celebraciones mientras disfruta de la calidez.
"¿Cuánto tiempo más?... ¿Será un año, o diez mil años?".
Ella se estira y bosteza, y echa a un lado sus inquietudes.
"¡Ja, Ciferia siempre reirá la última!".
Un relámpago dorado surca el cielo, mientras la proclama de la joven aún resuena en el viento...
Igual que hace mil años.', 953, 582, 529, 'Embaucamiento', '["La VEL del portador aumenta en un 18%. Después de que el portador ataque, cada enemigo tiene un 120% de probabilidad base de ser afectado con Desconcierto. La DEF de los enemigos en el estado de Desconcierto se reduce en un 16% durante 2 turnos. Si la VEL del portador es igual o superior a 170, cada enemigo tiene además un 120% de probabilidad base de ser afectado con Robado. La DEF de los enemigos en el estado de Robado se reduce en un 8% durante 2 turnos. Si Desconcierto o Robado se aplican repetidamente, solo tiene efecto la última aplicación de cada uno.","La VEL del portador aumenta en un 21%. Después de que el portador ataque, cada enemigo tiene un 120% de probabilidad base de ser afectado con Desconcierto. La DEF de los enemigos en el estado de Desconcierto se reduce en un 18% durante 2 turnos. Si la VEL del portador es igual o superior a 170, cada enemigo tiene además un 120% de probabilidad base de ser afectado con Robado. La DEF de los enemigos en el estado de Robado se reduce en un 9% durante 2 turnos. Si Desconcierto o Robado se aplican repetidamente, solo tiene efecto la última aplicación de cada uno.","La VEL del portador aumenta en un 24%. Después de que el portador ataque, cada enemigo tiene un 120% de probabilidad base de ser afectado con Desconcierto. La DEF de los enemigos en el estado de Desconcierto se reduce en un 20% durante 2 turnos. Si la VEL del portador es igual o superior a 170, cada enemigo tiene además un 120% de probabilidad base de ser afectado con Robado. La DEF de los enemigos en el estado de Robado se reduce en un 10% durante 2 turnos. Si Desconcierto o Robado se aplican repetidamente, solo tiene efecto la última aplicación de cada uno.","La VEL del portador aumenta en un 27%. Después de que el portador ataque, cada enemigo tiene un 120% de probabilidad base de ser afectado con Desconcierto. La DEF de los enemigos en el estado de Desconcierto se reduce en un 22% durante 2 turnos. Si la VEL del portador es igual o superior a 170, cada enemigo tiene además un 120% de probabilidad base de ser afectado con Robado. La DEF de los enemigos en el estado de Robado se reduce en un 11% durante 2 turnos. Si Desconcierto o Robado se aplican repetidamente, solo tiene efecto la última aplicación de cada uno.","La VEL del portador aumenta en un 30%. Después de que el portador ataque, cada enemigo tiene un 120% de probabilidad base de ser afectado con Desconcierto. La DEF de los enemigos en el estado de Desconcierto se reduce en un 24% durante 2 turnos. Si la VEL del portador es igual o superior a 170, cada enemigo tiene además un 120% de probabilidad base de ser afectado con Robado. La DEF de los enemigos en el estado de Robado se reduce en un 12% durante 2 turnos. Si Desconcierto o Robado se aplican repetidamente, solo tiene efecto la última aplicación de cada uno."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Augurio etéreo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115011.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Espíritu ardiente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110221.png","cantidad":4},{"nombre":"Augurio etéreo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115011.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Esencia de fuego estelar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110222.png","cantidad":4},{"nombre":"Gemido resonante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115012.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Esencia de fuego estelar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110222.png","cantidad":8},{"nombre":"Gemido resonante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115012.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Incinerador divino","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110223.png","cantidad":5},{"nombre":"Lamento eterno","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115013.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Incinerador divino","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110223.png","cantidad":10},{"nombre":"Lamento eterno","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115013.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23044', 'honkai-star-rail', 'Que arda el alba', 'Thus Burns the Dawn', '5', 'Destrucción', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23044.png', 'Una vez más, al final del viaje, la silueta del hombre fue devorada por el abrasador sol dorado.
"Entonces, esa sangre dorada, esa esperanza de salvación, era en realidad...".
Sus lágrimas no alcanzaron a caer y se desvanecieron en vapor.
"¡Hasta mañana, Fai!".
"¡Salvador, recuerda vivir hasta el final!".
"Ve y conviértete en el amanecer de Amphoreus...".

Los deseos de la gente resonaron en el vacío. El héroe sin nombre se hizo pedazos, dejando al descubierto una muerte feroz y trágica.
"Si la furia no puede reducir este destino retorcido a cenizas...".
Subió hacia la cima una y otra vez, solo para caer y romperse, una y otra vez.
"¡Entonces, que me consuma junto a él!".', 953, 688, 397, 'Desposesión', '["La VEL base del portador aumenta en 12 y este ignora un 18% de la DEF del objetivo cuando inflige daño. Después de que el portador lance su habilidad definitiva, obtiene Sol abrasador, el cual se disipa al comenzar el turno. Cuando tiene Sol abrasador, el daño que inflige el portador aumenta en un 60%.","La VEL base del portador aumenta en 14 y este ignora un 23% de la DEF del objetivo cuando inflige daño. Después de que el portador lance su habilidad definitiva, obtiene Sol abrasador, el cual se disipa al comenzar el turno. Cuando tiene Sol abrasador, el daño que inflige el portador aumenta en un 78%.","La VEL base del portador aumenta en 16 y este ignora un 27% de la DEF del objetivo cuando inflige daño. Después de que el portador lance su habilidad definitiva, obtiene Sol abrasador, el cual se disipa al comenzar el turno. Cuando tiene Sol abrasador, el daño que inflige el portador aumenta en un 96%.","La VEL base del portador aumenta en 18 y este ignora un 32% de la DEF del objetivo cuando inflige daño. Después de que el portador lance su habilidad definitiva, obtiene Sol abrasador, el cual se disipa al comenzar el turno. Cuando tiene Sol abrasador, el daño que inflige el portador aumenta en un 114%.","La VEL base del portador aumenta en 20 y este ignora un 36% de la DEF del objetivo cuando inflige daño. Después de que el portador lance su habilidad definitiva, obtiene Sol abrasador, el cual se disipa al comenzar el turno. Cuando tiene Sol abrasador, el daño que inflige el portador aumenta en un 132%."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Augurio etéreo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115011.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Canino de borisin","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110181.png","cantidad":4},{"nombre":"Augurio etéreo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115011.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Diente serrado con lupitoxina","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110182.png","cantidad":4},{"nombre":"Gemido resonante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115012.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Diente serrado con lupitoxina","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110182.png","cantidad":8},{"nombre":"Gemido resonante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115012.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Colmillo de la locura lunar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110183.png","cantidad":5},{"nombre":"Lamento eterno","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115013.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Colmillo de la locura lunar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110183.png","cantidad":10},{"nombre":"Lamento eterno","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115013.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23045', 'honkai-star-rail', 'Coronación sin agradecimiento', 'A Thankless Coronation', '5', 'Destrucción', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23045.png', 'Los oídos de la joven resonaban en la ilusión con las palabras que se habían dicho aquel día.
"Merlín, esta espada no fue difícil de sacar en absoluto".
"Así es. Convertirte en el rey que todos desean tampoco será difícil para ti. Después de todo, tienes mi guía. Sin embargo, Altria... lo realmente difícil es que no podrás cumplir siempre con las expectativas de todos".
"Cuando eso pase, pueden elegir a un rey más adecuado. Yo no me opondré".
"¿Y si esa persona nunca llega a existir?".
"... Entonces, me esforzaré por cumplir con las expectativas de todos".
Ahora, la joven comprendía bien lo que supondría esa tragedia. ¿Habría elegido rendirse si pudiera regresar a ese instante donde todo comenzó?
El rey no responde, solo aprieta con fuerza la empuñadura de la espada.
Una vez más, la roca retumba con estruendo mientras la espada sale de ella.', 953, 582, 529, 'Rey de los caballeros', '["El Daño CRIT del portador aumenta en un 36%. Cuando el portador lanza su habilidad definitiva, su ATQ aumenta en un 40%. Si la energía máxima del portador es igual o mayor que 300, recupera una cantidad fija de energía equivalente al 10% de su energía máxima y su ATQ vuelve a aumentar en un 40% durante 2 turnos.","El Daño CRIT del portador aumenta en un 45%. Cuando el portador lanza su habilidad definitiva, su ATQ aumenta en un 50%. Si la energía máxima del portador es igual o mayor que 300, recupera una cantidad fija de energía equivalente al 10% de su energía máxima y su ATQ vuelve a aumentar en un 50% durante 2 turnos.","El Daño CRIT del portador aumenta en un 54%. Cuando el portador lanza su habilidad definitiva, su ATQ aumenta en un 60%. Si la energía máxima del portador es igual o mayor que 300, recupera una cantidad fija de energía equivalente al 10% de su energía máxima y su ATQ vuelve a aumentar en un 60% durante 2 turnos.","El Daño CRIT del portador aumenta en un 63%. Cuando el portador lanza su habilidad definitiva, su ATQ aumenta en un 70%. Si la energía máxima del portador es igual o mayor que 300, recupera una cantidad fija de energía equivalente al 10% de su energía máxima y su ATQ vuelve a aumentar en un 70% durante 2 turnos.","El Daño CRIT del portador aumenta en un 72%. Cuando el portador lanza su habilidad definitiva, su ATQ aumenta en un 80%. Si la energía máxima del portador es igual o mayor que 300, recupera una cantidad fija de energía equivalente al 10% de su energía máxima y su ATQ vuelve a aumentar en un 80% durante 2 turnos."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Instinto del ladrón","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111011.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Canino de borisin","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110181.png","cantidad":4},{"nombre":"Instinto del ladrón","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111011.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Diente serrado con lupitoxina","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110182.png","cantidad":4},{"nombre":"Ambición distorsionada","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111012.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Diente serrado con lupitoxina","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110182.png","cantidad":8},{"nombre":"Ambición distorsionada","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111012.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Colmillo de la locura lunar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110183.png","cantidad":5},{"nombre":"Voluntad de conquista","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111013.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Colmillo de la locura lunar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110183.png","cantidad":10},{"nombre":"Voluntad de conquista","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111013.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23046', 'honkai-star-rail', 'Infierno donde arden los ideales', 'The Hell Where Ideals Burn', '5', 'Cacería', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23046.png', 'Las llamas del karma arden sobre las llanuras. Los ideales de unos se reducen a cenizas, mientras los de otros arden con pasión.
El guardián atraviesa el campo entre balas y flechas.
Aquí no hay nadie a quien pueda salvar. Aquí están todos aquellos a quienes desearía poder salvar.
Matar a uno para salvar a otro. Matar a diez mil para salvar a diez mil. El destino de pisotear al prójimo también es parte del ciclo de la humanidad.
El guardián ya se había acostumbrado a todo esto, y sus pasos nunca vacilaron.
La determinación que envuelve sus piernas es como el viento. La determinación que cubre sus brazos es como el fuego.
Aún sigue buscando el milagro capaz de traer la salvación.', 953, 582, 529, 'Cazador del páramo escarlata', '["La Prob. CRIT del portador aumenta en un 16%. Al entrar en combate, si el límite máximo de pts. de habilidad básica de los aliados es 6 o más, el ATQ del portador aumenta en un 40%. Cada vez que el portador lanza su habilidad básica, su ATQ aumenta en un 10%. Este efecto se puede acumular hasta 4 veces.","La Prob. CRIT del portador aumenta en un 20%. Al entrar en combate, si el límite máximo de pts. de habilidad básica de los aliados es 6 o más, el ATQ del portador aumenta en un 50%. Cada vez que el portador lanza su habilidad básica, su ATQ aumenta en un 13%. Este efecto se puede acumular hasta 4 veces.","La Prob. CRIT del portador aumenta en un 24%. Al entrar en combate, si el límite máximo de pts. de habilidad básica de los aliados es 6 o más, el ATQ del portador aumenta en un 60%. Cada vez que el portador lanza su habilidad básica, su ATQ aumenta en un 15%. Este efecto se puede acumular hasta 4 veces.","La Prob. CRIT del portador aumenta en un 28%. Al entrar en combate, si el límite máximo de pts. de habilidad básica de los aliados es 6 o más, el ATQ del portador aumenta en un 70%. Cada vez que el portador lanza su habilidad básica, su ATQ aumenta en un 18%. Este efecto se puede acumular hasta 4 veces.","La Prob. CRIT del portador aumenta en un 32%. Al entrar en combate, si el límite máximo de pts. de habilidad básica de los aliados es 6 o más, el ATQ del portador aumenta en un 80%. Cada vez que el portador lanza su habilidad básica, su ATQ aumenta en un 20%. Este efecto se puede acumular hasta 4 veces."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Núcleo apagado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Perdigón meteórico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110191.png","cantidad":4},{"nombre":"Núcleo apagado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Deceso predestinado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110192.png","cantidad":4},{"nombre":"Núcleo reluciente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Deceso predestinado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110192.png","cantidad":8},{"nombre":"Núcleo reluciente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Disparo antitemporal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110193.png","cantidad":5},{"nombre":"Núcleo serpenteante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Disparo antitemporal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110193.png","cantidad":10},{"nombre":"Núcleo serpenteante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23047', 'honkai-star-rail', 'Por qué canta el océano', 'Why Does the Ocean Sing', '5', 'Nihilidad', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23047.png', 'Las olas se agitan y su rugido resuena en el horizonte.
Los peces nadan en ese mar vacío, la antigua espuma se arremolina, y parece que aún se oye el eco de aquella melodía.
"¡Noble princesa, únete a nuestro festín!".
Para responder a este llamado de las profundidades, ella bailó con la marea oscura hasta quedarse sola en el grandioso escenario.
"Maestra de la espada del océano, ¿por qué guardas silencio, por qué cantas?".
A cada paso sobre la tierra, soportaba el dolor y cantaba en raras ocasiones. Solo su hoja carmesí entonaba el lamento de la vida.
"Dux Gladiorum, ¡ven conmigo a conquistar el mar de estrellas!".
Cuando encontró esa luz ardiente, tomó al fin el arco de su violín, creyendo que ese sería el comienzo de la celebración.
...
"Hysirenia... Hysirenia... Cuando termine tu canción, ¿hacia dónde nadarás?".
Cuando las esperanzas vanas se hacen añicos, ella siempre responde a las preguntas de la gente con una melodía solitaria, y acaba hechizando a todos los que la escuchan.
O quizás... ya sea en el mundo humano o en las profundidades del mar, la única que verdaderamente escucha es la intérprete.', 953, 635, 463, 'Solo', '["El acierto de efecto del portador aumenta en un 40%. Cuando el portador aplica un estado negativo a un enemigo, tiene una probabilidad base del 80% de afectarlo con Hechizo durante 3 turnos. Los efectos del mismo tipo no se pueden acumular. En el estado de Hechizo, el Daño con el tiempo recibido aumenta en un 5.0% por cada estado negativo aplicado por el portador. Este efecto se puede acumular hasta 6 veces. Cuando el objetivo recibe un ataque de un aliado, la VEL del atacante aumenta en un 10.0% durante 3 turnos. Cuando el portador es derrotado, se eliminan todas las acumulaciones de Hechizo.","El acierto de efecto del portador aumenta en un 45%. Cuando el portador aplica un estado negativo a un enemigo, tiene una probabilidad base del 80% de afectarlo con Hechizo durante 3 turnos. Los efectos del mismo tipo no se pueden acumular. En el estado de Hechizo, el Daño con el tiempo recibido aumenta en un 6.3% por cada estado negativo aplicado por el portador. Este efecto se puede acumular hasta 6 veces. Cuando el objetivo recibe un ataque de un aliado, la VEL del atacante aumenta en un 12.5% durante 3 turnos. Cuando el portador es derrotado, se eliminan todas las acumulaciones de Hechizo.","El acierto de efecto del portador aumenta en un 50%. Cuando el portador aplica un estado negativo a un enemigo, tiene una probabilidad base del 80% de afectarlo con Hechizo durante 3 turnos. Los efectos del mismo tipo no se pueden acumular. En el estado de Hechizo, el Daño con el tiempo recibido aumenta en un 7.5% por cada estado negativo aplicado por el portador. Este efecto se puede acumular hasta 6 veces. Cuando el objetivo recibe un ataque de un aliado, la VEL del atacante aumenta en un 15.0% durante 3 turnos. Cuando el portador es derrotado, se eliminan todas las acumulaciones de Hechizo.","El acierto de efecto del portador aumenta en un 55%. Cuando el portador aplica un estado negativo a un enemigo, tiene una probabilidad base del 80% de afectarlo con Hechizo durante 3 turnos. Los efectos del mismo tipo no se pueden acumular. En el estado de Hechizo, el Daño con el tiempo recibido aumenta en un 8.8% por cada estado negativo aplicado por el portador. Este efecto se puede acumular hasta 6 veces. Cuando el objetivo recibe un ataque de un aliado, la VEL del atacante aumenta en un 17.5% durante 3 turnos. Cuando el portador es derrotado, se eliminan todas las acumulaciones de Hechizo.","El acierto de efecto del portador aumenta en un 60%. Cuando el portador aplica un estado negativo a un enemigo, tiene una probabilidad base del 80% de afectarlo con Hechizo durante 3 turnos. Los efectos del mismo tipo no se pueden acumular. En el estado de Hechizo, el Daño con el tiempo recibido aumenta en un 10.0% por cada estado negativo aplicado por el portador. Este efecto se puede acumular hasta 6 veces. Cuando el objetivo recibe un ataque de un aliado, la VEL del atacante aumenta en un 20.0% durante 3 turnos. Cuando el portador es derrotado, se eliminan todas las acumulaciones de Hechizo."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Carne pisoteada del miedo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Espíritu ardiente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110221.png","cantidad":4},{"nombre":"Carne pisoteada del miedo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Esencia de fuego estelar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110222.png","cantidad":4},{"nombre":"Pecho hendido del valor","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Esencia de fuego estelar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110222.png","cantidad":8},{"nombre":"Pecho hendido del valor","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Incinerador divino","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110223.png","cantidad":5},{"nombre":"Torso bautizado de gloria","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Incinerador divino","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110223.png","cantidad":10},{"nombre":"Torso bautizado de gloria","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23048', 'honkai-star-rail', 'Era grabada en sangre dorada', 'Epoch Etched in Golden Blood', '5', 'Armonía', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23048.png', '"Dentro de mil años, ¿cómo recordará la historia a Céridra?".
Eso le preguntaron una vez.
Para algunos, ella era la famosa e impresionante emperatriz.
La tirana fría y cruel, la ambiciosa Portadora de la corona ardiente, la reina que quemó el viejo mundo con sangre y fuego...
Otros argumentaban que solo era un triste peón.
Esa soberana, abandonada por todos, no era más que una prisionera de la ambición, destinada a perderlo todo en aquella partida de ajedrez contra los dioses.
Y otros decían que, en lo más profundo de su corazón, más oscuro que el océano, era simplemente una mortal llamada Céridra.
Alguien que también lloraba por sus camaradas caídos, que dudaba y temía ante el peso de su misión, que se sentía incapaz de avanzar...
"Je, la historia no necesita recordarme".
Se tragó la amargura de su corazón y continuó por el camino buscallamas pavimentado con sacrificios.
"¡Será nuestra ardiente sangre dorada quien la inscriba!".', 953, 635, 463, 'Conquista', '["El ATQ del portador aumenta en un 64%. Tras lanzar la habilidad definitiva para atacar, recupera 1 pt. de habilidad básica. Después de que el portador lance la habilidad básica sobre un personaje aliado, el daño de habilidad básica infligido por el objetivo aumenta en un 54.0% durante 3 turnos.","El ATQ del portador aumenta en un 80%. Tras lanzar la habilidad definitiva para atacar, recupera 1 pt. de habilidad básica. Después de que el portador lance la habilidad básica sobre un personaje aliado, el daño de habilidad básica infligido por el objetivo aumenta en un 67.5% durante 3 turnos.","El ATQ del portador aumenta en un 96%. Tras lanzar la habilidad definitiva para atacar, recupera 1 pt. de habilidad básica. Después de que el portador lance la habilidad básica sobre un personaje aliado, el daño de habilidad básica infligido por el objetivo aumenta en un 81.0% durante 3 turnos.","El ATQ del portador aumenta en un 112%. Tras lanzar la habilidad definitiva para atacar, recupera 1 pt. de habilidad básica. Después de que el portador lance la habilidad básica sobre un personaje aliado, el daño de habilidad básica infligido por el objetivo aumenta en un 94.5% durante 3 turnos.","El ATQ del portador aumenta en un 128%. Tras lanzar la habilidad definitiva para atacar, recupera 1 pt. de habilidad básica. Después de que el portador lance la habilidad básica sobre un personaje aliado, el daño de habilidad básica infligido por el objetivo aumenta en un 108.0% durante 3 turnos."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Augurio etéreo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115011.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Nota del firmamento","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110231.png","cantidad":4},{"nombre":"Augurio etéreo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115011.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Compás celestial","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110232.png","cantidad":4},{"nombre":"Gemido resonante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115012.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Compás celestial","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110232.png","cantidad":8},{"nombre":"Gemido resonante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115012.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Movimiento celestial","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110233.png","cantidad":5},{"nombre":"Lamento eterno","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115013.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Movimiento celestial","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110233.png","cantidad":10},{"nombre":"Lamento eterno","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115013.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23049', 'honkai-star-rail', 'A la estrella de la larga noche', 'To Evernight''s Stars', '5', 'Memoria', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23049.png', 'En los resquicios del tiempo solo resuena el latido de su corazón.
Igual que tantas noches anteriores, observa la escena nocturna mientras descansa en ella.
Atesora los recuerdos que le fueron confiados.
Desde un punto de partida en blanco, la joven pinta con vívidos colores cada lugar donde se ha detenido. El acogedor tren, los compañeros de distintas personalidades, los planetas resplandecientes y hermosos... Es como un sueño hermoso del que no se quiere despertar.
"¡Mi verdadero viaje va a comenzar ahora!".
Oye la declaración de la chica como si la tuviera al lado.
Mira hacia el lejano cielo estrellado, por donde se acerca un rayo de luz.
Es el faro del tren, como si fuera una estrella fugaz.
♭ "Buenas noches, Marzo... El día que despiertes, continúa tu viaje trazando caminos". ♭
Mientras sube la marea de recuerdos, ella guarda su deseo en lo más profundo de su corazón. Esos susurros y esa luz...
Nunca los ha olvidado.', 1164, 529, 463, 'Insomnio', '["Los PV máx. del portador aumentan en un 30%. Cuando el mnemoduende del portador lanza una habilidad, el portador obtiene Escena nocturna. Cuando el portador tiene Escena nocturna, el daño que infligen todos los mnemoduendes aliados ignora el 20% de la DEF de los objetivos y el daño que infligen el portador y su mnemoduende aumenta en un 30%. Cuando el mnemoduende del portador desaparece, el portador recupera 8 pts. de energía. Los efectos del mismo tipo no se pueden acumular.","Los PV máx. del portador aumentan en un 38%. Cuando el mnemoduende del portador lanza una habilidad, el portador obtiene Escena nocturna. Cuando el portador tiene Escena nocturna, el daño que infligen todos los mnemoduendes aliados ignora el 23% de la DEF de los objetivos y el daño que infligen el portador y su mnemoduende aumenta en un 38%. Cuando el mnemoduende del portador desaparece, el portador recupera 10 pts. de energía. Los efectos del mismo tipo no se pueden acumular.","Los PV máx. del portador aumentan en un 45%. Cuando el mnemoduende del portador lanza una habilidad, el portador obtiene Escena nocturna. Cuando el portador tiene Escena nocturna, el daño que infligen todos los mnemoduendes aliados ignora el 25% de la DEF de los objetivos y el daño que infligen el portador y su mnemoduende aumenta en un 45%. Cuando el mnemoduende del portador desaparece, el portador recupera 12 pts. de energía. Los efectos del mismo tipo no se pueden acumular.","Los PV máx. del portador aumentan en un 53%. Cuando el mnemoduende del portador lanza una habilidad, el portador obtiene Escena nocturna. Cuando el portador tiene Escena nocturna, el daño que infligen todos los mnemoduendes aliados ignora el 28% de la DEF de los objetivos y el daño que infligen el portador y su mnemoduende aumenta en un 53%. Cuando el mnemoduende del portador desaparece, el portador recupera 14 pts. de energía. Los efectos del mismo tipo no se pueden acumular.","Los PV máx. del portador aumentan en un 60%. Cuando el mnemoduende del portador lanza una habilidad, el portador obtiene Escena nocturna. Cuando el portador tiene Escena nocturna, el daño que infligen todos los mnemoduendes aliados ignora el 30% de la DEF de los objetivos y el daño que infligen el portador y su mnemoduende aumenta en un 60%. Cuando el mnemoduende del portador desaparece, el portador recupera 16 pts. de energía. Los efectos del mismo tipo no se pueden acumular."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Augurio etéreo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115011.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Semilla de la reflexión","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110251.png","cantidad":4},{"nombre":"Augurio etéreo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115011.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Brote de manas","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110252.png","cantidad":4},{"nombre":"Gemido resonante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115012.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Brote de manas","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110252.png","cantidad":8},{"nombre":"Gemido resonante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115012.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Alayawah","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110253.png","cantidad":5},{"nombre":"Lamento eterno","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115013.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Alayawah","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110253.png","cantidad":10},{"nombre":"Lamento eterno","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115013.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23050', 'honkai-star-rail', 'No olvides su fuego', 'Never Forget Her Flame', '5', 'Nihilidad', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23050.png', '"Ven, acércate a mí...".
Un recuerdo muy vívido encendido por las llamas envuelve su cuerpo y su alma.
¿Es verdad que el pasado ya descansa en su tumba?
"Shhh, no llores, no te resistas".
Se graba a sí misma en los corazones ajenos, y las miradas extrañas se vuelven familiares.
"¿Ahora lo recuerdas?".
Las ascuas de los viejos recuerdos se dispersan y su rostro desprende una embriagadora fragancia floral.
"Yo soy tus recuerdos".', 1164, 529, 463, 'Inmolación', '["El efecto de Ruptura del portador aumenta en un 60%. Al entrar en combate, el Daño de Ruptura del portador y del compañero de equipo que inició el combate aumenta en un 32%. Si el combate no lo inició un compañero de equipo, el efecto se aplica al portador y al compañero de equipo con el mayor efecto de Ruptura. Los efectos del mismo tipo no se pueden acumular. Cuando el portador implanta una Debilidad a un enemigo, recupera 1 pt. de habilidad básica. Este efecto solo se puede activar una vez y el contador de activaciones se reinicia al lanzar la habilidad definitiva.","El efecto de Ruptura del portador aumenta en un 75%. Al entrar en combate, el Daño de Ruptura del portador y del compañero de equipo que inició el combate aumenta en un 42%. Si el combate no lo inició un compañero de equipo, el efecto se aplica al portador y al compañero de equipo con el mayor efecto de Ruptura. Los efectos del mismo tipo no se pueden acumular. Cuando el portador implanta una Debilidad a un enemigo, recupera 1 pt. de habilidad básica. Este efecto solo se puede activar una vez y el contador de activaciones se reinicia al lanzar la habilidad definitiva.","El efecto de Ruptura del portador aumenta en un 90%. Al entrar en combate, el Daño de Ruptura del portador y del compañero de equipo que inició el combate aumenta en un 52%. Si el combate no lo inició un compañero de equipo, el efecto se aplica al portador y al compañero de equipo con el mayor efecto de Ruptura. Los efectos del mismo tipo no se pueden acumular. Cuando el portador implanta una Debilidad a un enemigo, recupera 1 pt. de habilidad básica. Este efecto solo se puede activar una vez y el contador de activaciones se reinicia al lanzar la habilidad definitiva.","El efecto de Ruptura del portador aumenta en un 105%. Al entrar en combate, el Daño de Ruptura del portador y del compañero de equipo que inició el combate aumenta en un 62%. Si el combate no lo inició un compañero de equipo, el efecto se aplica al portador y al compañero de equipo con el mayor efecto de Ruptura. Los efectos del mismo tipo no se pueden acumular. Cuando el portador implanta una Debilidad a un enemigo, recupera 1 pt. de habilidad básica. Este efecto solo se puede activar una vez y el contador de activaciones se reinicia al lanzar la habilidad definitiva.","El efecto de Ruptura del portador aumenta en un 120%. Al entrar en combate, el Daño de Ruptura del portador y del compañero de equipo que inició el combate aumenta en un 72%. Si el combate no lo inició un compañero de equipo, el efecto se aplica al portador y al compañero de equipo con el mayor efecto de Ruptura. Los efectos del mismo tipo no se pueden acumular. Cuando el portador implanta una Debilidad a un enemigo, recupera 1 pt. de habilidad básica. Este efecto solo se puede activar una vez y el contador de activaciones se reinicia al lanzar la habilidad definitiva."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Jirones de pensamientos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114011.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Espíritu ardiente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110221.png","cantidad":4},{"nombre":"Jirones de pensamientos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114011.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Esencia de fuego estelar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110222.png","cantidad":4},{"nombre":"Fragmento de impresiones","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114012.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Esencia de fuego estelar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110222.png","cantidad":8},{"nombre":"Fragmento de impresiones","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114012.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Incinerador divino","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110223.png","cantidad":5},{"nombre":"Fragmento de deseos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114013.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Incinerador divino","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110223.png","cantidad":10},{"nombre":"Fragmento de deseos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114013.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23051', 'honkai-star-rail', 'A través de montañas y ríos', 'Though Worlds Apart', '5', 'Conservación', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23051.png', 'En las tierras inmemoriales sin fronteras, un joven camina solo en su búsqueda.
Parece haber regresado a aquellos días de vagabundeo, atravesando las olas, soportando las inclemencias del tiempo, luchando contra bestias gigantes y batallando contra las mareas furiosas.
Pero en ese momento de respiro, no está solo.
A través de montañas y ríos, aún puede ver la luz que brilla adelante...
Es la luz de la esperanza de todos los seres vivos.
La tierra destrozada ya no puede ser portadora de nueva vida y se reúnen alrededor de él, buscando consuelo y refugio.
Esas son las palabras que sus compañeros dejaron en su corazón, como un trayecto interminable que los mantiene firmemente unidos.
El pasado que lo perturbaba voló con el viento, pero el camino que ha recorrido terminará convirtiéndose en la fuerza para su metamorfosis.
"Protegeré la senda trazacaminos".
El joven salta hacia delante agarrando su lanza y avanza hacia la luz.
"¡Y defenderé toda esperanza que esté a punto de desvanecerse!".', 1058, 582, 463, 'Nuevas escamas', '["El ATQ del portador aumenta en un 64%. Cuando el portador lanza la habilidad definitiva, regenera los PV de todos los aliados por un valor equivalente al 10% del ATQ del portador, regenera al personaje con menos PV una cantidad adicional de PV equivalente al 10% del ATQ del portador, y otorga Baluarte a todos los aliados durante 3 turnos. El daño que infligen los objetivos con Baluarte aumenta en un 24% y, si tienen alguna invocación, aumenta en un 12% adicional.","El ATQ del portador aumenta en un 80%. Cuando el portador lanza la habilidad definitiva, regenera los PV de todos los aliados por un valor equivalente al 13% del ATQ del portador, regenera al personaje con menos PV una cantidad adicional de PV equivalente al 13% del ATQ del portador, y otorga Baluarte a todos los aliados durante 3 turnos. El daño que infligen los objetivos con Baluarte aumenta en un 30% y, si tienen alguna invocación, aumenta en un 15% adicional.","El ATQ del portador aumenta en un 96%. Cuando el portador lanza la habilidad definitiva, regenera los PV de todos los aliados por un valor equivalente al 15% del ATQ del portador, regenera al personaje con menos PV una cantidad adicional de PV equivalente al 15% del ATQ del portador, y otorga Baluarte a todos los aliados durante 3 turnos. El daño que infligen los objetivos con Baluarte aumenta en un 36% y, si tienen alguna invocación, aumenta en un 18% adicional.","El ATQ del portador aumenta en un 112%. Cuando el portador lanza la habilidad definitiva, regenera los PV de todos los aliados por un valor equivalente al 18% del ATQ del portador, regenera al personaje con menos PV una cantidad adicional de PV equivalente al 18% del ATQ del portador, y otorga Baluarte a todos los aliados durante 3 turnos. El daño que infligen los objetivos con Baluarte aumenta en un 42% y, si tienen alguna invocación, aumenta en un 21% adicional.","El ATQ del portador aumenta en un 128%. Cuando el portador lanza la habilidad definitiva, regenera los PV de todos los aliados por un valor equivalente al 20% del ATQ del portador, regenera al personaje con menos PV una cantidad adicional de PV equivalente al 20% del ATQ del portador, y otorga Baluarte a todos los aliados durante 3 turnos. El daño que infligen los objetivos con Baluarte aumenta en un 48% y, si tienen alguna invocación, aumenta en un 24% adicional."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Carne pisoteada del miedo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Polvo estelar disperso","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110211.png","cantidad":4},{"nombre":"Carne pisoteada del miedo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Meteoritos de cristal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110212.png","cantidad":4},{"nombre":"Pecho hendido del valor","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Meteoritos de cristal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110212.png","cantidad":8},{"nombre":"Pecho hendido del valor","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Ámbar divino","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110213.png","cantidad":5},{"nombre":"Torso bautizado de gloria","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Ámbar divino","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110213.png","cantidad":10},{"nombre":"Torso bautizado de gloria","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23052', 'honkai-star-rail', 'Amor eterno como este momento', 'This Love, Forever', '5', 'Memoria', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23052.png', 'El cielo azul refleja un mañana brillante.
Un paso, dos pasos... El camino de la joven ha sido muy largo, pero afortunadamente aquellas historias tan preciadas no han sido olvidadas por el ciclo del tiempo.
Hoy, la epopeya que han escrito entre todos se ha terminado y ha dado la bienvenida a su final.
Las estrellas, las flores, los pájaros y un hermoso mundo nuevo.
El velo, la corona de flores, el vestido largo y las bendiciones que trae el viento.
La búsqueda de treinta millones de vidas se ha transformado en un instante de felicidad suficiente para superar las palabras de la eternidad.
"Ji, ji, es una promesa...".
La joven mira hacia atrás y sonríe dulcemente.
♪ "Una persona permanece en el pasado y la otra camina hacia el futuro... pero nuestros corazones nunca se separarán". ♪
Se pone de puntillas y camina hacia el ayer...
Y los recuerdos, convertidos en ondas del pasado, fluyen hacia el mañana.', 1270, 476, 463, 'Promesa', '["La VEL del portador aumenta en un 18%. Cuando el mnemoduende del portador lanza la habilidad de mnemoduende sobre un aliado, obtiene Espacio en blanco, que aumenta el daño que reciben todos los enemigos en un 10%. Cuando el mnemoduende del portador lanza la habilidad de mnemoduende sobre enemigos, obtiene Verso, que aumenta el Daño CRIT de todos los aliados en un 16%. Si el mnemoduende del portador tiene simultáneamente Espacio en blanco y Verso, los efectos de ambos aumentan en un 60%.","La VEL del portador aumenta en un 21%. Cuando el mnemoduende del portador lanza la habilidad de mnemoduende sobre un aliado, obtiene Espacio en blanco, que aumenta el daño que reciben todos los enemigos en un 12%. Cuando el mnemoduende del portador lanza la habilidad de mnemoduende sobre enemigos, obtiene Verso, que aumenta el Daño CRIT de todos los aliados en un 19%. Si el mnemoduende del portador tiene simultáneamente Espacio en blanco y Verso, los efectos de ambos aumentan en un 65%.","La VEL del portador aumenta en un 24%. Cuando el mnemoduende del portador lanza la habilidad de mnemoduende sobre un aliado, obtiene Espacio en blanco, que aumenta el daño que reciben todos los enemigos en un 14%. Cuando el mnemoduende del portador lanza la habilidad de mnemoduende sobre enemigos, obtiene Verso, que aumenta el Daño CRIT de todos los aliados en un 22%. Si el mnemoduende del portador tiene simultáneamente Espacio en blanco y Verso, los efectos de ambos aumentan en un 70%.","La VEL del portador aumenta en un 27%. Cuando el mnemoduende del portador lanza la habilidad de mnemoduende sobre un aliado, obtiene Espacio en blanco, que aumenta el daño que reciben todos los enemigos en un 16%. Cuando el mnemoduende del portador lanza la habilidad de mnemoduende sobre enemigos, obtiene Verso, que aumenta el Daño CRIT de todos los aliados en un 25%. Si el mnemoduende del portador tiene simultáneamente Espacio en blanco y Verso, los efectos de ambos aumentan en un 75%.","La VEL del portador aumenta en un 30%. Cuando el mnemoduende del portador lanza la habilidad de mnemoduende sobre un aliado, obtiene Espacio en blanco, que aumenta el daño que reciben todos los enemigos en un 18%. Cuando el mnemoduende del portador lanza la habilidad de mnemoduende sobre enemigos, obtiene Verso, que aumenta el Daño CRIT de todos los aliados en un 28%. Si el mnemoduende del portador tiene simultáneamente Espacio en blanco y Verso, los efectos de ambos aumentan en un 80%."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Carne pisoteada del miedo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Semilla de la reflexión","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110251.png","cantidad":4},{"nombre":"Carne pisoteada del miedo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Brote de manas","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110252.png","cantidad":4},{"nombre":"Pecho hendido del valor","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Brote de manas","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110252.png","cantidad":8},{"nombre":"Pecho hendido del valor","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Alayawah","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110253.png","cantidad":5},{"nombre":"Torso bautizado de gloria","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Alayawah","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110253.png","cantidad":10},{"nombre":"Torso bautizado de gloria","icono":"https://sr.yatta.moe/hsr/assets/UI/item/115003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23053', 'honkai-star-rail', 'El cautivador mundochispa', 'Dazzled by a Flowery World', '5', 'Exultación', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23053.png', 'Cuando ella ríe, sus seguidores ríen.
Cuando llora, sus seguidores lloran.
Cuando está enojada, sus seguidores se enojan.
"Adorable, traviesa, popular. Chispa es todo lo que quiero ser".
"No te dejes engañar. Chispa es un veneno, una mentira...".
"Seguiré a Chispita para siempre. Ella me dio el valor de renacer...".
"¡Chispa debería desaparecer de este mundo!".
...
Clics, mensajes, comentarios... Chispa brilla cada vez más en los ojos de todos.
"¡He recibido todo su cariño! ♥ Se lo devolveré de la forma más animada posible ♥. Así...".
A medida que el directo llega a su fin, la joven guiña el ojo, como si pudiera ver los corazones de todos los que están detrás de sus pantallas...
"¡Les doy una oportunidad! ¿Les gustaría convertirse en Chispa?".', 1058, 582, 463, 'Foco de atención', '["El Daño CRIT del portador aumenta en un 48%. Cuando el portador está en el campo de batalla, el límite máximo de pts. de habilidad básica aumenta en 1 pt. por cada personaje de la Vía de Exultación que haya en el equipo, hasta un máximo de 3 pts. Cada vez que el portador consume 1 pt. de habilidad básica, el Daño de Exultación que inflige ignora un 5.0% de la DEF del enemigo. Este efecto se puede acumular hasta 4 veces. Si en un mismo turno consume 4 o más pts. de habilidad básica, el portador obtiene Directo promocional. Cuando el portador tiene Directo promocional, la Exultación de todos los aliados aumenta en un 20%. Los efectos de conos de luz del mismo tipo no se pueden acumular.","El Daño CRIT del portador aumenta en un 56%. Cuando el portador está en el campo de batalla, el límite máximo de pts. de habilidad básica aumenta en 1 pt. por cada personaje de la Vía de Exultación que haya en el equipo, hasta un máximo de 3 pts. Cada vez que el portador consume 1 pt. de habilidad básica, el Daño de Exultación que inflige ignora un 6.0% de la DEF del enemigo. Este efecto se puede acumular hasta 4 veces. Si en un mismo turno consume 4 o más pts. de habilidad básica, el portador obtiene Directo promocional. Cuando el portador tiene Directo promocional, la Exultación de todos los aliados aumenta en un 24%. Los efectos de conos de luz del mismo tipo no se pueden acumular.","El Daño CRIT del portador aumenta en un 64%. Cuando el portador está en el campo de batalla, el límite máximo de pts. de habilidad básica aumenta en 1 pt. por cada personaje de la Vía de Exultación que haya en el equipo, hasta un máximo de 3 pts. Cada vez que el portador consume 1 pt. de habilidad básica, el Daño de Exultación que inflige ignora un 7.0% de la DEF del enemigo. Este efecto se puede acumular hasta 4 veces. Si en un mismo turno consume 4 o más pts. de habilidad básica, el portador obtiene Directo promocional. Cuando el portador tiene Directo promocional, la Exultación de todos los aliados aumenta en un 28%. Los efectos de conos de luz del mismo tipo no se pueden acumular.","El Daño CRIT del portador aumenta en un 72%. Cuando el portador está en el campo de batalla, el límite máximo de pts. de habilidad básica aumenta en 1 pt. por cada personaje de la Vía de Exultación que haya en el equipo, hasta un máximo de 3 pts. Cada vez que el portador consume 1 pt. de habilidad básica, el Daño de Exultación que inflige ignora un 8.0% de la DEF del enemigo. Este efecto se puede acumular hasta 4 veces. Si en un mismo turno consume 4 o más pts. de habilidad básica, el portador obtiene Directo promocional. Cuando el portador tiene Directo promocional, la Exultación de todos los aliados aumenta en un 32%. Los efectos de conos de luz del mismo tipo no se pueden acumular.","El Daño CRIT del portador aumenta en un 80%. Cuando el portador está en el campo de batalla, el límite máximo de pts. de habilidad básica aumenta en 1 pt. por cada personaje de la Vía de Exultación que haya en el equipo, hasta un máximo de 3 pts. Cada vez que el portador consume 1 pt. de habilidad básica, el Daño de Exultación que inflige ignora un 9.0% de la DEF del enemigo. Este efecto se puede acumular hasta 4 veces. Si en un mismo turno consume 4 o más pts. de habilidad básica, el portador obtiene Directo promocional. Cuando el portador tiene Directo promocional, la Exultación de todos los aliados aumenta en un 36%. Los efectos de conos de luz del mismo tipo no se pueden acumular."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Crayón de la inocencia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Guion gráfico hecho a mano de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110261.png","cantidad":4},{"nombre":"Crayón de la inocencia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Edición conmemorativa de la serialización de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110262.png","cantidad":4},{"nombre":"Pluma creasueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Edición conmemorativa de la serialización de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110262.png","cantidad":8},{"nombre":"Pluma creasueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Edición de coleccionista de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110263.png","cantidad":5},{"nombre":"Pincel de los sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Edición de coleccionista de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110263.png","cantidad":10},{"nombre":"Pincel de los sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23054', 'honkai-star-rail', 'Cuando se decidió a ver', 'When She Decided to See', '5', 'Exultación', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23054.png', 'En la Barrera Decarreflectora, observa una vez más cómo el destino brilla como una red de perlas, superponiéndose y reflejándose entre sí en una cadena interminable de causa y efecto.
"¿Qué ves?", le preguntó una vez su maestro.
Algunos adivinos, al ver su propia insignificancia, dejaron de creer que el poder humano podía cambiar el destino.
Otros vieron las grandes tendencias del futuro y siguieron la corriente para encontrar las mejores soluciones.
En ese momento, la joven contempló fijamente la barrera y vio una oscuridad infinita: el futuro que ya estaba predestinado.
También vio la luz estelar, esas pequeñas posibilidades que aún no habían sido engullidas por la mirada de los dioses.
Aquella luz estelar en una ocasión se escapó de sus manos, condenando al Fanghu a una noche eterna.
Pero también logró atrapar las efímeras variables del destino, alterando la fortuna y la desgracia del Yuque.
"Un callejón sin salida se llama así porque nadie está dispuesto a desafiar al destino".
Ella quería encontrar su propia respuesta, aunque eso significara adentrarse en territorio maldito.
"Lo que vea no importa, lo que importa es lo que puedo hacer".', 1058, 529, 529, 'Punto de inflexión', '["La VEL del portador aumenta en un 18%. Cuando el portador entra en combate o lanza la habilidad definitiva a un aliado, el portador obtiene Gran suerte durante 3 turnos. Cuando el portador tiene Gran suerte, la Prob. CRIT y el Daño CRIT de todos los aliados aumentan en un 10% y un 30% respectivamente, y la recuperación de energía del portador aumenta en un 12%.\nAl comenzar cada oleada, el portador recupera 15 pts. de energía.","La VEL del portador aumenta en un 21%. Cuando el portador entra en combate o lanza la habilidad definitiva a un aliado, el portador obtiene Gran suerte durante 3 turnos. Cuando el portador tiene Gran suerte, la Prob. CRIT y el Daño CRIT de todos los aliados aumentan en un 11% y un 38% respectivamente, y la recuperación de energía del portador aumenta en un 14%.\nAl comenzar cada oleada, el portador recupera 15 pts. de energía.","La VEL del portador aumenta en un 24%. Cuando el portador entra en combate o lanza la habilidad definitiva a un aliado, el portador obtiene Gran suerte durante 3 turnos. Cuando el portador tiene Gran suerte, la Prob. CRIT y el Daño CRIT de todos los aliados aumentan en un 12% y un 45% respectivamente, y la recuperación de energía del portador aumenta en un 16%.\nAl comenzar cada oleada, el portador recupera 15 pts. de energía.","La VEL del portador aumenta en un 27%. Cuando el portador entra en combate o lanza la habilidad definitiva a un aliado, el portador obtiene Gran suerte durante 3 turnos. Cuando el portador tiene Gran suerte, la Prob. CRIT y el Daño CRIT de todos los aliados aumentan en un 13% y un 53% respectivamente, y la recuperación de energía del portador aumenta en un 18%.\nAl comenzar cada oleada, el portador recupera 15 pts. de energía.","La VEL del portador aumenta en un 30%. Cuando el portador entra en combate o lanza la habilidad definitiva a un aliado, el portador obtiene Gran suerte durante 3 turnos. Cuando el portador tiene Gran suerte, la Prob. CRIT y el Daño CRIT de todos los aliados aumentan en un 14% y un 60% respectivamente, y la recuperación de energía del portador aumenta en un 20%.\nAl comenzar cada oleada, el portador recupera 15 pts. de energía."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Crayón de la inocencia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Guion gráfico hecho a mano de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110261.png","cantidad":4},{"nombre":"Crayón de la inocencia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Edición conmemorativa de la serialización de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110262.png","cantidad":4},{"nombre":"Pluma creasueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Edición conmemorativa de la serialización de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110262.png","cantidad":8},{"nombre":"Pluma creasueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Edición de coleccionista de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110263.png","cantidad":5},{"nombre":"Pincel de los sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Edición de coleccionista de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110263.png","cantidad":10},{"nombre":"Pincel de los sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23056', 'honkai-star-rail', 'El final de una mentira', 'The Finale of a Lie', '5', 'Cacería', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23056.png', '¿Qué decía la «Introducción al razonamiento detectivesco»? A menos que sea absolutamente necesario...
Unos colmillos tejidos en rojo y negro trepan poco a poco por su hombro.
En lo más hondo de la noche se alza una niebla de sospecha. En el bosque tenebroso se esconden viles bestias.
"Este juego del gato y el ratón debe terminar".
El color sangre se desvanece, la luna sigue brillando en el cielo y las estrellas duermen plácidamente.
Otra vez intentaba buscar la verdad, pero las sombras del pasado le dan una palmada en el hombro y se dispersan.
Los giros y vueltas de este momento continuarán hasta...
"Hasta el día en que los pecadores sean castigados".', 847, 635, 529, 'Engullimiento', '["La Prob. CRIT del portador aumenta en un 18%. Al entrar en combate o cada vez que el portador lanza 4 ataques adicionales, el portador obtiene Sombra voraz durante 3 turnos. Cuando el portador tiene Sombra voraz, su ATQ aumenta en un 40% y el daño que reciben todos los enemigos aumenta en un 20%. Los efectos del mismo tipo no se pueden acumular.","La Prob. CRIT del portador aumenta en un 21%. Al entrar en combate o cada vez que el portador lanza 4 ataques adicionales, el portador obtiene Sombra voraz durante 3 turnos. Cuando el portador tiene Sombra voraz, su ATQ aumenta en un 50% y el daño que reciben todos los enemigos aumenta en un 23%. Los efectos del mismo tipo no se pueden acumular.","La Prob. CRIT del portador aumenta en un 24%. Al entrar en combate o cada vez que el portador lanza 4 ataques adicionales, el portador obtiene Sombra voraz durante 3 turnos. Cuando el portador tiene Sombra voraz, su ATQ aumenta en un 60% y el daño que reciben todos los enemigos aumenta en un 25%. Los efectos del mismo tipo no se pueden acumular.","La Prob. CRIT del portador aumenta en un 27%. Al entrar en combate o cada vez que el portador lanza 4 ataques adicionales, el portador obtiene Sombra voraz durante 3 turnos. Cuando el portador tiene Sombra voraz, su ATQ aumenta en un 70% y el daño que reciben todos los enemigos aumenta en un 28%. Los efectos del mismo tipo no se pueden acumular.","La Prob. CRIT del portador aumenta en un 30%. Al entrar en combate o cada vez que el portador lanza 4 ataques adicionales, el portador obtiene Sombra voraz durante 3 turnos. Cuando el portador tiene Sombra voraz, su ATQ aumenta en un 80% y el daño que reciben todos los enemigos aumenta en un 30%. Los efectos del mismo tipo no se pueden acumular."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Crayón de la inocencia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Polvo del Conflicto","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110271.png","cantidad":4},{"nombre":"Crayón de la inocencia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Sangre de batalla","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110272.png","cantidad":4},{"nombre":"Pluma creasueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Sangre de batalla","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110272.png","cantidad":8},{"nombre":"Pluma creasueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Lanza sangrienta de la furia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110273.png","cantidad":5},{"nombre":"Pincel de los sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Lanza sangrienta de la furia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110273.png","cantidad":10},{"nombre":"Pincel de los sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23057', 'honkai-star-rail', 'Bienvenidos a la ciudad cósmica', 'Welcome to the Cosmic City', '5', 'Exultación', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23057.png', 'En el cielo de la ciudad, la llamativa silueta de una joven emerge de un portal de teletransportación.
Entre un torrente de vehículos y siluetas humanas, sigue habiendo el mismo bullicio de siempre.
"Se ve muy animado, pero...".
La pantalla frente a ella se enciende y las emociones de las personas se transforman en pequeños puntos de luz que fluyen hacia su interior.
"Incluso las barras de agotamiento de los PNJ están a punto de llegar al máximo...".
"Paso de jugar una mazmorra tan aburrida".
Con un movimiento de sus dedos, las luces de la ciudad parpadean.
Un grito de sorpresa surge de un rincón oculto y, acto seguido, un clamor retumba hasta resonar en el cielo.
"Suerte doble para todos los jugadores, talentos especiales aleatorios y recompensas al máximo...".
"¡Juego cargado! Y ahora, ¡a jugar se ha dicho!".
La joven salta al vacío mientras un familiar sonido de notificación resuena en sus oídos.
El momento de su partida ya ha comenzado.', 1164, 476, 529, 'Victoria segura', '["La VEL del portador aumenta en un 18%. El Daño de Exultación infligido ignora un 20% de la DEF del objetivo. Cuando el portador lanza su habilidad definitiva sobre sí mismo, obtiene 20 pts. de Chiste. Este efecto puede activarse 1 vez como máximo y el contador de activaciones se restablece tras lanzar 3 ATQ básicos.","La VEL del portador aumenta en un 21%. El Daño de Exultación infligido ignora un 24% de la DEF del objetivo. Cuando el portador lanza su habilidad definitiva sobre sí mismo, obtiene 25 pts. de Chiste. Este efecto puede activarse 1 vez como máximo y el contador de activaciones se restablece tras lanzar 3 ATQ básicos.","La VEL del portador aumenta en un 24%. El Daño de Exultación infligido ignora un 28% de la DEF del objetivo. Cuando el portador lanza su habilidad definitiva sobre sí mismo, obtiene 30 pts. de Chiste. Este efecto puede activarse 1 vez como máximo y el contador de activaciones se restablece tras lanzar 3 ATQ básicos.","La VEL del portador aumenta en un 27%. El Daño de Exultación infligido ignora un 32% de la DEF del objetivo. Cuando el portador lanza su habilidad definitiva sobre sí mismo, obtiene 35 pts. de Chiste. Este efecto puede activarse 1 vez como máximo y el contador de activaciones se restablece tras lanzar 3 ATQ básicos.","La VEL del portador aumenta en un 30%. El Daño de Exultación infligido ignora un 36% de la DEF del objetivo. Cuando el portador lanza su habilidad definitiva sobre sí mismo, obtiene 40 pts. de Chiste. Este efecto puede activarse 1 vez como máximo y el contador de activaciones se restablece tras lanzar 3 ATQ básicos."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Crayón de la inocencia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Guion gráfico hecho a mano de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110261.png","cantidad":4},{"nombre":"Crayón de la inocencia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Edición conmemorativa de la serialización de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110262.png","cantidad":4},{"nombre":"Pluma creasueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Edición conmemorativa de la serialización de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110262.png","cantidad":8},{"nombre":"Pluma creasueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Edición de coleccionista de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110263.png","cantidad":5},{"nombre":"Pincel de los sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Edición de coleccionista de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110263.png","cantidad":10},{"nombre":"Pincel de los sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23058', 'honkai-star-rail', 'Encuentro en la próxima primavera', 'Until the Flowers Bloom Again', '5', 'Exultación', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23058.png', 'La brisa sopla a través de las cortinas blancas, agitando los pensamientos de la joven.
Mira hacia la alegre multitud fuera de la ventana, y su lápiz se detiene inconscientemente.
"¿Cuántas veces me he sentado aquí?".
En un instante, un pétalo que cae roza la punta de su nariz, como una respuesta, un recordatorio.
Un gran juego, un encuentro único, los días y las noches de flores que florecen y se marchitan...
Recuerda su historia con esta tierra, desde una página en blanco hasta un mundo lleno de color. Con cada sueño, anhela la llegada del mañana.
"¡Oh, un nuevo capítulo del cómic! Le echaré un vistazo cuando termine de dibujar a estas bellezas...".
La joven recibe una notificación, sacude sus orejas y la punta de su lápiz vuelve a moverse.
"¡Ojalá para la próxima primavera me haya puesto al día con las novedades más populares!".', 953, 635, 463, 'Ensoñación', '["Aumenta el Daño CRIT del portador en un 60% y la recuperación de energía en un 10.0%. Cuando la energía máxima del portador es superior a 120, la recuperación de energía aumenta en un 0.3% adicional por cada 10 pts. de energía máxima de exceso. Se cuentan hasta 360 pts. de energía máxima excedentes. Cuando el portador lanza la habilidad de Exultación, el daño que reciben todos los enemigos aumenta en un 15.0% durante 2 turnos. Los efectos del mismo tipo no se pueden acumular.","Aumenta el Daño CRIT del portador en un 75% y la recuperación de energía en un 11.5%. Cuando la energía máxima del portador es superior a 120, la recuperación de energía aumenta en un 0.3% adicional por cada 10 pts. de energía máxima de exceso. Se cuentan hasta 360 pts. de energía máxima excedentes. Cuando el portador lanza la habilidad de Exultación, el daño que reciben todos los enemigos aumenta en un 18.8% durante 2 turnos. Los efectos del mismo tipo no se pueden acumular.","Aumenta el Daño CRIT del portador en un 90% y la recuperación de energía en un 13.0%. Cuando la energía máxima del portador es superior a 120, la recuperación de energía aumenta en un 0.3% adicional por cada 10 pts. de energía máxima de exceso. Se cuentan hasta 360 pts. de energía máxima excedentes. Cuando el portador lanza la habilidad de Exultación, el daño que reciben todos los enemigos aumenta en un 22.5% durante 2 turnos. Los efectos del mismo tipo no se pueden acumular.","Aumenta el Daño CRIT del portador en un 105% y la recuperación de energía en un 14.5%. Cuando la energía máxima del portador es superior a 120, la recuperación de energía aumenta en un 0.3% adicional por cada 10 pts. de energía máxima de exceso. Se cuentan hasta 360 pts. de energía máxima excedentes. Cuando el portador lanza la habilidad de Exultación, el daño que reciben todos los enemigos aumenta en un 26.3% durante 2 turnos. Los efectos del mismo tipo no se pueden acumular.","Aumenta el Daño CRIT del portador en un 120% y la recuperación de energía en un 16.0%. Cuando la energía máxima del portador es superior a 120, la recuperación de energía aumenta en un 0.3% adicional por cada 10 pts. de energía máxima de exceso. Se cuentan hasta 360 pts. de energía máxima excedentes. Cuando el portador lanza la habilidad de Exultación, el daño que reciben todos los enemigos aumenta en un 30.0% durante 2 turnos. Los efectos del mismo tipo no se pueden acumular."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Crayón de la inocencia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Guion gráfico hecho a mano de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110261.png","cantidad":4},{"nombre":"Crayón de la inocencia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Edición conmemorativa de la serialización de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110262.png","cantidad":4},{"nombre":"Pluma creasueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Edición conmemorativa de la serialización de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110262.png","cantidad":8},{"nombre":"Pluma creasueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Edición de coleccionista de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110263.png","cantidad":5},{"nombre":"Pincel de los sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Edición de coleccionista de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110263.png","cantidad":10},{"nombre":"Pincel de los sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23059', 'honkai-star-rail', 'Nuevo cuerpo del averno ardiente', 'Reforged in Hellfire', '5', 'Nihilidad', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23059.png', 'Un instante: el agua fluye. El cuerpo se hunde lentamente, cayendo hacia lo más profundo del abismo azul.
Un instante: una isla desolada y solitaria, las voces del pasado resuenan entre las nubes y la niebla, alejándose cada vez más.
Un instante: una pradera de flores rojas en la otra orilla, espadas rotas arden entre las llamas, se forjan de nuevo y finalmente se funden en una sola.
"Si el momento no ha llegado aún, forjaré uno nuevo".
La desesperación es la fragua, este cuerpo es la chispa. Ya no recuerda cuántas veces ha sentido este dolor.
"Usaré la muerte como martillo y... ¡cortaré las cadenas del destino!".
En el instante en que renace de las llamas, el fuego se dispersa en todas direcciones, su resplandor se eleva hacia el cielo y arde hasta el límite de la otra orilla.
En ese momento, todas las deudas kármicas quedan saldadas. El nuevo cuerpo, templado tras miles de golpes, finalmente se ha forjado.', 1376, 423, 463, 'Templado', '["Los PV máx. del portador aumentan en un 30%. Cuando el portador comienza su turno, recupera 20 pts. de energía fijos. Este efecto se puede activar 1 vez por oleada. Después de que el portador lance su habilidad básica para atacar, afecta a los objetivos con Purgatorio durante 2 turnos. En el estado de Purgatorio, el Daño CRIT que un objetivo recibe aumenta en un 30%, y el que recibe del portador aumenta en un 30% adicional.","Los PV máx. del portador aumentan en un 38%. Cuando el portador comienza su turno, recupera 20 pts. de energía fijos. Este efecto se puede activar 1 vez por oleada. Después de que el portador lance su habilidad básica para atacar, afecta a los objetivos con Purgatorio durante 2 turnos. En el estado de Purgatorio, el Daño CRIT que un objetivo recibe aumenta en un 38%, y el que recibe del portador aumenta en un 38% adicional.","Los PV máx. del portador aumentan en un 45%. Cuando el portador comienza su turno, recupera 20 pts. de energía fijos. Este efecto se puede activar 1 vez por oleada. Después de que el portador lance su habilidad básica para atacar, afecta a los objetivos con Purgatorio durante 2 turnos. En el estado de Purgatorio, el Daño CRIT que un objetivo recibe aumenta en un 45%, y el que recibe del portador aumenta en un 45% adicional.","Los PV máx. del portador aumentan en un 53%. Cuando el portador comienza su turno, recupera 20 pts. de energía fijos. Este efecto se puede activar 1 vez por oleada. Después de que el portador lance su habilidad básica para atacar, afecta a los objetivos con Purgatorio durante 2 turnos. En el estado de Purgatorio, el Daño CRIT que un objetivo recibe aumenta en un 53%, y el que recibe del portador aumenta en un 53% adicional.","Los PV máx. del portador aumentan en un 60%. Cuando el portador comienza su turno, recupera 20 pts. de energía fijos. Este efecto se puede activar 1 vez por oleada. Después de que el portador lance su habilidad básica para atacar, afecta a los objetivos con Purgatorio durante 2 turnos. En el estado de Purgatorio, el Daño CRIT que un objetivo recibe aumenta en un 60%, y el que recibe del portador aumenta en un 60% adicional."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Crayón de la inocencia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Lágrima de Fagusa","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110311.png","cantidad":4},{"nombre":"Crayón de la inocencia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Vino de Fagusa","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110312.png","cantidad":4},{"nombre":"Pluma creasueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Vino de Fagusa","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110312.png","cantidad":8},{"nombre":"Pluma creasueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Corazón de Fagusa","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110313.png","cantidad":5},{"nombre":"Pincel de los sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Corazón de Fagusa","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110313.png","cantidad":10},{"nombre":"Pincel de los sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23060', 'honkai-star-rail', 'Cuando una estrella ilumina la noche', 'A Star That Lights the Night', '5', 'Erudición', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23060.png', 'Cuando piensa en su infancia, recuerda la primera vez que escuchó las historias de las aventuras de los Trazacaminos.
Su corazoncito latía por los vastos misterios del universo, así que tomó su pincel para esbozar su primera visión del cosmos.
"Una nave cometa, unos raíles estelares, una piloto...".
"Así se pueden trazar caminos, ¿no?".
Pero la maldición retrasó sus pasos y una cama de sanatorio aprisionó su juventud.
En sus momentos de soledad, los libros apilados, los desordenados planos de motores y los botes de pintura vacíos se convirtieron en su día a día.
Su frágil figura movía el pincel, delineando meticulosamente el sueño que anhelaba.
"Tal vez pueda aferrarme a más posibilidades en este tiempo limitado".
"Incluso si es un sueño, merece ser iluminado con colores".
Cuando los astros volvieron a girar, en un abrir y cerrar de ojos, ya había emprendido el camino que lleva a las estrellas.
Portando consigo el deseo que compartía con sus amigos, se convirtió en la persona que siempre soñó ser.
"El viaje trazacaminos comienza en este momento".
El Expreso viaja por el cosmos y las huellas que dejan la piloto y sus compañeros al avanzar juntos forman unos sólidos raíles estelares.
"¡Vayamos juntos al futuro donde residen las estrellas!".', 847, 635, 529, 'Deseo inicial', '["El portador ignora un 32% de la DEF del objetivo al infligirle daño. Cuando el portador lanza la habilidad de apoyo, recupera 6 pts. de energía y obtiene Partida, que dura 2 turnos y se puede acumular hasta 3 veces. Cada acumulación de Partida aumenta el daño de habilidad de apoyo en un 20%. Cuando Partida alcanza 3 acumulaciones, cada acumulación aumenta el daño de habilidad definitiva en un 20%.","El portador ignora un 36% de la DEF del objetivo al infligirle daño. Cuando el portador lanza la habilidad de apoyo, recupera 6 pts. de energía y obtiene Partida, que dura 2 turnos y se puede acumular hasta 3 veces. Cada acumulación de Partida aumenta el daño de habilidad de apoyo en un 25%. Cuando Partida alcanza 3 acumulaciones, cada acumulación aumenta el daño de habilidad definitiva en un 25%.","El portador ignora un 40% de la DEF del objetivo al infligirle daño. Cuando el portador lanza la habilidad de apoyo, recupera 6 pts. de energía y obtiene Partida, que dura 2 turnos y se puede acumular hasta 3 veces. Cada acumulación de Partida aumenta el daño de habilidad de apoyo en un 30%. Cuando Partida alcanza 3 acumulaciones, cada acumulación aumenta el daño de habilidad definitiva en un 30%.","El portador ignora un 44% de la DEF del objetivo al infligirle daño. Cuando el portador lanza la habilidad de apoyo, recupera 6 pts. de energía y obtiene Partida, que dura 2 turnos y se puede acumular hasta 3 veces. Cada acumulación de Partida aumenta el daño de habilidad de apoyo en un 35%. Cuando Partida alcanza 3 acumulaciones, cada acumulación aumenta el daño de habilidad definitiva en un 35%.","El portador ignora un 48% de la DEF del objetivo al infligirle daño. Cuando el portador lanza la habilidad de apoyo, recupera 6 pts. de energía y obtiene Partida, que dura 2 turnos y se puede acumular hasta 3 veces. Cada acumulación de Partida aumenta el daño de habilidad de apoyo en un 40%. Cuando Partida alcanza 3 acumulaciones, cada acumulación aumenta el daño de habilidad definitiva en un 40%."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Crayón de la inocencia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Maqueta del cuerpo celeste","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110291.png","cantidad":4},{"nombre":"Crayón de la inocencia","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Marco galáctico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110292.png","cantidad":4},{"nombre":"Pluma creasueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Marco galáctico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110292.png","cantidad":8},{"nombre":"Pluma creasueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Maqueta del cosmos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110293.png","cantidad":5},{"nombre":"Pincel de los sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Maqueta del cosmos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110293.png","cantidad":10},{"nombre":"Pincel de los sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/116003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23061', 'honkai-star-rail', 'Destelleos silentes', 'Flickering Stars', '5', 'Erudición', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23061.png', 'En el instante en que la energía mágica se desborda, los colores brillantes de las gemas cubren las paredes.
La joven esboza una sonrisa de sorpresa y protege con cuidado los puntos de luz oscilantes.
"¡Lo logré! A partir de ahora, ¿yo también podré convertirme en una gran maga?".
Imagina su futuro como maga y planta la semilla de un deseo en su corazón.
"¡Ánimo, Rin Tohsaka! No basta con triunfar una sola vez, ¡hay que lograrlo innumerables veces!".
"Aunque no sé cómo será el futuro, por ahora, ¡sigue adelante según los deseos de tu corazón!".
En este momento de éxito, sus propias exigencias, las esperanzas de su familia y el peso de sus responsabilidades recaen sobre ella.
La joven se da ánimos en silencio; ya está lista para convertirse en una mejor versión de sí misma.
El camino por delante es largo y arduo, pero un corazón incandescente brilla mucho más que la magia.', 847, 635, 529, 'Brote', '["La Prob. CRIT del portador aumenta en un 18%. Cuando cualquier personaje aliado consume un total de 4 pts. de habilidad básica o más en un mismo turno, el portador obtiene Corona brillante durante 3 turnos. Mientras el portador tiene Corona brillante, el daño que infligen todos los aliados ignora un 20% de la DEF del objetivo, y el daño de habilidad básica que inflige el portador aumenta en un 72%. Los efectos del mismo tipo no se pueden acumular.","La Prob. CRIT del portador aumenta en un 21%. Cuando cualquier personaje aliado consume un total de 4 pts. de habilidad básica o más en un mismo turno, el portador obtiene Corona brillante durante 3 turnos. Mientras el portador tiene Corona brillante, el daño que infligen todos los aliados ignora un 24% de la DEF del objetivo, y el daño de habilidad básica que inflige el portador aumenta en un 84%. Los efectos del mismo tipo no se pueden acumular.","La Prob. CRIT del portador aumenta en un 24%. Cuando cualquier personaje aliado consume un total de 4 pts. de habilidad básica o más en un mismo turno, el portador obtiene Corona brillante durante 3 turnos. Mientras el portador tiene Corona brillante, el daño que infligen todos los aliados ignora un 28% de la DEF del objetivo, y el daño de habilidad básica que inflige el portador aumenta en un 96%. Los efectos del mismo tipo no se pueden acumular.","La Prob. CRIT del portador aumenta en un 27%. Cuando cualquier personaje aliado consume un total de 4 pts. de habilidad básica o más en un mismo turno, el portador obtiene Corona brillante durante 3 turnos. Mientras el portador tiene Corona brillante, el daño que infligen todos los aliados ignora un 32% de la DEF del objetivo, y el daño de habilidad básica que inflige el portador aumenta en un 108%. Los efectos del mismo tipo no se pueden acumular.","La Prob. CRIT del portador aumenta en un 30%. Cuando cualquier personaje aliado consume un total de 4 pts. de habilidad básica o más en un mismo turno, el portador obtiene Corona brillante durante 3 turnos. Mientras el portador tiene Corona brillante, el daño que infligen todos los aliados ignora un 36% de la DEF del objetivo, y el daño de habilidad básica que inflige el portador aumenta en un 120%. Los efectos del mismo tipo no se pueden acumular."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Instinto del ladrón","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111011.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Maqueta del cuerpo celeste","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110291.png","cantidad":4},{"nombre":"Instinto del ladrón","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111011.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Marco galáctico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110292.png","cantidad":4},{"nombre":"Ambición distorsionada","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111012.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Marco galáctico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110292.png","cantidad":8},{"nombre":"Ambición distorsionada","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111012.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Maqueta del cosmos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110293.png","cantidad":5},{"nombre":"Voluntad de conquista","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111013.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Maqueta del cosmos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110293.png","cantidad":10},{"nombre":"Voluntad de conquista","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111013.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23062', 'honkai-star-rail', 'Soy lo que ves', 'I Am As You Behold', '5', 'Destrucción', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23062.png', 'Tesoros, poder, conquista, desafíos... Innumerables fragmentos confusos se proyectan una y otra vez en su mente.
En un instante bajo la luz parpadeante, el rey se bebe el contenido de su copa de un solo trago.
"Tesoros inagotables, tierras sin límites y el poder absoluto en mis manos... Todo lo que merezco pertenece a este rey".
"Pero si eso es todo, ¿qué sentido tiene la vida?".
Su figura perezosa se recuesta en el suave sofá, y todos sus pensamientos se desvanecen al instante como el humo.
De vez en cuando, el rey también debe ceder ante sus deseos y disfrutar de un momento de placer.
"Qué más da lo que se busque o lo que se obtenga. Los momentos en los que la vida late según los dictados del corazón son mis favoritos".', 953, 635, 463, 'A voluntad', '["El ATQ y la recuperación de energía del portador aumentan en un 18% y un 10.0% respectivamente. Cuando el portador lanza su habilidad definitiva, el daño de habilidad definitiva que inflige esta vez aumenta en un 0.20% por cada punto de energía consumido, hasta un máximo del 72%. Al entrar en combate o lanzar su habilidad definitiva, el portador obtiene Diversión del monarca durante 3 turnos. Mientras tiene Diversión del monarca, el Daño CRIT de todos los aliados aumenta en un 24%. Los efectos del mismo tipo no se pueden acumular.","El ATQ y la recuperación de energía del portador aumentan en un 21% y un 12.5% respectivamente. Cuando el portador lanza su habilidad definitiva, el daño de habilidad definitiva que inflige esta vez aumenta en un 0.25% por cada punto de energía consumido, hasta un máximo del 90%. Al entrar en combate o lanzar su habilidad definitiva, el portador obtiene Diversión del monarca durante 3 turnos. Mientras tiene Diversión del monarca, el Daño CRIT de todos los aliados aumenta en un 30%. Los efectos del mismo tipo no se pueden acumular.","El ATQ y la recuperación de energía del portador aumentan en un 24% y un 15.0% respectivamente. Cuando el portador lanza su habilidad definitiva, el daño de habilidad definitiva que inflige esta vez aumenta en un 0.30% por cada punto de energía consumido, hasta un máximo del 108%. Al entrar en combate o lanzar su habilidad definitiva, el portador obtiene Diversión del monarca durante 3 turnos. Mientras tiene Diversión del monarca, el Daño CRIT de todos los aliados aumenta en un 36%. Los efectos del mismo tipo no se pueden acumular.","El ATQ y la recuperación de energía del portador aumentan en un 27% y un 17.5% respectivamente. Cuando el portador lanza su habilidad definitiva, el daño de habilidad definitiva que inflige esta vez aumenta en un 0.35% por cada punto de energía consumido, hasta un máximo del 126%. Al entrar en combate o lanzar su habilidad definitiva, el portador obtiene Diversión del monarca durante 3 turnos. Mientras tiene Diversión del monarca, el Daño CRIT de todos los aliados aumenta en un 42%. Los efectos del mismo tipo no se pueden acumular.","El ATQ y la recuperación de energía del portador aumentan en un 30% y un 20.0% respectivamente. Cuando el portador lanza su habilidad definitiva, el daño de habilidad definitiva que inflige esta vez aumenta en un 0.40% por cada punto de energía consumido, hasta un máximo del 144%. Al entrar en combate o lanzar su habilidad definitiva, el portador obtiene Diversión del monarca durante 3 turnos. Mientras tiene Diversión del monarca, el Daño CRIT de todos los aliados aumenta en un 48%. Los efectos del mismo tipo no se pueden acumular."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Núcleo apagado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Brillo del cruce real","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110281.png","cantidad":4},{"nombre":"Núcleo apagado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Volauto del jaque universal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110282.png","cantidad":4},{"nombre":"Núcleo reluciente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Volauto del jaque universal","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110282.png","cantidad":8},{"nombre":"Núcleo reluciente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Bufón soberano multicolor","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110283.png","cantidad":5},{"nombre":"Núcleo serpenteante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Bufón soberano multicolor","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110283.png","cantidad":10},{"nombre":"Núcleo serpenteante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23063', 'honkai-star-rail', 'Levántate y canta', 'Rise and Sing', '5', 'Memoria', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23063.png', 'El agua del mar le cubre los tobillos y la espuma se rompe bajo la luz de la luna. En un raro descanso del rodaje, la joven acude a la playa tras ser invitada a una pequeña fiesta alrededor de una fogata.
La luz del fuego alarga las sombras de los niños, cuyas caritas reflejan confusión. "No sé cantar", "No canto bien", "No me atrevo a cantar"... Los niños la miran y dicen con timidez: "Señorita Robin, ¿qué hacemos?".
Ella sonríe levemente y roza las cuerdas con la punta de los dedos en lugar de responder.
"Vengan, síganme...".
La brisa marina ahoga el primer punteo de las cuerdas, pero al afinar una segunda vez, el sonido cobra forma. Con las olas rompiendo en la orilla y las luces parpadeando, ella abre los labios para entonar una suave canción, derramando el cielo despejado que lleva en su corazón.
"Cuando no sepan cómo cantar, escuchen la melodía de su propio corazón".
Al principio son solo notas sueltas, pero poco a poco cobra forma y vida. Ella canta y ellos cantan, hasta que los acaricia de paso la brisa veraniega.
"Escuchen, esta es la canción de nuestros corazones. Siempre ha estado ahí, a la espera de ser escuchada".
Ella la escucha y, con dulzura, formula un deseo:
"Levántense a cantar y, luego, abran las alas para volar".', 1164, 582, 397, 'Improvisación', '["Los PV máx. del portador aumentan en un 30%. Después de que el portador lance su habilidad definitiva, los aliados recuperan 1 pt. de habilidad básica. Al entrar en combate, el portador adelanta su acción un 30% y obtiene Nueva melodía durante 2 turnos. Mientras el portador tiene Nueva melodía, la VEL de todos los aliados aumenta en un 20%.","Los PV máx. del portador aumentan en un 38%. Después de que el portador lance su habilidad definitiva, los aliados recuperan 1 pt. de habilidad básica. Al entrar en combate, el portador adelanta su acción un 33% y obtiene Nueva melodía durante 2 turnos. Mientras el portador tiene Nueva melodía, la VEL de todos los aliados aumenta en un 25%.","Los PV máx. del portador aumentan en un 45%. Después de que el portador lance su habilidad definitiva, los aliados recuperan 1 pt. de habilidad básica. Al entrar en combate, el portador adelanta su acción un 35% y obtiene Nueva melodía durante 2 turnos. Mientras el portador tiene Nueva melodía, la VEL de todos los aliados aumenta en un 30%.","Los PV máx. del portador aumentan en un 53%. Después de que el portador lance su habilidad definitiva, los aliados recuperan 1 pt. de habilidad básica. Al entrar en combate, el portador adelanta su acción un 38% y obtiene Nueva melodía durante 2 turnos. Mientras el portador tiene Nueva melodía, la VEL de todos los aliados aumenta en un 35%.","Los PV máx. del portador aumentan en un 60%. Después de que el portador lance su habilidad definitiva, los aliados recuperan 1 pt. de habilidad básica. Al entrar en combate, el portador adelanta su acción un 40% y obtiene Nueva melodía durante 2 turnos. Mientras el portador tiene Nueva melodía, la VEL de todos los aliados aumenta en un 40%."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Componente del acumulador de sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Semilla de la reflexión","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110251.png","cantidad":4},{"nombre":"Componente del acumulador de sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Brote de manas","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110252.png","cantidad":4},{"nombre":"Válvula del flujo de sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Brote de manas","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110252.png","cantidad":8},{"nombre":"Válvula del flujo de sueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Alayawah","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110253.png","cantidad":5},{"nombre":"Motor creasueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Alayawah","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110253.png","cantidad":10},{"nombre":"Motor creasueños","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-23064', 'honkai-star-rail', 'Verano entre olas', 'Summer Rides the Surf', '5', 'Exultación', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/23064.png', 'El agua marina salta sobre la tabla, en la cresta de la ola se abre una brecha turbulenta y la luz del sol se quiebra en millones de esquirlas doradas. Se sube a la tabla de surf y deja que la ola lo lance a lo alto.
"El mar bravo conlleva grandes riesgos, y los grandes riesgos conllevan grandes recompensas".
Compite contra las olas, una y otra vez, situándose de cara al viento y a la marea. La canícula, la luz del sol, el frescor de la brisa marina... Los innumerables nombres, las cifras de pérdidas y ganancias, así como las mentiras y las estratagemas en las miradas ajenas, todo parece convertirse en manchas de colores borrosas que ya no hace falta escudriñar.
"Ya que las olas están aquí, ¿por qué no ver qué son capaces de desencadenar?".
El océano es infinito, al igual que la prosperidad de Astrópolis. Antes de apostar su próxima ficha, se sube a la cresta de la ola y se apuesta a sí mismo, y fija la mirada en ese instante mientras contempla el oleaje desde lo alto.', 953, 582, 529, 'Surcaolas', '["La Prob. CRIT del portador aumenta en un 18%. Cuando el portador lanza una habilidad de Exultación, obtiene Ventolera, que aumenta la VEL del portador en un 24%. Si la habilidad de Exultación lanzada es distinta a la anterior, obtiene además Corriente, que aumenta la Exultación del portador en un 40%.\nAl comienzo de cada oleada o cada vez que el portador lanza 3 veces su habilidad de Exultación, recupera 1 pt. de habilidad básica.","La Prob. CRIT del portador aumenta en un 21%. Cuando el portador lanza una habilidad de Exultación, obtiene Ventolera, que aumenta la VEL del portador en un 28%. Si la habilidad de Exultación lanzada es distinta a la anterior, obtiene además Corriente, que aumenta la Exultación del portador en un 55%.\nAl comienzo de cada oleada o cada vez que el portador lanza 3 veces su habilidad de Exultación, recupera 1 pt. de habilidad básica.","La Prob. CRIT del portador aumenta en un 24%. Cuando el portador lanza una habilidad de Exultación, obtiene Ventolera, que aumenta la VEL del portador en un 32%. Si la habilidad de Exultación lanzada es distinta a la anterior, obtiene además Corriente, que aumenta la Exultación del portador en un 70%.\nAl comienzo de cada oleada o cada vez que el portador lanza 3 veces su habilidad de Exultación, recupera 1 pt. de habilidad básica.","La Prob. CRIT del portador aumenta en un 27%. Cuando el portador lanza una habilidad de Exultación, obtiene Ventolera, que aumenta la VEL del portador en un 36%. Si la habilidad de Exultación lanzada es distinta a la anterior, obtiene además Corriente, que aumenta la Exultación del portador en un 85%.\nAl comienzo de cada oleada o cada vez que el portador lanza 3 veces su habilidad de Exultación, recupera 1 pt. de habilidad básica.","La Prob. CRIT del portador aumenta en un 30%. Cuando el portador lanza una habilidad de Exultación, obtiene Ventolera, que aumenta la VEL del portador en un 40%. Si la habilidad de Exultación lanzada es distinta a la anterior, obtiene además Corriente, que aumenta la Exultación del portador en un 100%.\nAl comienzo de cada oleada o cada vez que el portador lanza 3 veces su habilidad de Exultación, recupera 1 pt. de habilidad básica."]'::jsonb, 'Tirando en el banner de conos de luz del evento, cuando sale destacado', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Jirones de pensamientos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114011.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Guion gráfico hecho a mano de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110261.png","cantidad":4},{"nombre":"Jirones de pensamientos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114011.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Edición conmemorativa de la serialización de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110262.png","cantidad":4},{"nombre":"Fragmento de impresiones","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114012.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Edición conmemorativa de la serialización de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110262.png","cantidad":8},{"nombre":"Fragmento de impresiones","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114012.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Edición de coleccionista de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110263.png","cantidad":5},{"nombre":"Fragmento de deseos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114013.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Edición de coleccionista de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110263.png","cantidad":10},{"nombre":"Fragmento de deseos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/114013.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-24000', 'honkai-star-rail', 'Sobre la caída de un Eón', 'On the Fall of an Aeon', '5', 'Destrucción', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/24000.png', 'Todo comenzó con un rayo de luz.
Uno por uno, cayeron cuando la amenaza de la exterminación se cernía sobre ellos.
Dejaron de autorreplicarse, se abrazaron entre ellos e intentaron ofrecer el derecho a la reproducción a cambio de la posibilidad de que su existencia continuara.
Se tomaron de las manos en una muestra de unidad sin precedentes.
Pero las Vías han llegado a un final abrupto y se dirigen a la auténtica muerte.', 1058, 529, 397, 'Polilla a la luz', '["Cuando el portador lanza un ataque, su ATQ aumenta en un 8% durante esa batalla. Este efecto se puede acumular hasta 4 veces. Cuando el portador rompe la Debilidad del enemigo, el daño que inflige aumenta en un 12% durante 2 turnos.","Cuando el portador lanza un ataque, su ATQ aumenta en un 10% durante esa batalla. Este efecto se puede acumular hasta 4 veces. Cuando el portador rompe la Debilidad del enemigo, el daño que inflige aumenta en un 15% durante 2 turnos.","Cuando el portador lanza un ataque, su ATQ aumenta en un 12% durante esa batalla. Este efecto se puede acumular hasta 4 veces. Cuando el portador rompe la Debilidad del enemigo, el daño que inflige aumenta en un 18% durante 2 turnos.","Cuando el portador lanza un ataque, su ATQ aumenta en un 14% durante esa batalla. Este efecto se puede acumular hasta 4 veces. Cuando el portador rompe la Debilidad del enemigo, el daño que inflige aumenta en un 21% durante 2 turnos.","Cuando el portador lanza un ataque, su ATQ aumenta en un 16% durante esa batalla. Este efecto se puede acumular hasta 4 veces. Cuando el portador rompe la Debilidad del enemigo, el daño que inflige aumenta en un 24% durante 2 turnos."]'::jsonb, 'Se vende en tiendas del juego', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Núcleo apagado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Espada rota","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110111.png","cantidad":4},{"nombre":"Núcleo apagado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Espada inerte","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110112.png","cantidad":4},{"nombre":"Núcleo reluciente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Espada inerte","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110112.png","cantidad":8},{"nombre":"Núcleo reluciente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Espada rompemundos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110113.png","cantidad":5},{"nombre":"Núcleo serpenteante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Espada rompemundos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110113.png","cantidad":10},{"nombre":"Núcleo serpenteante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-24001', 'honkai-star-rail', 'Crucero estelar', 'Cruising in the Stellar Sea', '5', 'Cacería', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/24001.png', 'Navegando por el océano de estrellas, su velocidad es como un rayo arcoíris.
Persigue a las abominaciones no muertas, busca el antídoto contra el tesoro ilusorio, ansía un viaje de liberación.
Su trayecto es como un juramento que nunca se rompe, hasta el infinito.', 953, 529, 463, 'Batida', '["La Prob. CRIT del portador aumenta en un 8%, y su Prob. CRIT contra enemigos que tengan un porcentaje de PV igual o inferior al 50% aumenta en un 8% adicional. Cuando el portador derrota a un enemigo, su ATQ aumenta en un 20% durante 2 turnos.","La Prob. CRIT del portador aumenta en un 10%, y su Prob. CRIT contra enemigos que tengan un porcentaje de PV igual o inferior al 50% aumenta en un 10% adicional. Cuando el portador derrota a un enemigo, su ATQ aumenta en un 25% durante 2 turnos.","La Prob. CRIT del portador aumenta en un 12%, y su Prob. CRIT contra enemigos que tengan un porcentaje de PV igual o inferior al 50% aumenta en un 12% adicional. Cuando el portador derrota a un enemigo, su ATQ aumenta en un 30% durante 2 turnos.","La Prob. CRIT del portador aumenta en un 14%, y su Prob. CRIT contra enemigos que tengan un porcentaje de PV igual o inferior al 50% aumenta en un 14% adicional. Cuando el portador derrota a un enemigo, su ATQ aumenta en un 35% durante 2 turnos.","La Prob. CRIT del portador aumenta en un 16%, y su Prob. CRIT contra enemigos que tengan un porcentaje de PV igual o inferior al 50% aumenta en un 16% adicional. Cuando el portador derrota a un enemigo, su ATQ aumenta en un 40% durante 2 turnos."]'::jsonb, 'Se vende en tiendas del juego', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Núcleo apagado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Flecha del cazabestias","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110121.png","cantidad":4},{"nombre":"Núcleo apagado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Flecha del matademonios","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110122.png","cantidad":4},{"nombre":"Núcleo reluciente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Flecha del matademonios","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110122.png","cantidad":8},{"nombre":"Núcleo reluciente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Flecha del persigueestrellas","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110123.png","cantidad":5},{"nombre":"Núcleo serpenteante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Flecha del persigueestrellas","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110123.png","cantidad":10},{"nombre":"Núcleo serpenteante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-24002', 'honkai-star-rail', 'La textura de los recuerdos', 'Texture of Memories', '5', 'Conservación', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/24002.png', 'El universo era un erial cubierto de basura.
Entre los desechos había algún tesoro que esperaba a que lo descubrieran.
Mira por las rendijas del pasado y elige las semillas de la memoria.
Si brota una nueva vida, su semilla tiene que morir.
Aparecieron piedras preciosas de color rosa, azul y blanco
que relucían en su campo de cultivo, pero el universo se mantuvo en silencio.', 1058, 423, 529, 'Depósito de tesoros', '["La RES a efecto del portador aumenta en un 8%. Cuando el portador recibe un ataque, si no tiene ningún escudo, obtiene uno equivalente al 16% de sus PV máx. durante 2 turnos. Este efecto solo se puede activar 1 vez cada 3 turnos. Cuando el portador tiene un escudo, el daño que recibe se reduce en un 12%.","La RES a efecto del portador aumenta en un 10%. Cuando el portador recibe un ataque, si no tiene ningún escudo, obtiene uno equivalente al 20% de sus PV máx. durante 2 turnos. Este efecto solo se puede activar 1 vez cada 3 turnos. Cuando el portador tiene un escudo, el daño que recibe se reduce en un 15%.","La RES a efecto del portador aumenta en un 12%. Cuando el portador recibe un ataque, si no tiene ningún escudo, obtiene uno equivalente al 24% de sus PV máx. durante 2 turnos. Este efecto solo se puede activar 1 vez cada 3 turnos. Cuando el portador tiene un escudo, el daño que recibe se reduce en un 18%.","La RES a efecto del portador aumenta en un 14%. Cuando el portador recibe un ataque, si no tiene ningún escudo, obtiene uno equivalente al 28% de sus PV máx. durante 2 turnos. Este efecto solo se puede activar 1 vez cada 3 turnos. Cuando el portador tiene un escudo, el daño que recibe se reduce en un 21%.","La RES a efecto del portador aumenta en un 16%. Cuando el portador recibe un ataque, si no tiene ningún escudo, obtiene uno equivalente al 32% de sus PV máx. durante 2 turnos. Este efecto solo se puede activar 1 vez cada 3 turnos. Cuando el portador tiene un escudo, el daño que recibe se reduce en un 24%."]'::jsonb, 'Se vende en tiendas del juego', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Núcleo apagado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Persistencia del bronce","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110141.png","cantidad":4},{"nombre":"Núcleo apagado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Juramento de acero","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110142.png","cantidad":4},{"nombre":"Núcleo reluciente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Juramento de acero","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110142.png","cantidad":8},{"nombre":"Núcleo reluciente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Custodia de ámbar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110143.png","cantidad":5},{"nombre":"Núcleo serpenteante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Custodia de ámbar","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110143.png","cantidad":10},{"nombre":"Núcleo serpenteante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-24003', 'honkai-star-rail', 'Sanación solitaria', 'Solitary Healing', '5', 'Nihilidad', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/24003.png', 'Las cosas moldeadas por las manos del secreto son informes e incorpóreas.
En la totalidad del vacío, existe un sueño repentino.
Aquellos que cortejan la destrucción cosecharán frutos ruinosos, mientras que los que claman por la vida sobrevivirán.
Aquello que se extingue aún puede volver a prenderse, y lo que se ha secado puede llenarse nuevamente.
Compadeciéndose por la salvación del caos, el elixir nutre las sombras.
De espaldas a la oscuridad, entre las estrellas, el encapsulamiento de este recipiente solo puede hacerse en vano.
"Paradójicos son estos saberes, y en ellos refulge la plenitud de nuestro orgullo".', 1058, 529, 397, 'Elixir del caos', '["El efecto de Ruptura del portador aumenta en un 20%. Cuando el portador usa la habilidad definitiva, el Daño con el tiempo que inflige aumenta en un 24% durante 2 turnos. Cuando se elimina a un enemigo afectado por el Daño con el tiempo del portador, el portador recupera 4.0 pts. de energía.","El efecto de Ruptura del portador aumenta en un 25%. Cuando el portador usa la habilidad definitiva, el Daño con el tiempo que inflige aumenta en un 30% durante 2 turnos. Cuando se elimina a un enemigo afectado por el Daño con el tiempo del portador, el portador recupera 4.5 pts. de energía.","El efecto de Ruptura del portador aumenta en un 30%. Cuando el portador usa la habilidad definitiva, el Daño con el tiempo que inflige aumenta en un 36% durante 2 turnos. Cuando se elimina a un enemigo afectado por el Daño con el tiempo del portador, el portador recupera 5.0 pts. de energía.","El efecto de Ruptura del portador aumenta en un 35%. Cuando el portador usa la habilidad definitiva, el Daño con el tiempo que inflige aumenta en un 42% durante 2 turnos. Cuando se elimina a un enemigo afectado por el Daño con el tiempo del portador, el portador recupera 5.5 pts. de energía.","El efecto de Ruptura del portador aumenta en un 40%. Cuando el portador usa la habilidad definitiva, el Daño con el tiempo que inflige aumenta en un 48% durante 2 turnos. Cuando se elimina a un enemigo afectado por el Daño con el tiempo del portador, el portador recupera 6.0 pts. de energía."]'::jsonb, 'Se vende en tiendas del juego', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Núcleo apagado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Obsidiana lúgubre","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110151.png","cantidad":4},{"nombre":"Núcleo apagado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Obsidiana del vacío","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110152.png","cantidad":4},{"nombre":"Núcleo reluciente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Obsidiana del vacío","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110152.png","cantidad":8},{"nombre":"Núcleo reluciente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Obsidiana de la obsesión","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110153.png","cantidad":5},{"nombre":"Núcleo serpenteante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Obsidiana de la obsesión","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110153.png","cantidad":10},{"nombre":"Núcleo serpenteante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-24004', 'honkai-star-rail', 'Cálculo interminable', 'Eternal Calculus', '5', 'Erudición', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/24004.png', 'Suspendida eternamente en el vacío,
fluyen arroyos de datos fulgurantes en su mente.
Convirtiendo todo pasado y futuro en símbolos,
el Eón descifra el fin desde el principio.
Conocimiento, respuestas, verdades...
En la neblina de la información, emerge una luz radiante,
y todo se aclara para ella.', 1058, 529, 397, 'Pensamiento infinito', '["El ATQ del portador aumenta en un 8%. Tras lanzar un ataque, el ATQ aumenta en un 4% adicional por cada enemigo golpeado. Este efecto se puede acumular hasta 5 veces y dura hasta después del siguiente ataque. Si se golpean a 3 o más enemigos, la VEL del portador aumenta en un 8% durante 1 turno.","El ATQ del portador aumenta en un 9%. Tras lanzar un ataque, el ATQ aumenta en un 5% adicional por cada enemigo golpeado. Este efecto se puede acumular hasta 5 veces y dura hasta después del siguiente ataque. Si se golpean a 3 o más enemigos, la VEL del portador aumenta en un 10% durante 1 turno.","El ATQ del portador aumenta en un 10%. Tras lanzar un ataque, el ATQ aumenta en un 6% adicional por cada enemigo golpeado. Este efecto se puede acumular hasta 5 veces y dura hasta después del siguiente ataque. Si se golpean a 3 o más enemigos, la VEL del portador aumenta en un 12% durante 1 turno.","El ATQ del portador aumenta en un 11%. Tras lanzar un ataque, el ATQ aumenta en un 7% adicional por cada enemigo golpeado. Este efecto se puede acumular hasta 5 veces y dura hasta después del siguiente ataque. Si se golpean a 3 o más enemigos, la VEL del portador aumenta en un 14% durante 1 turno.","El ATQ del portador aumenta en un 12%. Tras lanzar un ataque, el ATQ aumenta en un 8% adicional por cada enemigo golpeado. Este efecto se puede acumular hasta 5 veces y dura hasta después del siguiente ataque. Si se golpean a 3 o más enemigos, la VEL del portador aumenta en un 16% durante 1 turno."]'::jsonb, 'Se vende en tiendas del juego', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Núcleo apagado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Bosquejo","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110201.png","cantidad":4},{"nombre":"Núcleo apagado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Esbozo dinámico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110202.png","cantidad":4},{"nombre":"Núcleo reluciente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Esbozo dinámico","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110202.png","cantidad":8},{"nombre":"Núcleo reluciente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Borrador con colores bellos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110203.png","cantidad":5},{"nombre":"Núcleo serpenteante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Borrador con colores bellos","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110203.png","cantidad":10},{"nombre":"Núcleo serpenteante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-24005', 'honkai-star-rail', 'Sobre los recuerdos nunca cae el telón', 'Memory''s Curtain Never Falls', '5', 'Memoria', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/24005.png', 'Desde los más prósperos hasta los más desolados, desde los más fugaces hasta los más duraderos... cada planeta y cada momento están llenos de innumerables eventos.
Esa historia condensada se derrite al tocarla y se convierte en lágrimas que fluyen desde los ojos del mundo.
Algunos se preguntan cuán pesadas serán, y dicen que todo ese tiempo reunido debería bastar para descolorar la eternidad.
Otros se preguntan cuán maravillosas son las historias que cuentan, de tristeza tan límpida y una alegría tan serena, sin una pizca de hipocresía.
El cosmos fluye en silencio y el Eón observa en silencio.
Contempla y espera a que esas historias se conviertan en recuerdos.', 1058, 529, 397, 'Recepción', '["La VEL del portador aumenta en un 6.0%. Después de que el portador lance la habilidad básica, el daño que infligen todos los aliados aumenta en un 8% durante 3 turnos.","La VEL del portador aumenta en un 7.5%. Después de que el portador lance la habilidad básica, el daño que infligen todos los aliados aumenta en un 10% durante 3 turnos.","La VEL del portador aumenta en un 9.0%. Después de que el portador lance la habilidad básica, el daño que infligen todos los aliados aumenta en un 12% durante 3 turnos.","La VEL del portador aumenta en un 10.5%. Después de que el portador lance la habilidad básica, el daño que infligen todos los aliados aumenta en un 14% durante 3 turnos.","La VEL del portador aumenta en un 12.0%. Después de que el portador lance la habilidad básica, el daño que infligen todos los aliados aumenta en un 16% durante 3 turnos."]'::jsonb, 'Se vende en tiendas del juego', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Núcleo apagado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Semilla de la reflexión","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110251.png","cantidad":4},{"nombre":"Núcleo apagado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Brote de manas","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110252.png","cantidad":4},{"nombre":"Núcleo reluciente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Brote de manas","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110252.png","cantidad":8},{"nombre":"Núcleo reluciente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Alayawah","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110253.png","cantidad":5},{"nombre":"Núcleo serpenteante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Alayawah","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110253.png","cantidad":10},{"nombre":"Núcleo serpenteante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","cantidad":8}]}]'::jsonb),
  ('hsr-lc-24006', 'honkai-star-rail', 'Exultación desbordante de bendiciones', 'Elation Brimming With Blessings', '5', 'Exultación', 'https://raw.githubusercontent.com/Mar-7th/StarRailRes/master/image/light_cone_portrait/24006.png', 'Los datos fluyen con fluidez y sin cesar bajo los dedos de los genios.
Las máscaras se ocultan en los intersticios de los "incidentes", observando cada posibilidad que espera impaciente a hacerse realidad.
Analizar, calcular, responder, preguntar... ¿Acaso no es este el escenario de los genios?
Aclamaciones, lágrimas, rugidos, lamentos... Todas las emociones de la vida florecen por completo.
La pantomima es cada vez más ruidosa, y la Exultación se llena a rebosar de bendiciones. ¿Será este el acto más fascinante?
La respuesta sigue siendo la misma: "¡Nadie puede predecirlo!".', 953, 529, 463, 'Apertura', '["El ATQ del portador aumenta en un 20%. Cuando el portador lanza la habilidad básica o la habilidad definitiva sobre un personaje aliado, la Exultación del objetivo aumenta en un 12% durante 2 turnos.","El ATQ del portador aumenta en un 25%. Cuando el portador lanza la habilidad básica o la habilidad definitiva sobre un personaje aliado, la Exultación del objetivo aumenta en un 15% durante 2 turnos.","El ATQ del portador aumenta en un 30%. Cuando el portador lanza la habilidad básica o la habilidad definitiva sobre un personaje aliado, la Exultación del objetivo aumenta en un 18% durante 2 turnos.","El ATQ del portador aumenta en un 35%. Cuando el portador lanza la habilidad básica o la habilidad definitiva sobre un personaje aliado, la Exultación del objetivo aumenta en un 21% durante 2 turnos.","El ATQ del portador aumenta en un 40%. Cuando el portador lanza la habilidad básica o la habilidad definitiva sobre un personaje aliado, la Exultación del objetivo aumenta en un 24% durante 2 turnos."]'::jsonb, 'Se vende en tiendas del juego', '[{"desde":20,"hasta":30,"creditos":5000,"materiales":[{"nombre":"Núcleo apagado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","cantidad":8}]},{"desde":30,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Guion gráfico hecho a mano de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110261.png","cantidad":4},{"nombre":"Núcleo apagado","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111001.png","cantidad":12}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Edición conmemorativa de la serialización de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110262.png","cantidad":4},{"nombre":"Núcleo reluciente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","cantidad":8}]},{"desde":50,"hasta":60,"creditos":50000,"materiales":[{"nombre":"Edición conmemorativa de la serialización de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110262.png","cantidad":8},{"nombre":"Núcleo reluciente","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111002.png","cantidad":12}]},{"desde":60,"hasta":70,"creditos":100000,"materiales":[{"nombre":"Edición de coleccionista de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110263.png","cantidad":5},{"nombre":"Núcleo serpenteante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","cantidad":6}]},{"desde":70,"hasta":80,"creditos":200000,"materiales":[{"nombre":"Edición de coleccionista de Pelosete","icono":"https://sr.yatta.moe/hsr/assets/UI/item/110263.png","cantidad":10},{"nombre":"Núcleo serpenteante","icono":"https://sr.yatta.moe/hsr/assets/UI/item/111003.png","cantidad":8}]}]'::jsonb)
on conflict (id) do update
  set name = excluded.name,
      name_en = excluded.name_en,
      rarity = excluded.rarity,
      category = excluded.category,
      image_url = excluded.image_url,
      description = excluded.description,
      base_hp = excluded.base_hp,
      base_atk = excluded.base_atk,
      base_def = excluded.base_def,
      passive_name = excluded.passive_name,
      passive_levels = excluded.passive_levels,
      how_to_get = coalesce(excluded.how_to_get, public.weapons.how_to_get),
      ascension = excluded.ascension,
      updated_at = now();

-- Comprobacion: 169 conos, ninguno sin icono ni sin pasiva.
select count(*) as total,
       count(*) filter (where image_url is null) as sin_icono,
       count(*) filter (where passive_levels is null) as sin_pasiva,
       count(*) filter (where how_to_get is null) as sin_origen
from public.weapons
where game_id = 'honkai-star-rail';

select category, count(*) as conos
from public.weapons
where game_id = 'honkai-star-rail'
group by category
order by category;
